window.STUDY_DATA = {"scores": [{"subject": "历史", "full": 100.0, "score": 60.0}, {"subject": "地理", "full": 100.0, "score": 51.0}, {"subject": "政治", "full": 100.0, "score": 59.0}, {"subject": "生物", "full": 100.0, "score": 55.0}, {"subject": "化学", "full": 100.0, "score": 31.0}, {"subject": "语文", "full": 150.0, "score": 100.0}, {"subject": "英语", "full": 150.0, "score": 96.5}, {"subject": "物理", "full": 100.0, "score": 61.0}, {"subject": "数学", "full": 150.0, "score": 59.0}], "wrong": [{"subject": "物理", "question_no": "5", "full_score": 6.0, "got_score": 3.0, "student_answer": "BC", "std_answer": "CD", "error_type": "概念混淆", "knowledge_point": "速度与加速度关系：a是速度变化快慢，与v大小无关；a增大v可能减小（反向时）", "note": "卡面3分；按规则含错误选项应0分，待确认", "key": "物理|5|1", "card_type": "concept", "teach": "加速度 a 描述的是速度变化的快慢，和速度 v 本身的大小没有直接关系：刹车瞬间 v 很大但 a 可以很小，起步时 v 很小但 a 可以很大，高速匀速时 v 最大而 a=0。判断 v 增减只看方向：a 与 v 同向，v 增大；a 与 v 反向，v 减小，此时 a 越大 v 减得越快。易混点：a 减小不等于 v 减小——同向时 a 减小只是加得慢了，v 还在增大。抓手：先比方向定增减，再看大小定快慢，两步分开想。", "why": "把加速度大小和速度大小直接挂钩，没先判断 a 与 v 的方向关系就下了结论。", "check_q": "一物体做直线运动，加速度方向与速度方向相反，且加速度大小逐渐增大，它的速度怎样变化？", "check_a": "速度越来越小，而且减小得越来越快（反向减速、减幅增大）。"}, {"subject": "物理", "question_no": "8", "full_score": 6.0, "got_score": 3.0, "student_answer": "AB", "std_answer": "BD", "error_type": "知识盲区", "knowledge_point": "等分位移比例推论：v_B:v_C:v_D:v_E=1:√2:√3:2；中间时刻速度", "note": "卡面3分；按规则含错误选项应0分，待确认", "stem": "如图所示，光滑斜面 AE 被分成长度相等的四段（B、C、D 为分点），一个物体由 A 点静止释放后做匀加速直线运动，下面结论中正确的是（ ）", "paper_cause": "概念不清——把\"相等位移\"误当成\"相等时间\"，以为每段速度增量相同；等位移与等时间两套比例规律混淆。", "key": "物理|8|1", "card_type": "redo", "options": {"A": "经过每一部分时，其速度增量均相同", "B": "物体到达 B、C、D、E 各点的速度大小之比为 1 : √2 : √3 : 2", "C": "物体通过 AB、BC、CD、DE 段所需的时间之比为 1 : √2 : √2 : √3 : 2", "D": "若该物体从 A 点运动到 E 点共用时 4s，则物体在第 2s 末的速度等于 B 点速度"}, "teach": "初速度为零的匀加速有两套比例，别混用：等时间段的位移比是 1:3:5:7；等位移段要用 v²=2ax，速度比 1:√2:√3:2，所以 B 对；每段时间比是 1:(√2−1):(√3−√2):(2−√3)，越走越快、每段用时越来越短。A 错就错在这里：速度增量 Δv=aΔt，每段 Δt 不同，增量依次是 1、√2−1、√3−√2、2−√3，越来越小，不相等。D 的抓手：B 是位移中点，全程位移比 1:4 对应时间比 1:2，总时间 4s 到达 B 恰好是 2s。", "why": "把“相等位移”当成“相等时间”，以为每段速度增量相同，多选了 A，双选含错项归零。", "check_q": "初速度为零的匀加速直线运动，物体通过第 1 段位移末的速度为 v，则通过第 2 段位移末（累计 2 段）的速度是多大？", "check_a": "√2 v。因为 v² 与位移成正比，位移变成 2 倍，速度变成 √2 倍。"}, {"subject": "物理", "question_no": "9空1", "full_score": 2.0, "got_score": 0.0, "student_answer": "7.5", "std_answer": "7.2", "error_type": "概念混淆", "knowledge_point": "前\"一半路程\"的平均速度≠算术平均，v=2v₁v₂/(v₁+v₂)=7.2", "note": "", "stem": "一物体做直线运动，它经过前一半路程的平均速度为 6 m/s，经过后一半路程的平均速度为 9 m/s，求物体全过程的平均速度。（原卷第 9 题，只做前一半路程这一问）", "paper_cause": "概念不清——等路程平均速度不能用算术平均代替，本质上是不理解平均速度等于总位移比总时间。", "key": "物理|9空1|1", "card_type": "redo", "teach": "平均速度只有一个定义：总位移÷总时间，不存在“把两个平均速度再平均”的道理。等路程时两段路程相同，但慢的那段耗时更长、在总时间里权重更大，所以结果偏向慢速，必须用调和平均：v̄=2v₁v₂/(v₁+v₂)=2×6×9÷(6+9)=7.2 m/s。只有等时间时，两段时间相同，才可以直接算术平均 (v₁+v₂)/2。抓手：看到“一半路程”先分别写 t=s/v 求两段时间，别凭感觉取中点。", "why": "把等路程平均速度按算术平均 (6+9)÷2=7.5 算了，忘了慢段耗时更长。", "check_q": "前一半路程速度为 4 m/s、后一半路程速度为 12 m/s，全程平均速度是多少？", "check_a": "2×4×12÷(4+12)=6 m/s（不是算术平均的 8 m/s）。"}, {"subject": "物理", "question_no": "10空2", "full_score": 2.0, "got_score": 0.0, "student_answer": "3", "std_answer": "−3", "error_type": "概念混淆", "knowledge_point": "坐标变化量Δx=x末−x初=0−3=−3（含符号）", "note": "", "stem": "某物体沿 x 轴做直线运动，其位置坐标随时间的变化规律为：0~1s 坐标由 2m 升到 3m，1~3s 保持 3m 不变，3~4s 降到 0m。求第 4s 内物体坐标的变化量 Δx。（原卷第 10 题的其中一空）", "paper_cause": "概念不清——平均速度是矢量，第 4s 内物体反向运动，平均速度应带方向（负号）；她算出的 0.6 与任何正确量都不对应，", "key": "物理|10空2|1", "card_type": "redo", "teach": "坐标变化量 Δx=x末−x初，必须带符号算：第 4s 内坐标从 3m 变到 0m，Δx=0−3=−3 m，负号表示沿 x 轴负方向运动。易混点：“变化量”问的是位移（矢量），不是路程——这 1 秒内路程是 3m，位移是 −3m，问法不同答案不同。抓手：凡是 Δ 开头的量（Δx、Δv）都先定正方向、用“末减初”，符号会自己出来；千万不要先算大小再回头猜符号，那一步最容易丢分。", "why": "只写了大小 3，没按“末坐标减初坐标”带符号计算，丢了负号。", "check_q": "物体坐标从 −2m 变到 5m，坐标变化量 Δx 是多少？", "check_a": "Δx=5−(−2)=7 m。"}, {"subject": "物理", "question_no": "10空4", "full_score": 2.0, "got_score": 0.0, "student_answer": "0.5", "std_answer": "−3", "error_type": "知识盲区", "knowledge_point": "x-t图像斜率=速度：第4s内3→0，v=−3m/s", "note": "", "stem": "某物体沿 x 轴做直线运动，其位置坐标随时间的变化规律为：0~1s 坐标由 2m 升到 3m，1~3s 保持 3m 不变，3~4s 降到 0m。求第 4s 内物体的平均速度。（原卷第 10 题的其中一空）", "paper_cause": "概念不清——平均速度是矢量，第 4s 内物体反向运动，平均速度应带方向（负号）；她算出的 0.6 与任何正确量都不对应，", "key": "物理|10空4|1", "card_type": "redo", "teach": "平均速度 v̄=Δx/Δt，是矢量：第 4s 内 Δx=0−3=−3 m，Δt=1 s，所以 v̄=−3 m/s。在 x-t 图像上，某段时间内的平均速度就是这段图线的斜率，图线下降，斜率为负、大小是 3。易混点：平均速度不等于平均速率——这 1s 内路程是 3m，平均速率是 3 m/s（正值），但平均速度必须带方向符号。抓手：先算带符号的 Δx，再除以时间，方向自动跟着符号走。", "why": "填了约 0.5，把路程和时间乱配相除，既没用 Δx 也没带方向。", "check_q": "x-t 图中物体 2s 时坐标为 6m，4s 时坐标为 2m，2~4s 内平均速度是多少？", "check_a": "(2−6)÷2=−2 m/s，负号表示沿负方向运动。"}, {"subject": "物理", "question_no": "11空3", "full_score": 2.0, "got_score": 0.0, "student_answer": "0.21", "std_answer": "0.14", "error_type": "计算失误", "knowledge_point": "a=Δv/Δt，时间Δt代入错误", "note": "", "stem": "用气垫导轨和光电门测物体的加速度：遮光板宽度为 2.0cm，通过第一个光电门的时间为 0.25s，通过第二个光电门的时间为 0.04s，遮光条从开始遮住第一个光电门到开始遮住第二个光电门的时间为 3s。求滑块的加速度 a。（结果保留两位小数；原卷第 11 题，只做加速度这一空）", "paper_cause": "计算失误——方法本身对（速度两空全对），最后一步除法算错。", "key": "物理|11空3|1", "card_type": "redo", "teach": "光电门测速的原理是“用很短时间内的平均速度代替瞬时速度”：v=遮光板宽÷遮光时间，所以 v₁=0.02÷0.25=0.08 m/s，v₂=0.02÷0.04=0.50 m/s。加速度回到定义式 a=Δv/Δt=(v₂−v₁)/t，这里的 t 是滑块在两门之间运动的过程时间 3s，不是任何一个遮光时间：a=(0.50−0.08)÷3=0.14 m/s²。抓手：定义式题目不玩变形，认准“速度的变化量÷对应的时间间隔”，先把每个时间到底指哪一段标清楚再代入。", "why": "两个速度都算对了，最后把速度差除错了时间（约除以 2），得到 0.21。", "check_q": "滑块通过两个光电门的速度分别为 0.20 m/s 和 0.80 m/s，中间历时 2s，加速度是多少？", "check_a": "a=(0.80−0.20)÷2=0.30 m/s²。"}, {"subject": "物理", "question_no": "12(2)a", "full_score": 2.0, "got_score": 0.0, "student_answer": "4.05", "std_answer": "0.81", "error_type": "审题偏差", "knowledge_point": "漏看\"相邻计数点间还有四个计时点未标出\"，T=0.1s误作0.02s（0.81×5=4.05）", "note": "", "stem": "用打点计时器研究小车运动，打点计时器所接电源频率为 50Hz。纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，测得 AB 段 7.10cm、BC 段 9.10cm。求打 B 点时小车的速度 v_B。（结果保留 2 位有效数字；原卷第 12 题第 (2) 问的第一空）", "paper_cause": "概念不清——\"相邻计数点间还有四个计时点未标出\"意味着时间间隔是 0.1s 而非 0.02s，这个关键点没掌握，导致后面", "key": "物理|12(2)a|1", "card_type": "redo", "teach": "纸带题第一件事是定计数周期：打点周期是 1/50=0.02s，“相邻计数点间还有四个计时点未标出”意味着两个计数点之间隔了 5 个打点周期，T=5×0.02=0.1s。她当时把 T 当成 0.02s，结果恰好放大 5 倍（4.05=0.81×5）。第二件事：匀变速运动中，中间时刻的瞬时速度等于这段的平均速度，v_B=(AB+BC)÷2T=(0.0710+0.0910)÷0.2=0.81 m/s。抓手：看到“还有 n 个点未标出”，先写 T=(n+1)×0.02s 再动笔算。", "why": "漏看“还有四个计时点未标出”，把计数周期 0.1s 当成 0.02s，速度放大了 5 倍。", "check_q": "50Hz 打点计时器，相邻计数点间还有 2 个计时点未标出，计数周期是多少？", "check_a": "T=(2+1)×0.02=0.06 s。"}, {"subject": "物理", "question_no": "12(2)b", "full_score": 2.0, "got_score": 0.0, "student_answer": "0.50", "std_answer": "2.0", "error_type": "知识盲区", "knowledge_point": "逐差法求加速度未掌握", "note": "", "stem": "用打点计时器研究小车运动，打点计时器所接电源频率为 50Hz。纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，测得 AB 段 7.10cm、BC 段 9.10cm。求小车运动的加速度 a。（结果保留 2 位有效数字；原卷第 12 题第 (2) 问的第二空）", "paper_cause": "概念不清——\"相邻计数点间还有四个计时点未标出\"意味着时间间隔是 0.1s 而非 0.02s，这个关键点没掌握，导致后面", "key": "物理|12(2)b|1", "card_type": "redo", "teach": "匀变速纸带求加速度用位移差公式 Δx=aT²：相邻相等时间内的位移之差恒定。先定 T：还有四个点未标出，T=5×0.02=0.1s（这一步错，后面全错）。再算 a=(x_BC−x_AB)÷T²=(0.0910−0.0710)÷0.1²=2.0 m/s²。两个注意点：位移要先把 cm 换成 m 再代入；T 要平方。抓手顺序固定：先数点定 T，再写“后段减前段除以 T 的平方”，最后检查单位和数量级（小车加速度一般在零点几到几 m/s²）。", "why": "计数周期取错，逐差法也没用对，a 在 3.56 与 4.56 之间涂改，两个都不对。", "check_q": "纸带上相邻两段位移分别为 5.00cm 和 7.00cm，计数周期 T=0.1s，加速度是多少？", "check_a": "a=(0.0700−0.0500)÷0.01=2.0 m/s²。"}, {"subject": "物理", "question_no": "13(1)", "full_score": 4.0, "got_score": 0.0, "student_answer": "2m/s", "std_answer": "18m/s", "error_type": "概念混淆", "knowledge_point": "速度变化量的矢量性：反向踢回，Δv=8−(−10)=18m/s", "note": "", "stem": "一质量为 0.4kg 的足球，以 10 m/s 的速度迎面飞来，足球守门员将球以 8 m/s 的速度反向踢出，守门员与球接触的时间为 0.1s。求足球在与守门员接触的这段时间内的速度变化量大小。（原卷第 13 题第 (1) 问）", "paper_cause": "概念不清——速度变化量要按矢量处理、反向必须带负号，这一点没建立起来，整题无从下笔（方法不会为次因）。", "key": "物理|13(1)|1", "card_type": "redo", "teach": "速度是矢量，速度变化量 Δv 必须先定正方向、带符号再相减。取来球方向为正方向：初速度 v₀=+10 m/s，被反向踢出后 v=−8 m/s，Δv=v−v₀=−8−10=−18 m/s，大小为 18 m/s。记忆抓手：“反向相减变相加”——末速度与初速度方向相反时，变化量的大小等于两者大小之和 10+8=18，而不是 10−8=2。凡遇到掉头、反弹、反向踢出，先给反方向的速度挂上负号，再套 Δv=v−v₀，这一步立住整题就立住了。", "why": "把速度变化量当标量算成 10−8=2，没给反向踢出的速度带负号。", "check_q": "小车以 6 m/s 向东行驶，碰墙后以 4 m/s 向西返回，速度变化量的大小是多少？", "check_a": "取向东为正，Δv=−4−6=−10 m/s，大小为 10 m/s。"}, {"subject": "物理", "question_no": "13(2)", "full_score": 4.0, "got_score": 4.0, "student_answer": "20m/s²", "std_answer": "180m/s²", "error_type": "连带错误", "knowledge_point": "加速度定义式a=Δv/Δt列对，但Δv代入错误", "note": "卡面13题计4分，约2分为教师裁量", "stem": "一质量为 0.4kg 的足球，以 10 m/s 的速度迎面飞来，足球守门员将球以 8 m/s 的速度反向踢出，守门员与球接触的时间为 0.1s。已知这段时间内速度变化量 Δv=−18 m/s（取来球方向为正），求足球的平均加速度大小。（原卷第 13 题第 (2) 问）", "paper_cause": "概念不清——速度变化量要按矢量处理、反向必须带负号，这一点没建立起来，整题无从下笔（方法不会为次因）。", "key": "物理|13(2)|1", "card_type": "redo", "teach": "平均加速度 a=Δv/Δt，代入的是带符号的速度变化量：a=−18÷0.1=−180 m/s²，大小 180 m/s²，方向与 Δv 相同，即守门员对球的施力方向。注意两点：题目问“大小”时最后报正数，但列式必须先带符号算；另外 Δv 是这一问的命根子，上一问 Δv 错一位，这一问 a 跟着错一位（她当时 Δv 取 2，a 就成了 20）。抓手：连环小题要分步落纸，第一问的 Δv 单独写一行算清、检查方向，再代入第二问。", "why": "定义式列对了，但代入了上一问错误的 Δv=2，加速度跟着算成 20 m/s²，连带丢分。", "check_q": "某物体速度在 0.2s 内由 +5 m/s 变为 −15 m/s，平均加速度大小是多少？", "check_a": "Δv=−15−5=−20 m/s，a=−20÷0.2=−100 m/s²，大小 100 m/s²。"}, {"subject": "物理", "question_no": "14(2)", "full_score": 6.0, "got_score": 4.0, "student_answer": "2m/s", "std_answer": "20m/s", "error_type": "计算失误", "knowledge_point": "v-t面积=位移=1500m正确，但1500/75=20算成2", "note": "", "key": "物理|14(2)|1", "card_type": "concept", "teach": "v-t 图像题的两把钥匙：图线斜率是加速度，图线与时间轴围成的面积是位移。她这道题面积算对了，总位移 1500m，最后平均速度=总位移÷总时间=1500÷75=20 m/s，却把商写成了 2，纯粹是除法错位。防这类错靠量级检查：75 秒走了 1500m，速度必然在十几到二十几 m/s，若写出 2 m/s（比步行还慢）应当场警觉重算。记住平均速度只认定义，与图线是直是弯无关，先求总位移再除总时间。", "why": "位移 1500m 算对了，最后一步 1500÷75 算错一位得 2，交卷前没做量级检查。", "check_q": "某物体在 0~50s 内的总位移为 1000m，它的平均速度是多大？", "check_a": "1000÷50=20 m/s。"}, {"subject": "物理", "question_no": "15(1)", "full_score": 4.0, "got_score": 1.0, "student_answer": "12m/s（无公式）", "std_answer": "12m/s", "error_type": "表述不规范", "knowledge_point": "v=v₀+at公式分（2分）丢了，只拿结果分", "note": "", "stem": "以 18 m/s 的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为 6 m/s²。求汽车在刹车 1s 末的速度。（原卷第 15 题第 (1) 问）", "paper_cause": "方法不会——刹车类问题\"先求停止时间、再分段套公式\"的基本套路没有建立，16 分大题整题放弃；停止时间判断缺失是最核心的", "key": "物理|15(1)|1", "card_type": "redo", "teach": "刹车题有固定开局：先算停止时间 t₀=v₀/a=18÷6=3s，之后每个问题都拿所问时间跟 3s 比较。1s 小于 3s，车还在运动，直接用速度公式 v=v₀−at=18−6×1=12 m/s。再提醒一个规范问题：她这问结果算对了，却只写结果没写公式，公式分丢了——解答题评分是“公式+代入+结果+单位”四件齐全才给满分，哪怕口算得出也要把 v=v₀−at 写出来。抓手：刹车题第一行永远先写 t₀。", "why": "结果 12 m/s 算对了，但没写公式，只拿到结果分，公式分被丢掉。", "check_q": "汽车以 20 m/s 刹车，加速度大小为 5 m/s²，它的停止时间是多少？", "check_a": "t₀=v₀/a=20÷5=4 s。"}, {"subject": "物理", "question_no": "15(2)", "full_score": 5.0, "got_score": 0.0, "student_answer": "18m", "std_answer": "24m", "error_type": "知识盲区", "knowledge_point": "匀减速位移公式 x=v₀t−½at² 不会用，拼凑答案", "note": "", "stem": "以 18 m/s 的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为 6 m/s²。求汽车在刹车 2s 内的位移。（原卷第 15 题第 (2) 问）", "paper_cause": "方法不会——刹车类问题\"先求停止时间、再分段套公式\"的基本套路没有建立，16 分大题整题放弃；停止时间判断缺失是最核心的", "key": "物理|15(2)|1", "card_type": "redo", "teach": "先比时间：停止时间 t₀=18÷6=3s，2s 小于 3s，车在这 2s 内一直在动，可以放心套位移公式 x=v₀t−½at²=18×2−½×6×2²=36−12=24 m。记公式的抓手：“初速乘时间，减去半 a t 方”——匀减速的位移就是匀速位移减掉被加速度吃掉的那部分。再教一个验算招：2s 末速度是 6 m/s，平均速度 (18+6)÷2=12 m/s，位移 12×2=24 m，两种算法对上才落笔。她当时拼凑出 18m，就是公式没记牢靠蒙。", "why": "匀减速位移公式不会用，靠拼凑得了 18m。", "check_q": "初速度 10 m/s、加速度大小 2 m/s² 的匀减速运动，3s 内的位移是多少？（停止时间 5s，未停）", "check_a": "x=10×3−½×2×3²=30−9=21 m。"}, {"subject": "物理", "question_no": "15(3)", "full_score": 7.0, "got_score": 0.0, "student_answer": "24m", "std_answer": "27m", "error_type": "审题偏差/知识盲区", "knowledge_point": "**刹车陷阱**：未先算停止时间t₀=v₀/a=3s，直接代t=4s", "note": "", "stem": "以 18 m/s 的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为 6 m/s²。求汽车在刹车 4s 内的位移。（原卷第 15 题第 (3) 问）", "paper_cause": "方法不会——刹车类问题\"先求停止时间、再分段套公式\"的基本套路没有建立，16 分大题整题放弃；停止时间判断缺失是最核心的", "key": "物理|15(3)|1", "card_type": "redo", "teach": "这是刹车题的标准陷阱，必须先算停止时间再套公式：t₀=v₀/a=18÷6=3s。所问的 4s 大于 3s，车在第 3s 末已经停下，第 4 秒整段是静止的，位移只能按 3s 算：x=v₀²/(2a)=18²÷(2×6)=27 m。她直接把 t=4 代入公式得 24m——位移公式默认车全程在运动，车停了以后公式继续算会让车“倒退”，结果甚至不比 2s 内的位移大，一眼就该看出荒谬。铁律：所问时间超过 t₀，一律用 t₀ 代入，或直接用 v₀²/2a。", "why": "没先算停止时间，直接把 t=4s 套进位移公式得 24m，正中刹车陷阱。", "check_q": "汽车以 15 m/s 刹车，加速度大小 5 m/s²，求刹车 5s 内的位移。", "check_a": "停止时间 t₀=15÷5=3s，小于 5s，x=15²÷(2×5)=22.5 m。"}, {"subject": "生物", "question_no": "1", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "细胞学说被列入19世纪自然科学的三大发现之一。下列相关叙述正确的是（ ）①认为动、植物都是由细胞发育而来的 ②认为新细胞是由老细胞分裂产生的 ③把动植物分为真核细胞和原核细胞 ④主要阐明了动物和植物的统一性 ⑤揭示了生物界和非生物界的统一性 ⑥使生物学研究进入分子水平", "paper_cause": "概念不清", "key": "生物|1|1", "card_type": "redo", "options": {"A": "①③⑤⑥", "B": "①②④", "C": "①②③④⑥", "D": "①②③⑤"}, "teach": "细胞学说只讲三件事：一切动植物都由细胞发育而来、细胞是一个相对独立的单位、新细胞由老细胞分裂产生；它的意义是揭示动植物的统一性（④对），使生物学研究进入细胞水平。三个高频陷阱要划清：细胞学说不涉及真核/原核分类（③错，那是后来按细胞结构分的）；揭示的是生物界内部的统一性，不是生物界与非生物界之间（⑤错）；进入的是细胞水平不是分子水平（⑥错，分子水平始于DNA双螺旋发现）。只含①②④的B才对。", "why": "没把细胞学说的内容清单记死，③⑤⑥每个都觉得“好像说过”就全放进了选项。", "check_q": "“细胞学说使生物学研究进入分子水平”这句话错在哪里？", "check_a": "应为进入细胞水平；分子水平始于20世纪DNA双螺旋结构的发现。"}, {"subject": "生物", "question_no": "3", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "生物学实验常呈现“五颜六色”的变化。下列实验中溶液颜色变化叙述正确的是（ ）", "paper_cause": "概念不清", "key": "生物|3|1", "card_type": "redo", "options": {"A": "在氨基酸溶液中加入双缩脲试剂，混匀后变成紫色", "B": "在淀粉溶液中加入碘液，混匀后变成蓝色", "C": "在花生匀浆中加入苏丹III染液，混匀后由橘黄色变成红色", "D": "在新鲜的梨汁中加入斐林试剂，混匀后在加热条件下由无色变成砖红色"}, "teach": "显色反应按“试剂本身颜色＋反应后颜色”成对记：双缩脲试剂检测的是蛋白质（含肽键）呈紫色，氨基酸没有肽键，加进去不变紫，A错；淀粉遇碘变蓝，B对；苏丹III染液本身就是橘黄色，它把脂肪染成橘黄色，C说“变成红色”错了（染成红色的是苏丹IV），错在方向；斐林试剂本身是浅蓝色而不是无色，D错在起点颜色，且斐林试剂必须水浴加热才出现砖红色沉淀。四个选项里只有B的起点、终点颜色全对。", "why": "选了C，把苏丹III染脂肪的颜色记反了——苏丹III是橘黄色，红色是苏丹IV。", "check_q": "检测花生种子中的脂肪用苏丹III染液，脂肪颗粒被染成什么颜色？", "check_a": "橘黄色（若用苏丹IV染液则为红色）。"}, {"subject": "生物", "question_no": "6", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "细胞是生命活动的基本单位，下列事实或证据不符合这一观点的是（ ）", "paper_cause": "概念不清", "key": "生物|6|1", "card_type": "redo", "options": {"A": "变形虫是单细胞生物，能进行摄食与运动", "B": "荷花的生长和发育离不开细胞的分裂和分化", "C": "当敌害来临时，丹顶鹤惊飞需要一系列细胞协同配合", "D": "离体的叶绿体在一定条件下能释放氧气"}, "teach": "这道题问“不符合”，要找的是反例。A、B、C都是正面证据：变形虫靠一个细胞完成摄食和运动，荷花的生长发育靠细胞分裂和分化，丹顶鹤惊飞靠一系列细胞协同配合，全都在说生命活动离不开细胞。D是陷阱：离体的叶绿体已经脱离了完整细胞，却还能进行光合作用放出氧气，说明某些生命活动可以在没有完整细胞的情况下进行，恰恰与观点唱反调。破题抓手：看到“不符合、例外”，先锁定那个“脱离细胞还能活动”的选项。", "why": "选了C，没看出C仍是细胞协同配合的正面例证，漏掉了D这个真正的反例。", "check_q": "“离体线粒体在适宜条件下能消耗氧气”，这支持还是违背“细胞是生命活动的基本单位”？", "check_a": "构成例外（违背）：它脱离完整细胞仍能进行呼吸作用。"}, {"subject": "生物", "question_no": "12", "full_score": 2.0, "got_score": 0.0, "student_answer": "D", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "生物|12|1", "card_type": "concept", "teach": "病毒是本章最爱考的分类陷阱：病毒没有细胞结构，只由蛋白质外壳和内部的一种核酸（DNA或RNA）构成，它既不属于原核生物，也不属于真核生物，是单独一类。病毒没有独立代谢的能力，必须寄生在活细胞内才能增殖，离开细胞就只是没有生命的化学物质。判断抓手：凡是说“病毒有细胞膜、核糖体、能独立代谢”的全错；诺如病毒、噬菌体、HIV都一样无细胞结构。原核生物指的是细菌、蓝藻这类有细胞但无核膜的生物，病毒不在其中。", "why": "把诺如病毒当成了原核生物，没抓住“病毒无细胞结构”这条分界线。", "check_q": "噬菌体属于原核生物吗？它由什么构成？", "check_a": "不属于。病毒无细胞结构，由蛋白质外壳和一种核酸（噬菌体为DNA）构成。"}, {"subject": "生物", "question_no": "17", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "某小组将样液脱色处理后打成匀浆，用斐林试剂鉴定其含糖情况。下列叙述错误的是（ ）", "paper_cause": "概念不清", "key": "生物|17|1", "card_type": "redo", "options": {"A": "脱色处理的目的是为了排除色素等无关变量对实验结果的干扰", "B": "使用斐林试剂时需将甲液和乙液等量混匀后再注入待测样液", "C": "为检测还原糖浓度，可增设多组不同浓度的蔗糖溶液作为颜色对照", "D": "斐林试剂通过简单处理后，也能用于鉴定待测样液中的蛋白质"}, "teach": "本题选“错误”项，逐个验：A脱色是为排除材料自身颜色的干扰，对；B斐林试剂必须甲液、乙液等量混合后立即使用，对；D斐林试剂经简单处理可转化为双缩脲试剂鉴定蛋白质，也是教材结论。C错：蔗糖是非还原糖，与斐林试剂不会产生砖红色反应，做还原糖定量的颜色对照必须用已知浓度的葡萄糖溶液。抓手是还原糖名单，只记三个：葡萄糖、果糖、麦芽糖；蔗糖、淀粉、纤维素都不是还原糖。", "why": "放过了“C用蔗糖作还原糖对照”这个真错误，反而怀疑起B项的正确用法。", "check_q": "下列糖中属于还原糖的是哪一个：蔗糖、淀粉、麦芽糖、纤维素？", "check_a": "麦芽糖。蔗糖、淀粉、纤维素均为非还原糖。"}, {"subject": "生物", "question_no": "18", "full_score": 4.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "生物|18|1", "card_type": "concept", "teach": "蛋白质变性要和水解分清：变性是高温、强酸、强碱、重金属盐等使蛋白质的空间结构被破坏、功能丧失（如高温灭菌、酒精消毒），但肽键并不斷裂，氨基酸的排列顺序不变；肽键断裂是水解，要靠酶或强酸强碱长时间作用。另一个易混点是盐析：加浓盐溶液使蛋白质溶解度降低而析出，空间结构不变，加水还能复溶，是可逆的。抓手：变性动的是“形状”不动肽键，盐析连形状也不动。", "why": "以为蛋白质变性就是肽链被打断，没分清变性（空间结构）与水解（肽键）。", "check_q": "鸡蛋煮熟是蛋白质变性，煮熟过程中肽键断裂了吗？熟蛋能再变回液态吗？", "check_a": "肽键没有断裂（破坏的是空间结构）；变性不可逆，不能变回液态。"}, {"subject": "生物", "question_no": "20", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "某种脑啡肽具有镇痛作用，它的基本组成单位是氨基酸。结合该脑啡肽的结构（由5个氨基酸组成，其中一种氨基酸重复出现），下列叙述正确的是（ ）", "paper_cause": "概念不清", "key": "生物|20|1", "card_type": "redo", "options": {"A": "该分子在合成时，脱去的水分子中的氧来自羧基", "B": "该分子是由5种氨基酸脱水缩合而成，称为五肽", "C": "该分子在合成时，相对分子质量减少90", "D": "该分子经高温加热后不会丧失其功能"}, "teach": "这类题按固定顺序拆：先数个数，再数种类，最后算脱水。脑啡肽含5个氨基酸、1条肽链，是五肽；但数“种类”要看R基——5个氨基酸中甘氨酸重复出现，R基只有4种不同，所以是4种氨基酸，“个数≠种类”是第一陷阱，B错。脱水数＝氨基酸数－肽链数＝5－1＝4，相对分子质量减少4×18＝72，不是90，C错。脱去的水中氧来自羧基，A对。高温会破坏蛋白质空间结构使其失活，D错。", "why": "把“5个氨基酸”直接等同于“5种氨基酸”，没数R基去重，掉进个数与种类的陷阱。", "check_q": "某六肽由6个氨基酸组成，其中亮氨酸出现2次、其余各1次，该肽含几种氨基酸？脱去几个水分子？", "check_a": "5种氨基酸；脱去5个水分子（脱水数＝6－1＝5）。"}, {"subject": "生物", "question_no": "21-(1)", "full_score": 2.0, "got_score": 0.0, "student_answer": "\"有无细胞结构\"（字迹潦草，疑为\"无细胞结构\"）", "std_answer": "有细胞结构", "error_type": "概念混淆", "knowledge_point": "病毒无细胞结构 vs 蓝藻等细胞生物有细胞结构（据答案反推）", "note": "", "stem": "显微镜下观察到的酵母菌、蓝细菌、植物细胞、草履虫、细菌等都是细胞生物，它们与病毒的最大区别是它们具有____。", "paper_cause": "记忆缺失", "key": "生物|21-(1)|1", "card_type": "redo", "teach": "细胞生物与病毒的分界线只有一条：有没有细胞结构。酵母菌、蓝藻、细菌、草履虫无论原核还是真核，都有细胞膜、细胞质和核糖体，是细胞生物；病毒只有蛋白质外壳加核酸，没有细胞结构，必须寄生在活细胞里才能增殖。这类填空先看清主语：问“它们（细胞生物）与病毒的区别”填“具有细胞结构”，问“病毒的特点”才填“无细胞结构”，主语看反、答案就反。", "why": "没看清主语是“它们（细胞生物）”，按病毒的角度作答，方向正好反了。", "check_q": "病毒与细菌最根本的区别是什么？", "check_a": "病毒没有细胞结构；细菌有细胞结构（属于原核细胞）。"}, {"subject": "生物", "question_no": "21-(2)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "BDE", "std_answer": "B、E", "error_type": "粗心多选", "knowledge_point": "原核生物举例，多选了D（据答案反推）", "note": "", "stem": "如图是显微镜下观察到的几种细胞或组织图像（A 光学显微镜视野、D 小肠上皮细胞[部分文字不清]，图中 A-E 为酵母菌、蓝细菌、植物细胞、草履虫、细菌等）。(1)材料中各种生物形态差异很大，从结构上来看，它们与病毒的最大区别是它们＿＿。(2)科学家依据＿＿将细胞分为原核细胞和真核细胞，其中属于原核生物的是＿＿，与真核细胞结构上的统一性表现在都具有＿＿（至少 2 点）。(4)过量繁殖会引起\"水华\"的是＿＿（填标号），该细胞中含有＿＿，因此能利用光能合成有机物，故其是自养生物。", "paper_cause": "记忆缺失", "key": "生物|21-(2)-②|1", "card_type": "concept", "teach": "判断原核生物抓两点。一看名单：细菌（乳酸菌、杆菌、球菌等）、蓝藻（蓝细菌、颤藻、念珠藻）、支原体、衣原体、放线菌。二看反例：酵母菌、草履虫、衣藻以及一切动植物细胞都是真核。原题图中D是小肠上皮细胞，属动物细胞、有成形的细胞核，她多选了D。记忆口诀：“细菌蓝藻支衣放，原核名单就这几家”。特别提醒：带“菌”字的不全是原核（酵母菌、霉菌是真菌，属真核），带“藻”字的也不全（衣藻是真核，只有蓝藻是原核）。", "why": "多选了D，把小肠上皮细胞（真核）也划进了原核生物。", "check_q": "下列哪些是原核生物：乳酸菌、酵母菌、颤藻、草履虫？", "check_a": "乳酸菌和颤藻是原核生物；酵母菌、草履虫是真核生物。"}, {"subject": "生物", "question_no": "21-(2)-③", "full_score": 2.0, "got_score": 2.0, "student_answer": "DNA和细胞膜", "std_answer": "细胞膜、细胞质（或核糖体）、都以DNA作为遗传物质", "error_type": "—（教师给满分；但缺\"细胞质/核糖体\"项，存疑）", "knowledge_point": "细胞的统一性（据答案反推）", "note": "", "stem": "如图是显微镜下观察到的几种细胞或组织图像（A 光学显微镜视野、D 小肠上皮细胞[部分文字不清]，图中 A-E 为酵母菌、蓝细菌、植物细胞、草履虫、细菌等）。(1)材料中各种生物形态差异很大，从结构上来看，它们与病毒的最大区别是它们＿＿。(2)科学家依据＿＿将细胞分为原核细胞和真核细胞，其中属于原核生物的是＿＿，与真核细胞结构上的统一性表现在都具有＿＿（至少 2 点）。(4)过量繁殖会引起\"水华\"的是＿＿（填标号），该细胞中含有＿＿，因此能利用光能合成有机物，故其是自养生物。", "paper_cause": "记忆缺失", "key": "生物|21-(2)-③|1", "card_type": "concept", "teach": "原核细胞与真核细胞的“统一性”要背标准件：都有细胞膜、都有细胞质、都有核糖体、都以DNA为遗传物质。答“至少两点”的空，优先写细胞膜和细胞质或核糖体——只写DNA容易被阅卷按“结构不完整”扣分，她写的“DNA和细胞膜”就漏了细胞质、核糖体。与统一性成对记的是“差异性”：有无以核膜为界限的细胞核，原核细胞只有拟核。统一性写共有结构，差异性只写核，这对概念要成对背。", "why": "只写了DNA和细胞膜，漏掉细胞质、核糖体，统一性的标准表述没背全。", "check_q": "原核细胞与真核细胞的统一性表现在哪几方面（至少写两点）？", "check_a": "都有细胞膜、细胞质和核糖体；都以DNA作为遗传物质（任写两点）。"}, {"subject": "生物", "question_no": "21-(3)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "叶绿体", "std_answer": "藻蓝素和叶绿素", "error_type": "知识盲区", "knowledge_point": "蓝藻含藻蓝素和叶绿素，无叶绿体（典型易错点）", "note": "", "stem": "过量繁殖会引起“水华”的蓝细菌（蓝藻）细胞中含有____（色素），因此能利用光能合成有机物，是自养生物。", "paper_cause": "记忆缺失", "key": "生物|21-(3)-②|1", "card_type": "redo", "teach": "蓝藻能光合作用靠的是色素而不是叶绿体：蓝藻是原核生物，细胞里没有任何叶绿体，它的光合色素是藻蓝素和叶绿素，分布在光合片层上直接吸收光能。这是全章最经典的陷阱——“能光合作用”不等于“有叶绿体”。对比记牢：真核的植物细胞靠叶绿体进行光合作用，原核的蓝藻靠藻蓝素加叶绿素。抓手：原核细胞唯一的细胞器是核糖体，其余一切功能都由细胞膜或细胞质中的成分完成。", "why": "填了“叶绿体”，忘了蓝藻是原核生物、根本没有叶绿体。", "check_q": "蓝藻与水绵都能进行光合作用，它们的光合场所分别是什么？", "check_a": "蓝藻无叶绿体，靠细胞质中的藻蓝素和叶绿素；水绵在叶绿体中进行。"}, {"subject": "生物", "question_no": "22-(1)-①", "full_score": 2.0, "got_score": 0.0, "student_answer": "淀粉", "std_answer": "水", "error_type": "审题偏差/知识盲区", "knowledge_point": "种子晒干失去的主要是水（据答案反推）", "note": "", "stem": "青萝卜细胞多汁、营养丰富。青萝卜细胞中含量最多的化合物是____。", "paper_cause": "记忆缺失", "key": "生物|22-(1)-①|1", "card_type": "redo", "teach": "“含量最多”要先分清问法：活细胞（鲜重）中含量最多的化合物永远是水，约占85%；含量最多的有机物才是蛋白质；干重中含量最多的化合物也是蛋白质。青萝卜是多汁的活细胞，问的又是“化合物”，答案锁定水。她答“淀粉”是把“重要的储能物质”错当成“含量最多的化合物”。抓手三连：鲜重问化合物答水，问有机物答蛋白质，问元素答O（氧）。", "why": "把储能物质淀粉当成了含量最多的化合物，没抓住“活细胞水最多”这条基准线。", "check_q": "种子干重中含量最多的化合物是什么？鲜活细胞中含量最多的元素是什么？", "check_a": "蛋白质；氧（O）。"}, {"subject": "生物", "question_no": "22-(2)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "无机物", "std_answer": "无机盐", "error_type": "概念混淆", "knowledge_point": "无机物包括水和无机盐，此处应为无机盐", "note": "", "stem": "把晒干的小麦种子放在试管中点燃，直至燃成灰烬，此灰烬主要是____。", "paper_cause": "记忆缺失", "key": "生物|22-(2)-②|1", "card_type": "redo", "teach": "种子点燃，烧掉的是有机物——糖类、脂质、蛋白质受热分解成气体散失；剩下的灰烬是烧不掉的部分。而种子里的水在晒干时已经散失，灰烬里不可能有水，所以灰烬只能是无机盐。概念链要分清：无机物包括水和无机盐两类，题目问“灰烬”时水已被排除，答案必须落到无机盐。她答“无机物”范围偏大，阅卷按标准答案给分，这类空要答到最具体的层级。", "why": "答了大概念“无机物”，没缩小到灰烬的实际成分“无机盐”。", "check_q": "晒干种子点燃后的灰烬中还能找到水吗？为什么？", "check_a": "不能。水在晒干时已散失；灰烬只剩无机盐。"}, {"subject": "生物", "question_no": "22-(3)", "full_score": 2.0, "got_score": 2.0, "student_answer": "自由水含量", "std_answer": "自由水与结合水的比例", "error_type": "—（教师给满分；与标准表述有出入，存疑）", "knowledge_point": "细胞代谢强弱的影响因素（据答案反推）", "note": "", "stem": "概念辨析：细胞的代谢强弱与细胞内哪项指标有密切关系？", "paper_cause": "记忆缺失", "key": "生物|22-(3)|1", "card_type": "concept", "teach": "细胞代谢强弱看的不是自由水的绝对含量，而是自由水与结合水的比值：比值越大，自由水相对越多，代谢越旺盛，但抗逆性越差；比值越小，如休眠的种子，代谢弱而抗逆性强。种子晒得不够干就入仓会发热霉烂，就是因为自由水比例高、呼吸作用旺盛放热。她写“自由水含量”意思接近，标准表述应是“自由水与结合水的比值”。配套记：种子萌发时比值上升，晒干储藏时比值下降。", "why": "只答了自由水含量，没写出决定代谢强弱的是自由水与结合水的比值。", "check_q": "休眠的种子和萌发的种子，哪一个自由水/结合水的比值更大？", "check_a": "萌发的种子比值更大（代谢旺盛）；休眠种子比值小、抗逆性强。"}, {"subject": "生物", "question_no": "22-(4)", "full_score": 2.0, "got_score": 0.0, "student_answer": "在细胞中的含量（字迹潦草）", "std_answer": "作为良好溶剂", "error_type": "知识盲区", "knowledge_point": "自由水的功能：良好溶剂、参与反应、运输", "note": "", "stem": "青萝卜细胞多汁，糖等多种物质溶解于水中，这说明细胞中水的功能是____。", "paper_cause": "记忆缺失", "key": "生物|22-(4)|1", "card_type": "redo", "teach": "自由水的功能背三条：①良好的溶剂，许多物质溶解在水中进行运输和反应；②参与化学反应，如光合作用、呼吸作用；③为细胞提供液体环境、运送营养物质和废物。做这类题的方法是先把功能清单背熟，再用题干关键词对号入座：本题题干说的是“溶解于水中”，直接对应第①条“水是细胞内良好的溶剂”。她这空写成了“在细胞中的含量”，把功能题答成了含量题，是审题时没抓“说明水的功能”这个问法。", "why": "没从“溶解”这个关键词对到“良好溶剂”，把功能空答成了含量描述。", "check_q": "血液运送氧气和养料，体现了自由水的哪项功能？", "check_a": "运输功能（运送营养物质和代谢废物）。"}, {"subject": "生物", "question_no": "23-(1)", "full_score": 3.0, "got_score": 0.0, "student_answer": "文字描述\"一个碳原子上至少连接一个氨基和一个羧基\"（未画结构式）", "std_answer": "画出氨基酸结构通式 H2N—C(R)(H)—COOH", "error_type": "审题偏差/表述不规范", "knowledge_point": "氨基酸的结构通式（要求画图，给文字描述得0分）", "note": "", "stem": "画出组成蛋白质的氨基酸的结构通式，并标出R基。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(1)|1", "card_type": "redo", "teach": "氨基酸结构通式必须能默画：一个中心碳原子上连着四样东西——氨基（-NH2）、羧基（-COOH）、氢（-H）和R基。判断一种物质是不是氨基酸就看两条：至少含一个氨基和一个羧基，并且它们连在同一个碳原子上；R基决定氨基酸的种类，21种氨基酸的差别全在R基。这类题题干写“画出”就必须动笔画图并标出R基，只用文字描述结构特点不得分。审题时看到“画出、写出结构式”，要立刻切换到作图模式。", "why": "题目要求画结构通式，她只用文字描述了特点，没作图、没标R基，直接0分。", "check_q": "某分子有一个氨基和一个羧基，但连在不同的碳原子上，它是组成蛋白质的氨基酸吗？", "check_a": "不是。氨基和羧基必须连在同一个碳原子上（中心碳）。"}, {"subject": "生物", "question_no": "23-(3)-②", "full_score": 1.0, "got_score": 0.0, "student_answer": "51", "std_answer": "49", "error_type": "计算失误/概念不清", "knowledge_point": "脱水数=氨基酸数-肽链数（51-2=49，她直接写了氨基酸总数）", "note": "", "stem": "一个牛胰岛素分子由51个氨基酸脱水缩合而成，含2条肽链。求该分子中的肽键数。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(3)-②|1", "card_type": "redo", "teach": "肽键数有一条万能公式：肽键数＝脱去的水分子数＝氨基酸总数－肽链条数。原理是每形成一个肽键就脱去一分子水，而每条肽链内部的连接数比氨基酸数少1，所以有几条链就少几个肽键。牛胰岛素：51－2＝49个肽键。配套公式一起记：每条肽链至少含1个游离氨基和1个游离羧基。她直接把氨基酸总数51填进去，是没理解“肽链条数要减掉”这一步——公式不是死背的，是数连接点数出来的。", "why": "把氨基酸总数51当成了肽键数，没减去肽链条数2。", "check_q": "某蛋白质由100个氨基酸、3条肽链组成，肽键数和脱水数各是多少？", "check_a": "都是97（100－3）。"}, {"subject": "生物", "question_no": "23-(3)-③", "full_score": 2.0, "got_score": 0.0, "student_answer": "882", "std_answer": "888", "error_type": "计算失误", "knowledge_point": "蛋白质相对分子质量计算，有漏项（据答案反推）", "note": "", "stem": "牛胰岛素由51个氨基酸、2条肽链组成，含3个二硫键。求氨基酸形成胰岛素后，相对分子质量比原来减少多少。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(3)-③|1", "card_type": "redo", "teach": "相对分子质量的减少量有两笔账，必须都算：第一笔是脱水缩合，脱去49个水，减少49×18＝882；第二笔是二硫键，每个二硫键由两个-SH脱去2个H形成，减少2，胰岛素有3个二硫键，再减少3×2＝6。合计882＋6＝888。她只算了第一笔得882，漏的正是二硫键这笔小账。抓手：题目只要出现二硫键（-S-S-），相对分子质量计算就要多减“二硫键数×2”；只问肽键数、脱水数时不用管二硫键。", "why": "只算了脱水减少的882，漏掉了3个二硫键形成时脱去的6个H。", "check_q": "某肽链含20个氨基酸、形成1个二硫键，形成后相对分子质量比原来减少多少？", "check_a": "脱水19个减19×18＝342，二硫键减2，合计减少344。"}, {"subject": "生物", "question_no": "23-(4)-②", "full_score": 2.0, "got_score": 0.0, "student_answer": "圈选①④⑥", "std_answer": "②④⑥⑧", "error_type": "知识盲区", "knowledge_point": "氨基酸分类（据答案反推）", "note": "", "stem": "从 1958 年开始，中国科学院上海生物化学研究所、上海有机化学研究所和北京大学三家单位联合攻关，终于在 1965 年人工合成了具有全部生物活性的结晶牛胰岛素。图 a 为牛胰岛素肽链结构示意图，其中的数字为氨基酸序号，二硫键（-S-S-）是由两个巯基（-SH）连接脱去两个 H 而形成的；图 b 是胰岛素部分肽链放大图。(1)氨基酸是组成蛋白质的基本单位，组成人体蛋白质的 21 种氨基酸[以脱水缩合方式连接，不清]。(2)生物体中不同的蛋白质具有不同的生物活性和功能。胰岛素是[胰岛 B 细胞分泌的降低血糖的]一种蛋白质类激素。与结晶牛胰岛素的生物活性有直接关系的选项是（ ）A.胰岛素分子中氨基酸的种类 B.胰岛素分子中二硫键的数目和位置 C.胰岛素分子中肽键的数目 D.胰岛素分子中氨基酸脱水缩合的方式。(3)一个牛胰岛素分子由 51 个氨基酸脱水缩合而成。根据图 a 判断，一个胰岛素分子中含有＿＿条肽链，＿＿个肽键。氨基酸形成胰岛素后，相对分子质量比原来的总相对分子质量减少了＿＿。(4)图 b 中游离的氨基有＿＿个，表示 R 基的序号是＿＿，含有肽键的序号是＿＿。", "paper_cause": "计算失误（第 (3) 问，存疑）；其余空记忆缺失", "key": "生物|23-(4)-②|1", "card_type": "concept", "teach": "在肽链结构图上认三样东西：肽键是氨基酸之间的-CO-NH-连接处，先在图中找到羰基碳与氮相连的位置；R基是每个中心碳上“多出来的”支链——中心碳连的四样东西里氨基、羧基、氢都是固定的，剩下的那个就是R基；游离氨基在肽链一端，若R基里带氨基也要算入。她的圈选漏了两处R基，是把个别中心碳的支链误认成了肽键结构的一部分。认图顺序：先标全部肽键，再逐个中心碳找支链，最后数两端和R基上的游离基团。", "why": "在图中漏认了两个R基，把中心碳的支链和肽键结构混淆了。", "check_q": "一条肽链中游离的氨基至少有几个？它们分布在哪里？", "check_a": "至少1个（在肽链的一端）；若R基中还含有氨基，还要加上R基上的氨基数。"}, {"subject": "生物", "question_no": "24-(1)-③", "full_score": 1.0, "got_score": 0.0, "student_answer": "因为没有对试管进行加热", "std_answer": "因为没有水浴加热", "error_type": "表述不规范", "knowledge_point": "\"水浴\"是关键限定词，直接加热不行", "note": "", "stem": "水熊虫对不良环境有极强的抵抗力。当环境恶化时，水熊虫会处于一种假死状态，代谢率几乎降到零，甚至能耐受 -273℃ 冰冻数小时，直到环境改善为止。据研究，水熊虫进入假死状态时，体内会产生大量海藻糖。(1)若要探究海藻糖是否为还原糖，可加入＿＿试剂鉴定，在海藻糖溶液中加入该试剂没有发生相应的颜色反应，能否说明海藻糖为非还原糖？＿＿为什么？＿＿。(2)有人认为\"水熊虫体液中的海藻糖可以保护组织细胞，使组织细胞免受低温造成的损伤\"，为探究上述假设的真实性，设计了一个实验方案：①为了确保实验的科学性和准确性，从化学组成及生理功能看，实验材料应选择＿＿的动物细胞（多选）A.含有海藻糖 B.不含海藻糖 C.能够合成海藻糖 D.不能合成海藻糖。②操作过程：a.取适量步骤①中选择的动物细胞，等分成甲、乙两组；b.甲组添加含海藻糖的细胞培养液，乙组添加＿＿；c.两组均控制在＿＿条件下数小时；d.观察环境改变后，甲、乙两组细胞的存活率。③预期结果及结论：若＿＿，则假设成立，海藻糖可以保护组织细胞，使其免受低温造成的损伤；若＿＿，则假设不成立。", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(1)-③|1", "card_type": "concept", "teach": "斐林试剂鉴定还原糖的完整条件是“50～65℃水浴加热”，缺了加热这一步，即使溶液里全是葡萄糖也不会出现砖红色沉淀——所以“没有变色”不能推出“不是还原糖”，结论必须建立在操作规范的前提上。她答“因为没有加热”被扣分，是因为少了“水浴”二字：水浴受热均匀、能防止液体暴沸和Cu(OH)2受热分解，直接对试管加热在实验规范里是错误操作。答实验题的原则：条件类答案要写全方式和程度，少一个限定词就少一分。", "why": "答对了“要加热”，却漏了关键限定词“水浴”，表述不规范被扣分。", "check_q": "用斐林试剂鉴定还原糖时，为什么必须水浴加热，不能直接用酒精灯加热试管？", "check_a": "水浴受热均匀、温度可控；直接加热易使液体暴沸溅出，且Cu(OH)2受热分解变黑，干扰颜色观察。"}, {"subject": "生物", "question_no": "24-(2)-①", "full_score": 2.0, "got_score": 0.0, "student_answer": "BC", "std_answer": "BD", "error_type": "知识盲区/审题偏差", "knowledge_point": "实验变量分析（据答案反推：海藻糖低温保护细胞实验）", "note": "", "stem": "为探究海藻糖能否保护细胞免受低温损伤，实验材料应选择怎样的动物细胞（多选）：", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(2)-①|1", "card_type": "redo", "options": {"A": "含有海藻糖", "B": "不含海藻糖", "C": "能够合成海藻糖", "D": "不能合成海藻糖"}, "teach": "实验材料的选择原则是“排除内源干扰”：要研究外加海藻糖有没有用，实验对象本身必须是一张白纸——体内不含海藻糖（B），也不能自己合成海藻糖（D），这样甲组（外加海藻糖）与乙组（不加）之间唯一的差别就是人为添加的海藻糖，自变量干净。如果选C（能够合成），细胞受低温刺激时会自己产生海藻糖，乙组也被污染，实验直接作废。多选题的每个选项都要按“会不会干扰自变量”逐个过一遍，不能只想一层。", "why": "选了“能够合成海藻糖”的C，细胞自己产糖会污染对照组，自变量就不纯了。", "check_q": "研究外源胰岛素对血糖的影响，实验动物应选健康鼠还是糖尿病模型鼠？为什么？", "check_a": "糖尿病模型鼠（自身胰岛素分泌不足），这样外加胰岛素的效果才能单独显现，排除内源胰岛素的干扰。"}, {"subject": "生物", "question_no": "24-(2)-③", "full_score": 2.0, "got_score": 0.0, "student_answer": "相同", "std_answer": "相同的低温", "error_type": "表述不规范", "knowledge_point": "对照条件缺关键限定词\"低温\"", "note": "", "stem": "在海藻糖保护细胞的实验中：甲组添加含海藻糖的培养液，乙组添加等量不含海藻糖的培养液，两组均控制在____条件下数小时，再观察存活率。（填实验条件）", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(2)-③|1", "card_type": "redo", "teach": "对照实验的条件表述要写“全”：本题假设检验的是海藻糖能否抵抗低温损伤，所以处理条件必须是“相同的低温条件”——“相同”保证无关变量一致，“低温”点明假设指向的环境因素，两者缺一不可。她只写“相同”，阅卷认为没答出处理因素。这一坑在实验题里反复出现：凡是“控制在__条件下”的空，都要先把题干假设里的关键环境词（低温、黑暗、适宜光照等）找出来写进去，再补上“相同”等限定词。", "why": "只写了“相同”，漏掉了假设指向的核心条件“低温”。", "check_q": "探究光照对光合作用的影响时，两组装置应分别放在什么条件下？", "check_a": "一组光照、一组黑暗作对照，其余条件（温度、水分等）相同且适宜。"}, {"subject": "生物", "question_no": "24-(2)-⑤", "full_score": 2.0, "got_score": 2.0, "student_answer": "甲乙两组细胞存活率相…（字迹潦草，疑为\"相同/相近\"）", "std_answer": "甲、乙两组细胞的存活率都很低（或基本相等）", "error_type": "—（字迹不清，按最可能的辨认给分）", "knowledge_point": "", "note": "", "stem": "概念辨析：在对照实验中，预期“假设不成立”时的结果应如何规范表述？", "paper_cause": "方法不会  ## 本科小结", "key": "生物|24-(2)-⑤|1", "card_type": "concept", "teach": "实验题的“预期结果及结论”必须会写双向：如果假设成立，甲组（有海藻糖）存活率明显高于乙组；如果假设不成立，甲、乙两组存活率无显著差异。表述要用“明显高于”“无显著差异”这类可比较的语言，不要写“存活率都很低”这种没有对照意义的话。她这空写成存活率相近的意思，老师酌情给了分，但规范写法应是“甲、乙两组细胞的存活率基本相等（无显著差异）”。抓手：预期结果与结论成对出现，假设有几种可能就写几种。", "why": "表述含糊，只写存活率相近，没用“无显著差异”这类规范的对照语言（本题老师酌情给分）。", "check_q": "若实验结果是甲组存活率远高于乙组，应得出什么结论？", "check_a": "海藻糖可以保护组织细胞、使其免受低温造成的损伤，假设成立。"}, {"subject": "化学", "question_no": "1", "full_score": 4.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "化学|1|1", "card_type": "concept", "teach": "实验室安全题抓三条线。一是钠的取用：钠保存在煤油中，剩余的钠必须放回原试剂瓶（钠太活泼，随便丢弃遇水会起火）。二是灭火与存放：钠着火只能用干燥沙土盖灭，泡沫灭火器喷出的水会助长反应；浓硫酸与氢氧化钠一酸一碱不能同橱存放。三是见光易分解的试剂：氯水中的HClO见光分解，必须用棕色细口瓶避光保存，液体用细口瓶而不是广口瓶。逐项过：对象是谁、怕什么、用什么容器。", "why": "把“剩余钠放回原瓶”这个特殊规定当成了错误项，又放过了广口瓶存氯水等细节错误。", "check_q": "实验室里氯水应保存在什么瓶中？金属钠着火用什么灭火？", "check_a": "棕色细口瓶（避光保存）；用干燥的沙土盖灭，不能用水或泡沫灭火器。"}, {"subject": "化学", "question_no": "4", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "key": "化学|4|1", "card_type": "concept", "teach": "钠投入盐溶液，永远先和水反应，这是铁律：2Na＋2H2O＝2NaOH＋H2↑，生成的NaOH再与盐发生复分解。钠投入MgCl2溶液：先得NaOH和H2，NaOH再与MgCl2生成Mg(OH)2白色沉淀，所以现象是浮、熔、游、响加白色沉淀，绝不会置换出金属镁——钠虽活泼，但在水溶液中抢先与水反应。判断抓手：只要环境里有水，钠的第一反应对象就是水，第二步再看生成的碱与盐是否反应。", "why": "按“钠置换镁”的金属活动性思路选错，没走“先水后盐”两步。", "check_q": "把一小块钠投入CuSO4溶液，能看到红色铜析出吗？实际现象是什么？", "check_a": "不能。钠先与水反应放出H2，生成的NaOH与CuSO4生成蓝色Cu(OH)2沉淀；现象为浮、熔、游、响并有蓝色沉淀。"}, {"subject": "化学", "question_no": "7", "full_score": 4.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "氯气与氯水的性质（卷面订正口径）", "note": "", "stem": "下列关于氯气和氯水的说法中正确的是（ ）", "paper_cause": "概念不清", "key": "化学|7|1", "card_type": "redo", "options": {"A": "红热的铁丝在Cl2中剧烈燃烧生成FeCl3", "B": "氯气是一种无色、密度比空气大的有毒气体", "C": "新制氯水能杀菌消毒是因为Cl2有毒，能杀灭细菌", "D": "氯气溶于水后生成的次氯酸见光易分解（据卷面辨认，含错误表述）"}, "teach": "四个选项逐个验：A红热铁丝在Cl2中剧烈燃烧生成FeCl3，正确——Cl2氧化性强，变价金属与Cl2反应一律生成最高价氯化物。B错在颜色：Cl2是黄绿色气体（密度比空气大、有毒这两点对）。C错在主角：新制氯水杀菌消毒靠的是HClO的强氧化性，不是Cl2有毒。抓手：氯气本身黄绿色、有毒；溶于水后真正起漂白消毒作用的是HClO。做这类题先把每个选项的“事实点”单独验真假，别被一句大体眼熟的话带走。", "why": "放过了A项“铁与氯气生成FeCl3”这个确定正确的事实，被表述含糊的D项带偏。", "check_q": "新制氯水能使有色布条褪色，起漂白作用的是哪种物质？氯气是什么颜色？", "check_a": "次氯酸（HClO）；黄绿色。"}, {"subject": "化学", "question_no": "8", "full_score": 4.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "物质的量：微粒数与分子内原子数换算（卷面订正口径）", "note": "", "stem": "下列各物质所含原子数由多到少排列的是（ ）①0.5 mol NH3 ②4 g H2 ③标准状况下0.3 mol CO2 ④0.2 mol H3PO4", "paper_cause": "计算失误", "key": "化学|8|1", "card_type": "redo", "options": {"A": "①④③②", "B": "④③②①", "C": "②③④①", "D": "②①④③"}, "teach": "比较原子数只用一条公式：原子的物质的量＝分子的物质的量×每个分子的原子数。逐个算：①0.5×4＝2 mol；②4 g H2先换成2 mol，再×2＝4 mol；③0.3×3＝0.9 mol；④0.2×8＝1.6 mol（H3PO4一个分子有3个H＋1个P＋4个O共8个原子，别漏数）。由多到少是②①④③。两个易错点：题目给质量的，先除以摩尔质量换成物质的量；数分子内原子数时把每个元素都数全。", "why": "把分子的多少当成了原子的多少，没乘每个分子的原子个数，H2的质量也没先换算成物质的量。", "check_q": "0.4 mol H2SO4和8 g CH4，哪一个含的原子更多？", "check_a": "H2SO4含原子0.4×7＝2.8 mol；8 g CH4是0.5 mol，含原子0.5×5＝2.5 mol，H2SO4更多。"}, {"subject": "化学", "question_no": "9", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "下列说法正确的是（ ）", "paper_cause": "概念不清", "key": "化学|9|1", "card_type": "redo", "options": {"A": "同温、同压下，相同质量的气体都占有相同的体积", "B": "在标准状况下，1 mol任何物质的体积均为22.4 L", "C": "1 mol某气体的体积为22.4 L，该气体所处的状态一定是标准状况", "D": "同温、同压下，相同体积的气体都含有相同数目的分子数"}, "teach": "22.4 L/mol的适用条件要背全三个限定：标准状况（0℃、101 kPa）、1 mol、气体，缺一个都不能用。B错在“任何物质”：固体、液体1 mol的体积远不是22.4 L。A错在“相同质量”：质量相同而摩尔质量不同，物质的量就不同，体积也不同；同温同压下体积只由物质的量决定。C错在反推：改变温度压强，非标况下1 mol气体体积也可以恰好是22.4 L。D是阿伏加德罗定律本身，正确。", "why": "选了B，把22.4 L无条件套到“1 mol任何物质”，丢了“标况＋气体”两个限定词。", "check_q": "标准状况下，1 mol H2O的体积是22.4 L吗？为什么？", "check_a": "不是。标况下水是液体，22.4 L/mol只适用于气体；1 mol水体积约18 mL。"}, {"subject": "化学", "question_no": "10", "full_score": 4.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待定（无题干，需复盘）", "knowledge_point": "未知（需题干）", "note": "", "stem": "用下列实验装置进行相应实验，装置正确且能达到相应实验目的的是（ ）", "paper_cause": "概念不清", "key": "化学|10|1", "card_type": "redo", "options": {"A": "用图甲（饱和NaCl溶液、浓硫酸两洗气瓶）除去Cl2中的HCl并干燥", "B": "用图乙装置进行钠的燃烧实验", "C": "用图丙装置稀释浓硫酸", "D": "用图丁制备二氧化碳"}, "teach": "装置题逐图排查三句话：仪器对不对、试剂对不对、顺序对不对。甲对：除Cl2中的HCl用饱和食盐水（抑制Cl2溶解又能吸收HCl），再用浓硫酸干燥，顺序先除杂后干燥。乙错：钠的燃烧必须在坩埚中进行，不能在普通装置里直接加热钠。丙错：稀释浓硫酸要在烧杯中、酸入水并不断搅拌，绝不能在量筒类容器里操作。丁的装置与药品组合达不到制CO2目的。逐图排除，只剩甲。", "why": "选了D项制CO2装置，放过了甲图“先饱和食盐水除HCl、再浓硫酸干燥”这个标准组合。", "check_q": "除去Cl2中混有的HCl并干燥，两个洗气瓶应依次装什么试剂？", "check_a": "先饱和食盐水（除HCl），后浓硫酸（干燥）。"}, {"subject": "化学", "question_no": "11-(1)", "full_score": 2.0, "got_score": 0.0, "student_answer": "4Na+O2=Na2O（自加不明条件\"R△\"）", "std_answer": "重建：2Na+O2=点燃=Na2O2", "error_type": "产物错误", "knowledge_point": "钠与氧气反应：条件决定产物（常温Na2O/加热Na2O2），据答案反推", "note": "", "key": "化学|11-(1)|1", "card_type": "redo", "stem": "写出钠块在氧气中加热、生成淡黄色固体的化学方程式。", "teach": "钠与氧气反应，条件决定产物：常温缓慢氧化生成白色Na2O：4Na＋O2＝2Na2O；加热或点燃生成淡黄色Na2O2：2Na＋O2＝Na2O2（条件写点燃或△）。题目给了“加热、淡黄色”两个信号，产物锁定Na2O2。用四步检查法自查：①化学式——产物是Na2O2不能写成Na2O；②配平——2个Na、2个O两边相等；③条件——等号上方写点燃或△，不能自创符号；④符号——没有气体沉淀生成，不标。她第①步产物就判错，后面全丢。", "why": "写成4Na＋O2＝Na2O，把加热产物当成了常温产物，还自创了不明条件符号。", "check_q": "钠在常温下与氧气反应的化学方程式是什么？产物什么颜色？", "check_a": "4Na＋O2＝2Na2O，产物是白色固体。"}, {"subject": "化学", "question_no": "11-(2)", "full_score": 2.0, "got_score": 0.0, "student_answer": "3H2+Cl2=…→2H3Cl（涂改混乱）", "std_answer": "重建：H2+Cl2=点燃=2HCl", "error_type": "知识盲区", "knowledge_point": "氢气在氯气中燃烧", "note": "", "key": "化学|11-(2)|1", "card_type": "redo", "stem": "写出氢气在氯气中燃烧的化学方程式。", "teach": "H2在Cl2中安静燃烧、发出苍白色火焰：H2＋Cl2＝2HCl，条件点燃。四步检查法：①化学式——产物是HCl，一个H配一个Cl；②配平——系数比1∶1∶2，H、Cl两边都是2；③条件——点燃；④符号——HCl虽是气体，但反应物中也有气体，不标↑。最要紧的一条铁律：配平只能改系数，化学式的下标永远不能动。她写出的“2H3Cl”是把系数挪进了化学式，凭空造出不存在的物质，这是方程式书写的大忌。", "why": "把配平系数写进了化学式，造出不存在的H3Cl，化学式书写规则没过关。", "check_q": "H2在Cl2中燃烧的火焰是什么颜色？产物遇水蒸气有什么现象？", "check_a": "苍白色火焰；产物HCl遇水蒸气形成白雾（盐酸小液滴）。"}, {"subject": "化学", "question_no": "11-(3)", "full_score": 2.0, "got_score": 0.0, "student_answer": "2Fe+HCl=Fe3Cl2", "std_answer": "重建：2Fe+3Cl2=点燃=2FeCl3", "error_type": "概念混淆", "knowledge_point": "Fe与Cl2生成FeCl3 vs Fe与盐酸生成FeCl2+H2↑，两者混淆且化学式错误", "note": "", "key": "化学|11-(3)|1", "card_type": "redo", "stem": "写出细铁丝在氯气中燃烧的化学方程式。", "teach": "铁与氯气、铁与盐酸是两个完全不同的反应，必须分开记：Cl2氧化性强，红热铁丝在Cl2中剧烈燃烧、产生棕褐色烟，产物是FeCl3：2Fe＋3Cl2＝2FeCl3（点燃），铁被氧化到＋3价；盐酸是非氧化性酸，铁与盐酸反应生成的是FeCl2和H2。规律：变价金属与Cl2反应生成最高价氯化物，与盐酸反应生成低价盐。四步检查：化学式FeCl3、配平2-3-2、条件点燃、无符号。", "why": "把“铁与氯气”错换成“铁与盐酸”，反应物写成HCl，产物价态和化学式一起错。", "check_q": "铁与盐酸反应的化学方程式是什么？铁是几价？", "check_a": "Fe＋2HCl＝FeCl2＋H2↑，铁为＋2价（与氯气反应则生成＋3价的FeCl3）。"}, {"subject": "化学", "question_no": "11-(4)", "full_score": 2.0, "got_score": 0.0, "student_answer": "HClO=H2O+Cl2↑", "std_answer": "重建：2HClO=光照=2HCl+O2↑", "error_type": "知识盲区", "knowledge_point": "次氯酸见光分解", "note": "", "key": "化学|11-(4)|1", "card_type": "redo", "stem": "次氯酸不稳定、需避光保存在冷暗处。写出次氯酸见光分解的化学方程式。", "teach": "次氯酸见光分解：2HClO＝2HCl＋O2↑，条件是光照。这也是氯水必须避光保存、久置氯水最终变成稀盐酸的原因。四步检查法：①化学式——产物是HCl和O2；②配平——2个HClO分解出2个HCl和1个O2，H、Cl、O三边守恒；③条件——光照，写在等号上方；④符号——O2是唯一生成的气体，加↑。写完方程式一定回头数两边原子个数：她写的HClO＝H2O＋Cl2↑，左右原子数根本对不上，数一遍就能发现。", "why": "凭感觉拼产物写成H2O和Cl2，没用原子守恒检验，产物和配平双错。", "check_q": "久置的氯水最终主要变成什么？什么现象能说明HClO见光分解？", "check_a": "主要变成稀盐酸；光照新制氯水有气泡（O2）冒出、黄绿色变浅。"}, {"subject": "化学", "question_no": "11-(5)", "full_score": 2.0, "got_score": 0.0, "student_answer": "2Ca(OH)2+2H2O+4Cl2=CaCl2+Ca(ClO)2+HClO（另有一版涂改作废）", "std_answer": "重建：2Ca(OH)2+2Cl2=CaCl2+Ca(ClO)2+2H2O", "error_type": "配平错误+产物记忆错误", "knowledge_point": "漂白粉的制取", "note": "", "key": "化学|11-(5)|1", "card_type": "redo", "stem": "写出工业上制取漂白粉的化学方程式（氯气通入石灰乳）。", "teach": "漂白粉是把Cl2通入冷的石灰乳制成的：2Cl2＋2Ca(OH)2＝CaCl2＋Ca(ClO)2＋2H2O，产物是两种盐加水，漂白粉就是CaCl2与Ca(ClO)2的混合物，有效成分是Ca(ClO)2。四步检查法：①化学式——反应物只有Cl2和Ca(OH)2，水是产物不是反应物；②配平——按Ca守恒先定Ca(OH)2为2，再数Cl两边各4；③条件——常温，不用写；④符号——无气体沉淀。她把H2O错放到反应物一侧、产物还多出HClO，第①步就没过关。", "why": "把产物水写进了反应物，又凭空多写了HClO，方程式左右两边完全不对等。", "check_q": "漂白粉的有效成分是什么？它靠什么起漂白作用？", "check_a": "有效成分是Ca(ClO)2；它与空气中的CO2和水反应生成HClO，靠HClO的强氧化性漂白杀菌。"}, {"subject": "化学", "question_no": "11-(6)", "full_score": 2.0, "got_score": 0.0, "student_answer": "CuSO4+NaOH=Na2SO4（产物不全）", "std_answer": "重建：CuSO4+2NaOH=Cu(OH)2↓+Na2SO4", "error_type": "方程式不完整", "knowledge_point": "复分解反应：产物有蓝色Cu(OH)2沉淀", "note": "", "key": "化学|11-(6)|1", "card_type": "redo", "stem": "写出往CuSO4溶液中滴加NaOH溶液的化学方程式。", "teach": "这是复分解反应：两种化合物交换成分，Cu2＋与OH－结合成难溶的蓝色沉淀Cu(OH)2：CuSO4＋2NaOH＝Na2SO4＋Cu(OH)2↓。用四步检查法对应她的三处错：①化学式——OH是原子团，个数为2时必须加括号写(OH)2，她写成CuOH2，这种物质不存在；②配平——右边有2个Na和2个OH，NaOH前面必须配2，她没配；③条件——常温无条件；④符号——Cu(OH)2是沉淀必须加↓，她漏了。四步错三步，一分都剩不下。", "why": "没给NaOH配平、Cu(OH)2没加括号、沉淀符号也漏了，方程式只剩骨架。", "check_q": "CuSO4溶液中滴加NaOH会看到什么现象？沉淀是什么、什么颜色？", "check_a": "产生蓝色絮状沉淀、溶液蓝色变浅；沉淀是Cu(OH)2。"}, {"subject": "化学", "question_no": "13-(1)", "full_score": 2.0, "got_score": 0.0, "student_answer": "Na+H2O=NaOH（未配平，漏写H2）", "std_answer": "重建：2Na+2H2O=2NaOH+H2↑", "error_type": "漏写气体产物+未配平", "knowledge_point": "钠与水的反应", "note": "", "stem": "写出钠与水反应的化学方程式。", "paper_cause": "方法不会（整题空白，与第 11 题方程式薄弱互为印证）", "key": "化学|13-(1)|1", "card_type": "redo", "teach": "钠与水反应是必背方程式：2Na＋2H2O＝2NaOH＋H2↑。用四步检查法自查：①化学式——产物NaOH和H2两个都要写全；②配平——Na两边各2、H两边各4、O两边各2；③条件——常温剧烈反应，不需要条件；④符号——H2是气体且反应物中没有气体，必须加↑。她写的Na＋H2O＝NaOH漏了H2、没配平、漏↑，四步错三步。习惯要养成：每写完一个方程式，化学式、配平、条件、符号逐项打勾再往下做。", "why": "漏写了产物H2，也没配平，气体符号也没标——没走四步检查。", "check_q": "钠与水反应的现象可用哪五个字概括？", "check_a": "浮、熔、游、响、红（浮在水面、熔成小球、四处游动、发出嘶嘶响声、滴酚酞后变红）。"}, {"subject": "化学", "question_no": "13-(2)-方程1", "full_score": 2.0, "got_score": 1.0, "student_answer": "Na2O2+CO2=2Na2CO3+O2（未配平）", "std_answer": "重建：2Na2O2+2CO2=2Na2CO3+O2", "error_type": "配平错误（按规则扣1分）", "knowledge_point": "过氧化钠与二氧化碳反应", "note": "", "stem": "写出过氧化钠与二氧化碳反应的化学方程式。", "paper_cause": "方法不会（整题空白，与第 11 题方程式薄弱互为印证）", "key": "化学|13-(2)-方程1|1", "card_type": "redo", "teach": "Na2O2与CO2的反应：2Na2O2＋2CO2＝2Na2CO3＋O2，这是Na2O2用作呼吸面具、潜水艇供氧剂的原理。四步检查法：①化学式——产物是Na2CO3和O2，她这步对了；②配平——抓Na守恒：右边2个Na2CO3含4个Na，左边Na2O2必须配2，CO2随之配2，最后数O自动守恒；③条件——常温无条件；④符号——反应物CO2本身是气体，生成的O2不标↑（只有反应物无气体时才标）。她就栽在第②步：两个系数2都没写。", "why": "产物全对，就是Na2O2和CO2前的系数2没写，未配平被扣分。", "check_q": "Na2O2与水反应的化学方程式是什么？Na2O2在呼吸面具中起什么作用？", "check_a": "2Na2O2＋2H2O＝4NaOH＋O2↑；吸收人呼出的CO2并释放O2（供氧剂）。"}, {"subject": "化学", "question_no": "13-(5)", "full_score": 2.0, "got_score": 0.0, "student_answer": "圈选①③②④⑤", "std_answer": "未知（标准缺失）", "error_type": "未知（据总分反推0分，不确定）", "knowledge_point": "疑为排序题，标准未知", "note": "", "stem": "[钠及其化合物转化关系图：Na、Na2O、NaOH、Na2CO3、NaHCO3、NaCl 按化合价与类别排布，部分文字不清](1)Na 与水反应的化学方程式为＿＿。(2)Na2O2 与二氧化碳反应的化学方程式为＿＿。(3)Na2CO3 粉末与过量盐酸反应的化学方程式为＿＿。(4)NaH 中氢元素的化合价为＿＿价，NaH 与水反应生成一种强碱和一种可燃性气体，反应的化学方程式为＿＿。(5)将一小块钠投入 CuSO4 溶液中，观察到的现象是＿＿（填序号：①钠浮于液面上 ②熔化成小球 ③发出嘶嘶的响声，放出气体 ④有蓝色沉淀产生 ⑤析出红色的铜）。", "paper_cause": "方法不会（整题空白，与第 11 题方程式薄弱互为印证）", "key": "化学|13-(5)|1", "card_type": "concept", "teach": "钠投入CuSO4溶液的现象，正确序号是①②③④，没有⑤。原理还是“先水后盐”：钠先与水反应，所以浮（密度比水小）、熔（反应放热且钠熔点低）、游、响四项都有；生成的NaOH再与CuSO4生成蓝色Cu(OH)2沉淀，即④。⑤“析出红色的铜”是陷阱：钠在水溶液中绝不置换出金属。记忆抓手：钠入盐溶液的现象＝钠与水反应的现象＋生成的碱与盐反应的现象，两段拼起来，唯独没有金属单质析出。", "why": "把⑤也圈了进去，以为钠能像置换反应那样从溶液里置换出铜。", "check_q": "钠投入FeCl3溶液中，除了浮、熔、游、响，还会看到什么现象？", "check_a": "产生红褐色沉淀Fe(OH)3（生成的NaOH与FeCl3反应），不会析出铁。"}, {"subject": "化学", "question_no": "14-(1)-方程", "full_score": 4.0, "got_score": 2.0, "student_answer": "MnO2+HCl=MnCl2+Cl2↑+H2O（未配平，缺\"浓\"和\"△\"）", "std_answer": "重建：MnO2+4HCl(浓)=△=MnCl2+Cl2↑+2H2O", "error_type": "配平错误+条件缺失（按规则各扣1分）", "knowledge_point": "氯气的实验室制法", "note": "", "stem": "写出实验室用MnO2和浓盐酸制取氯气的化学方程式。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(1)-方程|1", "card_type": "redo", "teach": "实验室制Cl2是本章第一个必背方程式：MnO2＋4HCl(浓)＝MnCl2＋Cl2↑＋2H2O，条件△。四步检查法对她的错：①化学式——盐酸必须标注“浓”，稀盐酸与MnO2不反应，这是最关键的限定；②配平——先数产物一侧的Cl：MnCl2有2个、Cl2有2个，共4个，所以HCl配4，再配H2O为2，她只写了1个HCl；③条件——必须加热，△不能漏，她漏了；④符号——Cl2加↑她写对了。配平抓手：从产物Cl总数倒推HCl系数。", "why": "没配平HCl的系数4，条件△和“浓”字也都缺了，一个方程式丢了两处分。", "check_q": "实验室制氯气为什么必须用浓盐酸？稀盐酸行不行？", "check_a": "不行。MnO2氧化能力有限，需要浓盐酸才能被氧化放出Cl2；稀盐酸与MnO2不反应。"}, {"subject": "化学", "question_no": "14-(1)-BDC", "full_score": 2.0, "got_score": 0.0, "student_answer": "BDC", "std_answer": "未知（题意不明）", "error_type": "未知（据总分反推0分，不确定）", "knowledge_point": "疑为装置/选项选择", "note": "", "stem": "I. 氯气是制备含氯化合物的重要原料，工业和生活中常用含氯消毒剂，实验室还用下图所示装置制取干燥纯净的氯气。(1)装置 A 中发生反应的化学方程式为＿＿。(2)B、C 中分别装的试剂是＿＿、＿＿。(3)写出该实验中[尾气处理]的化学方程式＿＿。(4)新制氯水显黄绿色说明其中含有＿＿，[说明其中含有 HClO 的现象，不清]。(5)实验发现，一瓶密封不严的漂白粉已变质[部分文字不清]。假设①：该漂白粉未变质；假设②：该漂白粉全部变质，含有 CaCl2、CaCO3[推断]；假设③：该漂白粉部分变质，既含有 CaCl2、Ca(ClO)2，又含有 CaCO3。II. 设计实验方案：实验 1，取少量上述漂白粉样品于试管中，加入适量稀盐酸，观察是否有气泡产生；实验 2，向实验 1 反应后的试管中滴加 1-2 滴品红溶液，振荡。预期现象和结论：a.若有气泡产生，则假设＿＿不成立；b.若品红溶液褪色，结合实验 1 的判断，则假设＿＿成立；c.若品红溶液不褪色，则假设＿＿成立。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(1)-BDC|1", "card_type": "concept", "teach": "制取干燥纯净Cl2的净化顺序是固定的：发生装置制出的Cl2先过B瓶饱和食盐水——除去混有的HCl（HCl极易溶于水，Cl2在饱和食盐水中溶解很少）；再过C瓶浓硫酸——干燥除水蒸气；最后收集，尾气用NaOH溶液吸收。顺序绝不能反：如果先干燥后除HCl，气体从食盐水里出来又会带上水蒸气，干燥白做。记忆抓手八个字：“先除杂、后干燥”，B的任务是除HCl，C的任务是吸水。", "why": "对B、C两瓶各装什么、谁先谁后没有把握，净化流程的顺序和分工没记牢。", "check_q": "制Cl2时把饱和食盐水和浓硫酸的顺序颠倒，会有什么问题？", "check_a": "气体最后经过食盐水会重新带上水蒸气，干燥失败，收集到的Cl2不纯净不干燥。"}, {"subject": "化学", "question_no": "14-(3)", "full_score": 4.0, "got_score": 0.0, "student_answer": "Cl2+NaOH=NaCl+HClO", "std_answer": "重建：Cl2+2NaOH=NaCl+NaClO+H2O", "error_type": "产物错误", "knowledge_point": "氯气与NaOH反应（尾气吸收）；注意产物是NaClO不是HClO", "note": "", "stem": "写出用NaOH溶液吸收氯气（尾气处理）的化学方程式。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(3)|1", "card_type": "redo", "teach": "Cl2与NaOH溶液反应：Cl2＋2NaOH＝NaCl＋NaClO＋H2O，产物是次氯酸钠NaClO，不是次氯酸HClO。两个反应要分清：Cl2与水反应生成HCl和HClO（可逆）；Cl2与碱反应时，生成的HClO会立刻被碱中和，最终产物是次氯酸盐。工业制漂白液、实验室吸收Cl2尾气用的都是这个反应。四步检查：化学式NaClO里的Na不能丢；NaOH配2；常温无条件；没有气体和沉淀，不加符号。她把氯水反应和氯碱反应混成了一个。", "why": "产物写成HClO，没想通碱性环境里HClO会被NaOH中和成NaClO。", "check_q": "漂白液的有效成分是什么？它和漂白粉的有效成分有什么共同点？", "check_a": "NaClO；两者有效成分都是次氯酸盐，遇酸或CO2都能生成HClO起漂白作用。"}, {"subject": "化学", "question_no": "14-(5)", "full_score": 6.0, "got_score": 0.0, "student_answer": "CaCl2·Ca(ClO)2 / CaCO3 / 圈②；下行圈①、③", "std_answer": "部分重建：有效成分应为Ca(ClO)2", "error_type": "概念混淆+未知（标准缺失，据总分反推合计0分，不确定）", "knowledge_point": "漂白粉：有效成分Ca(ClO)2 vs 混合物CaCl2·Ca(ClO)2", "note": "", "stem": "I. 氯气是制备含氯化合物的重要原料，工业和生活中常用含氯消毒剂，实验室还用下图所示装置制取干燥纯净的氯气。(1)装置 A 中发生反应的化学方程式为＿＿。(2)B、C 中分别装的试剂是＿＿、＿＿。(3)写出该实验中[尾气处理]的化学方程式＿＿。(4)新制氯水显黄绿色说明其中含有＿＿，[说明其中含有 HClO 的现象，不清]。(5)实验发现，一瓶密封不严的漂白粉已变质[部分文字不清]。假设①：该漂白粉未变质；假设②：该漂白粉全部变质，含有 CaCl2、CaCO3[推断]；假设③：该漂白粉部分变质，既含有 CaCl2、Ca(ClO)2，又含有 CaCO3。II. 设计实验方案：实验 1，取少量上述漂白粉样品于试管中，加入适量稀盐酸，观察是否有气泡产生；实验 2，向实验 1 反应后的试管中滴加 1-2 滴品红溶液，振荡。预期现象和结论：a.若有气泡产生，则假设＿＿不成立；b.若品红溶液褪色，结合实验 1 的判断，则假设＿＿成立；c.若品红溶液不褪色，则假设＿＿成立。", "paper_cause": "方法不会（全卷分值最高的 22 分大题基本空白）  ## 本科小结", "key": "化学|14-(5)|1", "card_type": "concept", "teach": "漂白粉要分三层记：成分是CaCl2和Ca(ClO)2的混合物；有效成分只有Ca(ClO)2；变质产物是CaCO3。变质过程：Ca(ClO)2吸收空气中的CO2和水，生成CaCO3和HClO，HClO见光分解失效，所以全部变质的漂白粉只剩CaCl2和CaCO3。检验变质的两个探针：加稀盐酸有气泡，说明含CaCO3、已经变质；再滴品红，褪色说明还有Ca(ClO)2，是部分变质，不褪色则是全部变质。她把成分、有效成分、变质产物搅在一起，三个假设自然无从判断。", "why": "把漂白粉的成分、有效成分和变质产物混为一谈，假设判断全乱了。", "check_q": "一瓶漂白粉加稀盐酸产生气泡，再加品红不褪色，说明它处于什么状态？", "check_a": "全部变质：含CaCO3（加酸有气泡），且已无Ca(ClO)2（品红不褪色）。"}, {"subject": "语文", "question_no": "1", "full_score": 3.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "审题偏差", "knowledge_point": "论述类：张冠李戴——把本文作者的观点（\"写诗的人\"机械写诗缺诗意）安到江湜头上；江湜诗只是论据", "note": "", "key": "语文|1|1", "card_type": "concept", "teach": "论述类文本选择题第一大坑叫张冠李戴：材料里有好几个人在说话，选项故意把甲的观点安到乙头上。这道题里，江湜是材料二请来的诗人，他的诗和话只是被讨论的例子；批评有人写诗像机器一样拼凑、缺乏诗意，是文章作者的观点，不是江湜说的。你选错，就是把作者的观点认成了江湜的。防坑方法固定三步：第一步，圈出选项里的主语（谁说、谁认为）；第二步，回原文找到这个人名所在的段落；第三步，把选项的说法和原文那句话逐字比对，主语对不上、原文找不到出处的，直接排除。宁可慢十秒，也不要凭印象选。", "why": "没圈选项的主语就凭印象选，把作者的观点安到了江湜头上。", "check_q": "材料中作者引用学者王某的事例来说明自己的观点。下列哪一项犯了张冠李戴的错误？A.作者认为写作不能机械拼凑 B.王某认为写作不能机械拼凑（原文中王某只提供了事例，并未表态）C.材料提到了王某的事例", "check_a": "B。事例提供者没有发表这个观点，把作者的观点安到他头上就是张冠李戴；判断时先认主语，再回原文找这个人说过的原话。"}, {"subject": "语文", "question_no": "4", "full_score": 6.0, "got_score": 2.0, "student_answer": "笼统作答（约2点）", "std_answer": "①原创能力②诗境营造③诗心触动④解决自己的问题", "error_type": "表述不规范", "knowledge_point": "信息筛选整合：四点只答出约两点，且语言口语化、未扣住\"高段位/诗境/诗心\"术语", "note": "", "key": "语文|4|1", "card_type": "concept", "teach": "这道6分简答题问人类诗歌高于AI的地方，标准答案是四个得分点：①原创能力——AI只是把现成诗句综合组织、拼凑模仿，人能从无到有地创造；②诗境营造——AI能渲染气氛，却营造不出浑然天成的诗境；③诗心触动——诗人会被景象和经历触动内心而产生创作冲动，AI没有自我意识和情感；④解决自己的问题——写诗是诗人表达情感、安顿自我的方式，AI没有自己的问题。你只答出约两点，还用了口头语，所以只得2分。方法记牢：先看分值定点数，6分题至少准备3到4点；再回材料逐段找差异句，一段提炼一点；最后用材料里的术语（诗境、诗心、高段位）写答案，一点一行，不要揉成一团。", "why": "只凭感觉答了约两点，没按分值回材料逐段提炼得分点，还用了口头话。", "check_q": "一道6分的简答题，参考答案有4个得分点。动笔答题之前，你应该先做哪两件事？", "check_a": "先按分值估点数（6分约需3到4点），再回原文逐段划出关键句、一段提炼一点，用原文术语分点作答。"}, {"subject": "语文", "question_no": "8", "full_score": 6.0, "got_score": 3.0, "student_answer": "部分作答", "std_answer": "①叙事线索②桥梁/奉献象征③守望与归属④人生过渡", "error_type": "表述不规范", "knowledge_point": "\"渡口\"多重象征只答出一半，\"奉献\"\"过渡\"等义项缺失", "note": "", "key": "语文|8|1", "card_type": "concept", "teach": "小说标题内涵题要挖四层，你只答出约一半。这篇《渡口》的标题：①表层义与结构义——渡口是故事发生的地点，也是叙事线索，人物在这里相遇、等待、离别，全文围绕它展开；②象征义之奉献——渡口和摆渡者默默连接两岸、送人过河，象征无私奉献、成全他人；③象征义之守望与归属——渡口是离人出发、归人回来的地方，承载着守望、牵挂与归属感；④主题义之人生过渡——渡口是从此岸到彼岸的过渡，象征人生中的转折、成长与命运变迁。答题公式记住：地点物象义到线索结构义，再到象征义，最后到主题义，逐层往下挖，每层都回原文找一处证据支撑，不要停在第一层。", "why": "只答了表层和一部分象征义，奉献和人生过渡两层没有挖出来。", "check_q": "某小说以桥为题：桥是村里通往外界的唯一通道，老村长守桥三十年，主人公走出大山后又回到家乡。按四层法，桥的主题义应怎样概括？", "check_a": "象征人生的跨越与归途：走出大山是人生的过渡与成长，返乡是归属；桥既是出发点也是归途，寄托成长、闯荡与归属的主题。能答出过渡转折加归属即对。"}, {"subject": "语文", "question_no": "9", "full_score": 3.0, "got_score": 0.0, "student_answer": "非BEG", "std_answer": "BEG", "error_type": "知识盲区", "knowledge_point": "文言断句：\"天下将乱\"后断、\"也\"句末断、\"其\"句首表揣测", "note": "", "key": "语文|9|1", "card_type": "concept", "teach": "文言断句有三招，这道题全用得上。第一招，看句末语气词：也、矣、乎、哉多在句末出现，见到它们，先在它后面断一刀。第二招，看句首虚词：其放在句首常表揣测或反问（其……乎），要在其前面断开，让它领起新句；夫、盖、若夫出现的地方也多是句首。第三招，先找主谓宾：先通读一句，认出谁做什么，一个完整的主谓结构就是一句话，比如天下将乱主谓完整，后面就该断。你这次断错，就是逐字硬猜、没先理大意。固定流程：先默读一遍说出大意，再按语气词和主谓结构下刀，最后连起来读一遍，检验通不通顺。", "why": "没先通读理大意，也没用语气词和主谓结构定位，逐字猜断点。", "check_q": "断句时，句首的其表揣测语气，应该在它的前面还是后面断开？另外，句末见到哪个字最常提示要断开？", "check_a": "在其前面断开，让其领起新句（如其李将军之谓乎，是揣测语气）；句末见也、矣、乎、哉等语气词，一般在其后断开。"}, {"subject": "语文", "question_no": "12(1)", "full_score": 4.0, "got_score": 0.0, "student_answer": "\"现在天下没有…的地方…的人呢？\"", "std_answer": "当今天下莫非还有…在渭水岸边钓鱼的贤人吗？", "error_type": "知识盲区", "knowledge_point": "\"得无…乎\"（莫非…吗）译反，\"被（穿着）\"\"钓于渭滨（状后）\"全丢", "note": "", "key": "语文|12(1)|1", "card_type": "concept", "teach": "这句4分你得0分，三个采分点全丢，逐个拆。原句的标准译意是：当今天下莫非还有像姜太公那样披着蓑衣在渭水岸边钓鱼的贤人吗？采分点一，得无……乎是固定句式，译作莫非……吗，是反问不是疑问，你把语气译反，整句意思就反了。采分点二，被通披，是动词穿着、披着，不能漏译。采分点三，钓于渭滨是状语后置，正常语序是于渭滨钓，译时要倒过来说在渭水岸边钓鱼。翻译铁律是字字落实：每个实词、虚词、句式都要在译文里有对应的词，漏一个扣一分；动笔前先在原文上把后置、省略、通假标出来，再逐字翻。", "why": "得无……乎的反问句式不认识导致译反，又漏译了被（披）和状语后置。", "check_q": "翻译句子：得无异于古之贤人乎？（提示：得无……乎等于莫非……吗）", "check_a": "（这人）莫非和古代的贤人不一样吗？得无……乎要译成莫非……吗，语气是反问，不能译成平常的疑问或否定。"}, {"subject": "语文", "question_no": "12(2)", "full_score": 4.0, "got_score": 2.0, "student_answer": "大意译出", "std_answer": "从这一点说，人有些缺点难道就弃而不用吗？", "error_type": "知识盲区（部分）", "knowledge_point": "\"由（从）/偏短（缺点）/庸（难道）\"只落实部分", "note": "", "key": "语文|12(2)|1", "card_type": "concept", "teach": "这句的标准译文是：从这一点说，人有些缺点，难道就弃而不用吗？三个关键词决定分数：由是从，由是观之就是从这件事看；偏短不能拆开按字面理解，它合成一个词，指缺点、短处；庸是副词难道，放在疑问句里加强反问语气。你只落实了一部分，得2分丢2分。文言翻译最常见的丢分就是这种词认识一半：多义词只记第一个义项，合成词拆开硬译。办法是建一份高频词多义清单，比如庸有难道、平庸、受雇等义，由有从、由于、听任等义，短有短处、说人坏话等义；翻译时先想这个词在本句最合理的义项，再代入检验通不通。", "why": "由、偏短、庸三个关键词只落实了一部分，多义词只记了表面义项。", "check_q": "庸在下列哪句中应译为难道？A.庸医误人 B.庸可弃乎 C.中庸之道", "check_a": "B。庸可弃乎是反问句，庸作副词译难道；A中的庸是平庸，C中是儒家概念，都不能译作难道。"}, {"subject": "语文", "question_no": "13", "full_score": 3.0, "got_score": 2.0, "student_answer": "部分作答", "std_answer": "①材料一：不计前嫌用张绣/魏种/毕谌②材料二三：唯才是举、不因小瑕弃用", "error_type": "表述不规范", "knowledge_point": "曹操\"山不厌高，海不厌深\"求贤若渴，材料三要点或表述有缺", "note": "", "key": "语文|13|1", "card_type": "concept", "teach": "这道题要求结合三则材料，说明曹操山不厌高、海不厌深式的求贤若渴是怎样体现的。满分3分，一则材料1分，必须分材料作答。得分构成是：①材料一，曹操不计前嫌，任用曾经背叛过他、与他为敌的张绣、魏种、毕谌等人，体现的是不计较旧怨；②材料二和材料三，唯才是举，不因为一个人有小缺点、小瑕疵就弃而不用，体现的是用人只看才能。你的答案丢了1分，多半是把几则材料混在一起写，或者漏了不计前嫌这一面。方法记牢：凡题目说结合材料一二三，答案就分成三点写，每点用固定句式：材料几中，某人做了什么，体现了哪一点，最后不要再加空泛的总结。", "why": "没有按材料逐则对应作答，要点混在一起，漏了不计前嫌这一面。", "check_q": "题目要求结合材料一、材料二分别说明某人的特点。写答案时最稳妥的格式是什么？", "check_a": "分点写：①材料一……体现……；②材料二……体现……。每则材料单独成点，用谁加做了什么加体现哪一点的句式，不混写、不漏则。"}, {"subject": "语文", "question_no": "17", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "知识盲区", "knowledge_point": "字音：B揳入(xiē)/C忸怩(ní)/D皱褶(zhě)包扎(zā)着恼(zháo)", "note": "", "key": "语文|17|1", "card_type": "concept", "teach": "这道字音题错在几个高频易读错字，一次记牢：揳入的揳读xiē，和楔子的楔同音，不读jiā；忸怩读niǔ ní，是不好意思的样子，不要读成nǐu nì；皱褶的褶读zhě，连起来是zhòu zhě；包扎是动词，扎读zā，扎是多音字，扎根读zhā，包扎读zā，挣扎读zhá；着恼的着读zháo。字音题没有取巧的技巧，全靠平时积累：读课文、做题时把拿不准的字音当场查、当场记进错字本，尤其多音字要连着词记音，记包扎zā，而不是只记一个孤零零的字。你这次选错，说明这几个词的读音从来没有真正落实过。", "why": "揳、忸怩、褶、扎这几个字的读音凭感觉读，从没查证落实。", "check_q": "下列读音全对的一组是：A.楔子xiē子、挣扎zhá B.包扎bāo zhā、忸怩niǔ ní C.皱褶zhòu zhē、着急zháo jí", "check_a": "A。B错在包扎应读zā；C错在褶应读zhě。多音字必须连着词语一起记读音。"}, {"subject": "语文", "question_no": "18", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "知识盲区", "knowledge_point": "文言实词：C项\"到中流击水（击水：游泳）\"说法错误", "note": "", "key": "语文|18|1", "card_type": "concept", "teach": "这道题考课文《沁园春·长沙》里的到中流击水。错误项把击水解释错了：击水就是击打水面、游泳前行，写的是青年毛泽东在湘江中流击水而进的矫健身姿，不是敲击水面抒发感慨之类。这类题叫课内迁移题，选项拿的全是学过的课文名句，判断对错只能靠课文注释里的原始解释，不能自己望文生义。复习方法很明确：把必修课文里老师划过的重点词句注释过一遍，尤其是诗词名句中的实词，像击水、峥嵘、挥斥方遒、浪遏飞舟；考场上遇到课内句子，先在心里默念注释，再去判断选项。", "why": "击水没有回课文注释，望文生义，把游泳前行理解错了。", "check_q": "《沁园春·长沙》浪遏飞舟中，遏是什么意思？击水又指什么？", "check_a": "遏是阻止、挡住，指江水阻挡飞快行进的船只；击水指游泳、击打水面奋力前行。两个词都必须按课文注释来记。"}, {"subject": "语文", "question_no": "19", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "C", "error_type": "知识盲区", "knowledge_point": "虚词\"之\"：C项两\"之\"均为助词\"的\"，A项介词/连词不同", "note": "", "key": "语文|19|1", "card_type": "concept", "teach": "判断虚词之的用法，靠的是替换检验法，逐项过。之常见的身份有四种：①助词的，前后是修饰关系，如水陆草木之花，换成的读得通就是它；②代词，可以换成他、它、这件事；③动词到、往，后面常跟地点，如送孟浩然之广陵的之是到；④音节助词，没有实义，如久之、顷之。这道题C项的两个之都是助词的，A项两个之一个带介词性、一个带连词性，用法并不相同，所以选错。你要做的不是背定义，而是把每一项的之依次换成的、他、到试读，哪个通顺就是哪一种。平时把课文里每个之的用法标注出来，考前只看这本账。", "why": "凭语感猜之的用法，没用替换法逐项检验，C项两个的没有看出来。", "check_q": "判断予独爱莲之出淤泥而不染中之的用法，并说明你用的检验方法。", "check_a": "之是结构助词，译作的（莲的出淤泥而不染）。检验法：把之换成的读，句子通顺且前后是修饰关系，即为助词的；若能换成他、它，则是代词。"}, {"subject": "语文", "question_no": "20", "full_score": 3.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "知识盲区", "knowledge_point": "古今异义：②④⑨古今义相同（憔悴/一生/门庭冷落），其余不同", "note": "", "key": "语文|20|1", "card_type": "concept", "teach": "判断古今异义只有一条办法：把词放回原句翻译，译不通、别扭，就是古今义不同。先记一批常见陷阱词：妻子在古代指妻子和儿女，今天只指配偶；卑鄙在古代指地位低微、见识浅陋，是诸葛亮的自称，今天指品德坏；涕在古代指眼泪，今天指鼻涕；走在古代指跑，行在古代指走。这道题里，憔悴、一生、门庭冷落这几个词古今意思相同，其余各句都有古今差别，所以要选相同的一组。你答错，是因为拿现代义去套古句，觉得好像也讲得通。做题时对每个词都多问一句：这个意思放回古代语境，合不合人物的身份和情理？合不上就是异义。", "why": "用现代词义去套古句，没把词放回原句翻译检验，相同与不同分反了。", "check_q": "弃甲曳兵而走（《寡人之于国也》）中的走，与现代汉语走路的走意思相同还是不同？为什么？", "check_a": "不同。古义是跑、逃跑（士兵丢下盔甲、拖着兵器逃跑），今义才是步行。判断古今异义必须把词放回原句翻译，身份情理对不上就是异义。"}, {"subject": "语文", "question_no": "23", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "知识盲区", "knowledge_point": "修辞：例句借代；B\"唯有杜康\"借代，A为互文", "note": "", "key": "语文|23|1", "card_type": "concept", "teach": "借代和互文最容易混，用一个检验动作就能分开。借代是用与本体相关的特征、工具、人物来代替本体，能换回去：杜康代酒（杜康是传说中的造酒者），巾帼代女子，烽烟代战争。互文是上下两句字面各说一半，意思必须拼起来才完整，比如秦时明月汉时关，其实是秦汉时的明月和关隘；开我东阁门，坐我西阁床，动作是交叉着说的。这道题B项唯有杜康以造酒者代酒，是借代；A项是互文，你把互文认成了借代。记口诀：借代找替身，互文找拼图。句子单独看意思残缺、必须和邻句拼起来读的，就是互文。", "why": "分不清借代与互文，把上下句互补的互文当成了借代。", "check_q": "判断两句的修辞：①将军百战死，壮士十年归 ②何以解忧，唯有杜康。哪句是互文，哪句是借代？", "check_a": "①是互文：并非将军都战死、壮士都归来，而是将士们征战多年、有的战死有的归来，两句要合起来理解。②是借代：杜康代指酒。"}, {"subject": "语文", "question_no": "25", "full_score": 60.0, "got_score": 45.0, "student_answer": "《选择与（坚守）初心》", "std_answer": "—", "error_type": "论证深度不足", "knowledge_point": "见下文作文专项评估", "note": "", "key": "语文|25|1", "card_type": "concept", "teach": "你的题目《选择与坚守初心》立意没有跑偏，45分卡在论证太浅。材料里其实站着三个人：曹操天下归心，是顺应大势、成就大事；李白安能摧眉折腰事权贵，是不肯顺势、低头，守住本心；黄文秀是把个人选择落到奉献里。只写要坚守初心，等于把三个人喊成了一句口号。升格写法是设三个递进的分论点：选择要顺时代之势（曹操、黄文秀回应时代需要），坚守要不违本心之真（李白），初心最后要落到行动与奉献上（黄文秀）。再加一段思辨：当顺势与守心冲突时怎么办，势可以顺，底线不能丢。这一段就是从二类文迈进一类文的关键。每段都要事例加一句分析，不要只堆事例。", "why": "立意停在口号层，没有分论点递进，事例后面缺分析句，也没有思辨段。", "check_q": "请为这篇作文写出三个递进的分论点（各一句话），分别对应曹操、李白、黄文秀。", "check_a": "示例：①顺势而为，在时代需要中确立自己的选择（曹操成就大业、黄文秀扎根乡村）；②守心不移，在权势与诱惑面前不丢本真（李白）；③以行践心，把初心落成实实在在的奉献（黄文秀）。三点按选、守、行递进即合格。"}, {"subject": "英语", "question_no": "2", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "词汇量不足/听辨弱", "knowledge_point": "短对话：house颜色，漏听关键信息", "note": "", "key": "英语|2|1", "card_type": "concept", "teach": "颜色细节题有固定套路：录音里往往不止一个颜色——先想要的、别人建议的、最后定下的，问题问最终结果。她选 B、正确是 C（dark green），多半把中间提到的颜色当了答案。抓题要诀：听到 but、in the end、let's take... 这类「拍板信号」才锁定，信号后的颜色才是真答案。场景词先认熟：paint 刷漆，decorate 装修，dark/light green 深绿/浅绿，prefer 更喜欢，curtain 窗帘。做题时在每个颜色旁记「谁说的、是不是最后定的」。", "why": "把录音中间提到的颜色当成最终答案，没等转折后的拍板信息。", "check_q": "听力小练：录音说 \"I first chose the blue curtains, but my mother thought the grey ones looked better, so we took the grey ones.\" 他们最后选了什么颜色？", "check_a": "Grey（灰色）。but 之后妈妈的意见被采纳，so 后面是最终结果；blue 是干扰项。"}, {"subject": "英语", "question_no": "3", "full_score": 1.5, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "听辨弱", "knowledge_point": "短对话：mother jogging outdoors", "note": "", "key": "英语|3|1", "card_type": "concept", "teach": "短对话问「某人靠什么锻炼」时，答案藏在答句的动词短语里。这题问母亲的锻炼方式，正确 B（by jogging outdoors，户外慢跑）。对话常设干扰：先提别人做什么、或以前做什么，最后才说问的那个人现在做什么，听到第一个动词就选必中坑。步骤：听前把选项动词（jogging、swimming、cycling、doing yoga）的发音在脑子里过一遍；听时只盯问的那个人的动词。场景词背熟：jog 慢跑，go cycling 骑行，do yoga 做瑜伽，take a walk 散步，keep fit 保持健康。", "why": "没盯住答句里的动词短语，被对话中提到的其他活动带偏了。", "check_q": "听力小练：\"—How does your father keep fit? —He goes swimming twice a week.\" 父亲靠什么锻炼？", "check_a": "Swimming（游泳）。答句的动词短语 goes swimming 就是答案，keep fit 是问句里的背景词，别被带偏。"}, {"subject": "英语", "question_no": "5", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "粗心/听辨弱", "knowledge_point": "短对话：brush teeth时间", "note": "", "key": "英语|5|1", "card_type": "concept", "teach": "这题问整段对话在谈什么（正确 A：什么时候刷牙），不是某个细节。她选 B，多半抓住一个听到的细节词就下手——话题题里，选项中出现的原文词最危险，往往只是细节不是主题。方法：短对话听完先用一句中文概括「他们在聊什么」，再对选项；若选项里只有一个是概括性的、其余都是具体小事，优先考虑概括的。场景词认熟：brush one's teeth 刷牙，twice a day 一天两次，before breakfast 早餐前，after meals 饭后，dentist 牙医。练习：每段听完先复述主题再看题。", "why": "把对话里出现的细节当成了主题，话题类题没有先概括整段内容。", "check_q": "听力小练：对话「—When should I brush my teeth? —The dentist says twice a day, in the morning and before bed.」这段对话的主题是什么？", "check_a": "刷牙的时间/频率（when to brush teeth）。整段围绕时间展开，牙膏、牙医都只是背景。"}, {"subject": "英语", "question_no": "7", "full_score": 1.5, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "听辨弱", "knowledge_point": "长对话：cinema，细节（时间/停车）抓不住", "note": "", "key": "英语|7|1", "card_type": "concept", "teach": "长对话信息密集，靠脑记必漏，这题错在电影场景的时间、停车等细节没抓住（她选 C，正确 A）。方法只有一个：边听边记。听前几秒扫选项，心里分成「时间、价格、地点、人物」几类；听到数字立刻写在对应选项旁，听到地点词打钩。数字题防双数字陷阱：7:30 和 8:00 可能一个是开场、一个是出发，问题问哪个就抓哪个动词后面的数。场景词必熟：cinema 电影院，start at 几点开场，ticket 票，seat 座位，car park 停车场，traffic jam 堵车。练习：精听专练「听到数字就落笔」，一周三次。", "why": "长对话细节全靠脑记，数字和地点一多就混了，没做边听边记。", "check_q": "听力小练：\"The film starts at 7:40. Let's meet at the cinema at 7:20.\" 电影几点开始？", "check_a": "7:40。meet 的时间 7:20 是干扰项，问题问 starts，就抓 starts at 后面的数字。"}, {"subject": "英语", "question_no": "8", "full_score": 1.5, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "听辨弱", "knowledge_point": "长对话：工作单位/咖啡馆", "note": "", "key": "英语|8|1", "card_type": "concept", "teach": "长对话问某人在哪工作，答案多藏在场所词里。听到 serve customers、menu、order，多半在餐厅；听到 office、manager、meeting，多半是公司职员。她选 C 错、正确 A，没把场所词和职业对上号。方法：听前看选项，全是职业或地点时，专等场所名词（cafe、office、shop、hospital），听到一个标一个。配对背熟：clerk—office，barista—coffee shop，waiter—restaurant，nurse—hospital。考的就是「场所→职业」这步推断。", "why": "没听出工作场所的信号词，职业推断这一步没做出来。", "check_q": "听力小练：\"She takes orders and serves coffee to customers all day.\" 她在哪儿工作？", "check_a": "咖啡馆（coffee shop / cafe）。orders 和 coffee 是场所信号词，由场所推出职业场合。"}, {"subject": "英语", "question_no": "13", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|13|1", "card_type": "concept", "teach": "独白讲人物经历要按时间线切分：at first 起初，then 后来，years later 多年后，now 现在，每个标记对应一个阶段，题目只问其中一段。这题问最初的工作（bank clerk，银行职员），她混了段。方法：听独白时在纸上画一条线，听到时间词就分段记职业和事件，答题按题干问的时段对号。场景词：bank clerk 银行职员，businessman 商人，retire 退休，career 职业生涯。独白没对话提示、语速快，时间词是唯一路标。练习：听完按「过去—后来—现在」复述三句。", "why": "独白里几个阶段的工作混在一起，没用时间词切分，问哪段答错段。", "check_q": "听力小练：\"At first he was a bank clerk. Ten years later, he opened his own shop.\" 他最初的工作是什么？", "check_a": "Bank clerk（银行职员）。at first 标记最初阶段，后面的 shop owner 是后来，问「最初」就选前者。"}, {"subject": "英语", "question_no": "14", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|14|1", "card_type": "concept", "teach": "问感受、态度的题，答案是形容词，且要分清 -ing 和 -ed：事情「令人有压力」用 stressful，人「感到有压力」用 stressed。她选的正是 stressful 方向的选项，掉进这对词的坑。听时听到 feel 就记下后面的词——feel 后跟的永远是人的感受词（stressed、tired、proud）。几对词成对背熟：stressed/stressful、bored/boring、interested/interesting、tired/tiring。一句话：-ed 形容人，-ing 形容事。", "why": "stressed 和 stressful 没分清，感受类形容词的人/物分工不明确。", "check_q": "听力小练：\"The job was so stressful that he felt stressed every day.\" 哪个词形容工作，哪个词形容人？", "check_a": "stressful 形容工作（令人有压力的），stressed 形容人（感到有压力的）。"}, {"subject": "英语", "question_no": "15", "full_score": 1.5, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|15|1", "card_type": "concept", "teach": "这题是最典型的教训：她先选 A（Chicago），又改成 B（San Francisco），两个都不对。独白里地名成串出现——出生地、去过的地方、现居地、要去的地方，问题只问其中一个身份，听到一个就选必错。方法：听前看清问哪类（was he born / does he live now），听时给每个地名标身份（生、去、住、往）。再立纪律：改答案必须有「听到了确切新信息」，凭感觉改，第一答案往往才对。她这次是地名身份没分清，又凭感觉改错。", "why": "几个地名的身份没区分，又凭感觉改了答案，两头落空。", "check_q": "听力小练：\"He was born in Chicago. He moved to New York at 20 and now lives in San Francisco.\" 他现在住在哪儿？", "check_a": "San Francisco。now lives 标记现居地，Chicago 是出生地、New York 是中途站，都是干扰。"}, {"subject": "英语", "question_no": "19", "full_score": 1.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "听辨弱", "knowledge_point": "独白细节", "note": "", "key": "英语|19|1", "card_type": "concept", "teach": "独白常考最后一问：讲话的目的是什么（正确方向 to introduce different cultures，介绍不同文化）。她错在拿某个细节当了目的。抓法：听开头第一句和结尾句，讲话人通常开门见山交代主题、结尾再呼应；中间反复出现的关键词就是主题词——customs、festivals 反复出现，主题就是 cultures。顺序也要改：细节题可边听边选，主旨题必须听完再选。选项多是 to do 开头，选前先问「这句能不能概括全篇」，只能概括一段的排除。", "why": "用局部细节代替全篇目的，主旨题没有听完、没抓反复出现的主题词。", "check_q": "听力小练：一段独白反复讲各国节日、食物和习俗，结尾说 \"I hope you can learn more about the world.\" 这段讲话的目的是什么？", "check_a": "介绍不同文化（to introduce different cultures）。反复出现的 customs、festivals 就是主题词，结尾句也在呼应。"}, {"subject": "英语", "question_no": "28", "full_score": 2.5, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "审题偏差", "knowledge_point": "阅读：细节/推理题，关键句定位错", "note": "", "key": "英语|28|1", "card_type": "concept", "teach": "这题问段落的写作目的，正确是 C（引出话题）。判断分两步：先看位置——第一段通常引出话题，最后一段多是总结升华，中间段才论证举例；再看内容——这一段若主要在摆现象、讲引子，选项写「给出建议」「得出结论」的就多半不对。她选 D，是把铺垫当成了目的。落笔前先把选项动词译出来：introduce 引出，prove 证明，show 展示，conclude 总结——目的题一半败在这些动词的细微差别上。先用一句话说清「这段在干什么」，再对选项。", "why": "没先判断段落功能，被选项里眼熟的内容带走，把铺垫当成了目的。", "check_q": "小练：文章第一段讲「越来越多学生用手机查单词」这一现象，第二段才开始分析原因。第一段的写作目的是什么？", "check_a": "引出话题（to introduce the topic）。只摆现象、未分析未下结论，就是引出。"}, {"subject": "英语", "question_no": "29", "full_score": 2.5, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "审题偏差", "knowledge_point": "阅读：同上", "note": "", "key": "英语|29|1", "card_type": "concept", "teach": "细节题铁律：答案必须在原文有依据句，没依据的选项再「合理」也不能选。这题问为什么说这本书好，正确是 B（写作风格）；她选的 C（插图色彩丰富）是常识型陷阱——听着顺，原文没说。三步：1）拿题干关键词（perfect book）回原文扫读定位；2）圈出定位句里的原因（信号 because、for、its...）；3）选项逐个回原文核对，没提到的当场排除。她七选五全对，衔接感不差，缺的就是这个「定位—核对」硬动作。以后每道细节题强制画出依据句再选。", "why": "用生活常识和眼熟词选了答案，没有回原文找依据句核对。", "check_q": "小练：原文说 \"The book is popular not for its pictures, but for its simple language.\" 这本书受欢迎的原因是什么？", "check_a": "语言简单（its simple language）。not...but... 后面才是真原因，前面的 pictures 是被否定掉的干扰。"}, {"subject": "英语", "question_no": "33", "full_score": 2.5, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "词汇量不足", "knowledge_point": "阅读：词义/推理题", "note": "", "key": "英语|33|1", "card_type": "concept", "teach": "这题考「one tourist for each person」：游客数和当地人数 1:1，平均每个居民对应一个游客，总量非常大，所以正确 C（大量游客到访西班牙）。她选 D，是没把比率换算成总量。方法：遇到 one X for each Y、twice as many as 这类数量表达，先换算成一句话——「游客总数≈当地人口总数」，结论立刻清楚：人山人海。顺带记 masses of＝大量的，后接可数名词复数。数字、比率、百分比题都先换算再对选项，别停在字面。", "why": "\"一个居民对应一个游客」的比率没换算成总量，短语的字面含义没读懂。", "check_q": "小练：\"The village has one car for each family.\" 这句话是什么意思？", "check_a": "平均每户有一辆车（汽车总量约等于家庭户数），不是「全村只有一辆车」。"}, {"subject": "英语", "question_no": "34", "full_score": 2.5, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "审题偏差", "knowledge_point": "阅读", "note": "", "key": "英语|34|1", "card_type": "concept", "teach": "这题要用「否定信息反推」。原文说游客 don't mind pollution（不介意污染）、can allow traffic jams（能容忍堵车），言下之意这些不会让人扫兴；问什么会毁兴致，就选没被「豁免」的那个：A 阴雨天。她选 D，是正着找「文中提到的坏事」，正中出题人的坑。固定方法：遇到 ruin、except、NOT 类题，先分两堆——被 don't mind、not care 豁免的放一堆（全是排除项），没被豁免的才是答案。步骤：圈否定词→标豁免项→反推。but 后面的信息权重最高。", "why": "正着找答案，没注意到原文用 don't mind 把污染、堵车都豁免了，需要反推。", "check_q": "小练：原文说 \"Visitors don't mind the cold, but they hate rainy days.\" 什么会让游客扫兴？", "check_a": "雨天（rainy days）。cold 被 don't mind 豁免，but 后面的 hate 指向的才是真答案。"}, {"subject": "英语", "question_no": "44", "full_score": 1.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "词汇辨析", "knowledge_point": "完形：近义词/语境辨析不清", "note": "", "key": "英语|44|1", "card_type": "redo", "stem": "完形填空：This nervousness finally led to ___. A. actions B. words C. plans D. ambitions", "teach": "先看搭配：led to「导致、通向」，后接名词作结果。再辨析四词：actions 行动，words 话语，plans 计划，ambitions 抱负。紧张（nervousness）是情绪，它导向的应是外在行动——情绪推动人做行动，逻辑最顺；words 是说出口的话，紧张不会「导致话语」成本句结果；plans、ambitions 是长期打算，与 finally「终于转变」的语气不搭。所以选 A。完形名词题三步：看空前动词要什么宾语；四词逐个译中文；代入读整句验逻辑。别凭眼熟选。", "why": "led to 后面四个名词没逐个辨析，凭眼熟选了 words，没验证逻辑是否成立。", "check_q": "小检验：Years of practice finally led to his ___ in the competition. A. success B. word C. plan D. ambition", "check_a": "A（success）。led to 接努力带来的结果，success 和 practice 的因果最顺，其余三项都不是「结果」。"}, {"subject": "英语", "question_no": "48", "full_score": 1.0, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "词汇辨析", "knowledge_point": "完形：逻辑连词/语境", "note": "", "key": "英语|48|1", "card_type": "redo", "stem": "完形填空：He was late again, but it was just an ___ — in fact, he had overslept. A. reason B. adventure C. excuse D. chance", "teach": "辨析 excuse 和 reason：excuse 是「借口、托词」，为掩盖真相编出的说法，带贬义；reason 是「原因、理由」，中性，是真实原因。本句两个信号：just（不过是）和破折号后的 in fact he had overslept（其实睡过头了）——前面的说法是编的，所以选 excuse（C）。搭配：make an excuse 找借口，an excuse for being late。看到 just、in fact 出现，就警惕「表面说法≠真相」，多半选 excuse。她错在把借口和原因当一回事。", "why": "excuse（借口）和 reason（真实原因）没分清，漏看了 just 和 in fact 的提示。", "check_q": "小检验：Don't make ___ for your mistakes; just say sorry. A. reasons B. excuses C. adventures D. chances", "check_a": "B（excuses）。make excuses 是固定搭配「找借口」，且语境是认错道歉，不是讲真实原因。"}, {"subject": "英语", "question_no": "52", "full_score": 1.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "词汇辨析", "knowledge_point": "完形", "note": "", "key": "英语|52|1", "card_type": "redo", "stem": "完形填空：Hearing the news, I ___ for a second and didn't know what to say. A. sat B. slept C. knocked D. stood", "teach": "stood 是 stand 的过去式。stand 除「站立」外还有「停着不动、愣住」意：stand for a second 就是愣了一秒。判断两步：一看空后搭配——for a second 是一小段时间，需要能持续一小会儿的动作，stand 合适；knocked「敲、撞」必须有对象（knock on the door），直接跟 for a second 不成立。二看语境——听到消息后「不知说什么」是愣住，不是 sat（坐下）更不是 slept（睡着）。选 D。完形动词题先验「动词+空后成分」结构，再看词义。", "why": "不知道 stand 有「愣住、停着不动」的用法，被 knocked 的眼熟带偏了。", "check_q": "小检验：She ___ at the door for a minute before going in. A. knocked B. stood C. slept D. hit", "check_a": "B（stood）。at the door + for a minute 表示在门口停留一分钟，stand 合适；knock 后面要接 on/at 且不能持续一分钟。"}, {"subject": "英语", "question_no": "55", "full_score": 1.0, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "词汇辨析", "knowledge_point": "完形", "note": "", "key": "英语|55|1", "card_type": "redo", "stem": "完形填空：After graduation, he decided to follow his ___ and became a painter. A. advice B. dream C. interest D. personality", "teach": "follow one's interest「遵从自己的兴趣」，是讲职业选择时的常用搭配。后半 became a painter 是结果——因兴趣在画画才去当画家，选 C（interest）。逐个排除：advice 建议，follow advice 是听从别人建议，与 he decided（他自己决定）矛盾；dream 梦想，follow one's dream 也成立，但强调「目标」，本句强调「热爱什么」；personality 性格，不与 follow 搭配。抓手：先看搭配，再看上下文指向热爱、目标还是别人的意见。", "why": "follow 和四个抽象名词的搭配没辨清，interest（兴趣）这个点没抓住。", "check_q": "小检验：You should follow your ___ and choose what you truly love to do. A. personality B. interest C. advice D. excuse", "check_a": "B（interest）。truly love 指向兴趣；advice 是别人的建议，personality 不与 follow 搭配。"}, {"subject": "英语", "question_no": "56", "full_score": 1.5, "got_score": 0.0, "student_answer": "at", "std_answer": "For", "error_type": "知识盲区", "knowledge_point": "介词：句首\"For children…\"表对象，误用at", "note": "", "key": "英语|56|1", "card_type": "redo", "stem": "语法填空（填一个介词）：___ children, eating comfort food is not only about taste; it also brings back warm memories.", "teach": "答案是 For。for 放句首、后接人加逗号，意为「对于……来说」：For children, ... = 对孩子们来说。判断三步：一，空后是名词加逗号，后面是完整主句，空处填介词构成状语；二，排除 at——at children 不成立，at 只用于时间点和地点（at 7 o'clock，at school）；三，句意「对孩子而言」正是 for 表对象。搭配记牢：for example 例如，wait for 等待，be good for 对……有好处。她错在把 at 当万能介词。", "why": "句首表对象「对……来说」要用 For，她误用了 at，没先判断空后结构。", "check_q": "小检验：___ me, the best part of the trip was the food.（填一个介词）", "check_a": "For。「对我来说」句首引出评价对象，用 For，后接人加逗号。"}, {"subject": "英语", "question_no": "57", "full_score": 1.5, "got_score": 0.0, "student_answer": "to surprised", "std_answer": "to reduce", "error_type": "知识盲区", "knowledge_point": "不定式作目的状语，动词原形；且surprised词义亦错", "note": "", "key": "英语|57|1", "card_type": "redo", "stem": "语法填空：When people feel stressed, they often eat something sweet ___ (reduce) pressure.（用所给词的适当形式填空）", "teach": "答案 to reduce，考不定式作目的状语：吃甜食是为了减压，目的 = in order to do，所以用 to + 动词原形。判断三步：第一，句子已有谓语 eat，空处不是第二个谓语；第二，问「吃是为了什么」——能答出目的就用 to do；第三，to 后必须跟动词原形，这是铁律。她写 to surprised 错了两层：surprised 是形容词「感到惊讶的」，不是动词；就算用 surprise 也必须是原形。记住：-ed 结尾的形容词（surprised、tired）永远不能站在 to 后充当动作。", "why": "把 to 当成普通介词，后面填了形容词 surprised，没意识到表目的要用 to + 动词原形。", "check_q": "小检验：He got up early ___ (catch) the first bus.（用所给词的适当形式填空）", "check_a": "to catch。早起的目的是赶车，不定式作目的状语，to 后接动词原形。"}, {"subject": "英语", "question_no": "59", "full_score": 1.5, "got_score": 0.0, "student_answer": "e（未完成）", "std_answer": "easier", "error_type": "知识盲区/时间不够", "knowledge_point": "比较级：未写出完整形式", "note": "", "key": "英语|59|1", "card_type": "redo", "stem": "语法填空：People like comfort food because it is ___ (easy) to prepare than the food in restaurants.（用所给词的适当形式填空）", "teach": "答案 easier。触发词是 than：句中有 than，前面的形容词多半用比较级，这是送分信号。再看变法：easy 以「辅音+y」结尾，变比较级把 y 改 i 再加 -er → easier；同类背一组：happy→happier，busy→busier，heavy→heavier。她只写了个开头 e，规则知道大概但没落实到笔头。做题动作固定：一扫 than / more 定比较级；二写变化 y→i 加 er；三检查没漏写。比较级不难，丢分全在手上不规范。", "why": "看到了比较语境却没写出完整比较级形式，y 变 i 加 er 的规则没落实。", "check_q": "小检验：This box is ___ (heavy) than that one.（用所给词的适当形式填空）", "check_a": "heavier。than 提示比较级，heavy 和 easy 同类：变 y 为 i 再加 er。"}, {"subject": "英语", "question_no": "63", "full_score": 1.5, "got_score": 0.0, "student_answer": "（未辨认/0分）", "std_answer": "the", "error_type": "知识盲区", "knowledge_point": "冠词：特指the，空着或写错", "note": "", "key": "英语|63|1", "card_type": "redo", "stem": "语法填空（填冠词）：For many people, pizza is ___ number one comfort food in the world.", "teach": "答案 the。定冠词有个高频考点：序数词和「第一、唯一」类表达前必须加 the——the first，the number one，the best（最高级），the only。number one 是排名第一，全世界只有一个，是特指，用 the，绝不能用 a（a 表示任意一个）。判断两步：空后若是 first、second、best、only、same，先想 the；再自问「是不是独一无二的那一个」，是就坐实。她这空空着，是没想到冠词也单独设空考。口诀：序数最高级，唯一和特指，见面先给 the。", "why": "number one 前需要定冠词特指，她没意识到冠词也是考点，空着没写。", "check_q": "小检验：He was ___ first student to finish the exam.（填冠词）", "check_a": "the。first 是序数词，特指「第一个」，前面加 the。"}, {"subject": "英语", "question_no": "64", "full_score": 1.5, "got_score": 0.0, "student_answer": "（未辨认/0分）", "std_answer": "aged", "error_type": "知识盲区", "knowledge_point": "过去分词作定语（aged children）", "note": "", "key": "英语|64|1", "card_type": "redo", "stem": "语法填空：The survey found that people ___ (age) 25 to 40 are most likely to eat comfort food when stressed.（用所给词的适当形式填空）", "teach": "答案 aged，考过去分词作后置定语：people aged 25 to 40 = 年龄在 25 到 40 岁的人。age 作动词时 aged 表示「年龄为……岁」。判断两步：一，名词 people 后缺定语、括号给动词，优先考虑分词；二，看关系——人是「被标明年龄」的，属状态、被动，用 -ed；若是名词自己的动作正在进行，用 -ing（the sleeping baby）。同类：the girl dressed in red，the boy named Tom。她没得分是「分词作定语」没启动。", "why": "不知道 aged 可以作后置定语表示「年龄在……岁」，分词作定语的用法没掌握。", "check_q": "小检验：The girl ___ (dress) in red is my sister.（用所给词的适当形式填空）", "check_a": "dressed。女孩是「被穿着」红衣，状态作定语用过去分词 dressed，和 aged 同理。"}, {"subject": "英语", "question_no": "66", "full_score": 0.0, "got_score": 0.0, "student_answer": "confident", "std_answer": "confidence", "error_type": "知识盲区", "knowledge_point": "词形：have confidence in，误用形容词", "note": "", "key": "英语|66|1", "card_type": "redo", "stem": "完成句子：他非常自信地回答了所有问题。He answered all the questions with great ___.", "teach": "答案 confidence（名词，自信），她填的 confident 是形容词，词性对不上。词形题先看位置：with great ___ 里 great 是形容词，后面必须接名词。搭配记牢：with (great) confidence 自信地，have confidence in sb./sth. 对……有信心。抓手：形容词 -ent 结尾（confident），名词换 -ence（confidence），同 different → difference。括号给形容词、空处要名词时，先想「换尾巴」。", "why": "空处需要名词，她填了形容词 confident，词性判断这一步没做。", "check_q": "小检验：She has great ___ in her own ability.（confident 的适当形式）", "check_a": "confidence。has great 后接名词，且 have confidence in 是固定搭配。"}, {"subject": "英语", "question_no": "67", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "confusing", "error_type": "知识盲区", "knowledge_point": "-ing/-ed形容词辨析", "note": "", "key": "英语|67|1", "card_type": "redo", "stem": "完成句子：这道数学题太令人困惑了，全班都做不出来。The maths problem was so ___ that nobody in the class could work it out.", "teach": "答案 confusing。-ing / -ed 形容词分工是高频考点：confusing「令人困惑的」修饰物或事，confused「感到困惑的」修饰人。口诀：物用 -ing，人用 -ed。对比记：the news is exciting（消息令人兴奋），I am excited（我感到兴奋）。本题修饰 problem（物），用 confusing。判断两步：先看修饰人还是物，再选形式。她 0 分就是规则没分清。so...that... 里形容词作表语跟在 was 后，选对形式即得分。", "why": "confusing 和 confused 的人/物分工没分清，修饰题目（物）误用了方向。", "check_q": "小检验：The students looked ___ when they saw the strange question.（confuse 的适当形式）", "check_a": "confused。修饰人 students 的感受，用 -ed 形式；题面令人困惑才用 confusing。"}, {"subject": "英语", "question_no": "68", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "extremely", "error_type": "知识盲区", "knowledge_point": "副词修饰形容词", "note": "", "key": "英语|68|1", "card_type": "redo", "stem": "完成句子：春天的这座花园非常美丽。The garden is ___ beautiful in spring.", "teach": "答案 extremely（副词，极其、非常）。空在形容词 beautiful 前面，修饰形容词必须用副词，不能用形容词 extreme。extreme 加 -ly 变副词，拼写直接加 ly（e 不去掉）：extremely，强度比 very 还强。判断记死：空后是形容词或副词，填副词；空后是名词，才填形容词。同类记一组：careful → carefully，quick → quickly，real → really；但 true → truly 要去 e，是例外。她这题是没做词形转换，把原词直接搬上去了。", "why": "修饰形容词需要副词，她没做词形转换，extreme 和 extremely 分不清。", "check_q": "小检验：It is ___ hot today; you'd better stay inside.（extreme 的适当形式）", "check_a": "extremely。hot 是形容词，前面要用副词 extremely 修饰。"}, {"subject": "英语", "question_no": "69", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "official", "error_type": "词汇量不足", "knowledge_point": "目标词汇拼写/ recalls", "note": "", "key": "英语|69|1", "card_type": "redo", "stem": "完成句子：官方报告称，事故中没有人受伤。The ___ report said that nobody was hurt in the accident.", "teach": "答案 official（形容词，官方的）：official report 官方报告，official news 官方消息。真正的考点是拼写：o-f-f-i-c-i-a-l，双 f，中间是 ci 不是 ce。抓手：official 来自 office（办公室）+ -al，「办公室发布的」就是「官方的」；但拼写时 ce 变 ci，把词拆三段默念——offi-ci-al。再和 officer（官员，指人）分开。她的问题是「背过但写不出」，这类词光看没用，必须动笔分段默写两遍。", "why": "official 的拼写没落实，双 f 和 cial 的写法写不出来。", "check_q": "小检验：Please check the ___ website of the school for the news.（官方的）", "check_a": "official。修饰 website 用形容词 official，注意拼写 offi-ci-al。"}, {"subject": "英语", "question_no": "72", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "addicted to", "error_type": "词汇量不足", "knowledge_point": "be addicted to，目标短语不会", "note": "", "key": "英语|72|1", "card_type": "redo", "stem": "完成句子：他沉迷于电脑游戏，根本停不下来。He is ___ ___ computer games and simply can't stop.", "teach": "答案 addicted to：be addicted to「沉迷于、对……上瘾」，是本单元核心短语——写作劝诫信里老师改的范文开头用的就是它。三点记牢：一，addicted 是形容词，前面要有 be 动词；二，to 是介词，后接名词或动名词——addicted to playing games，不能写 to play；三，拼写双 d。抓手：add 是「加上」，addict 是「瘾君子」，加上就戒不掉的状态就是 addicted。她两空全错，是整条短语没默写过，只能整条背、整条写。", "why": "be addicted to 整条短语没背下来，两空都写不出。", "check_q": "小检验：She is addicted ___ chocolate and eats it every day.（填一个词）", "check_a": "to。be addicted to 是固定搭配，to 是介词，后面接名词 chocolate。"}, {"subject": "英语", "question_no": "73", "full_score": 0.0, "got_score": 1.0, "student_answer": "clean up（部分）", "std_answer": "clean up", "error_type": "粗心", "knowledge_point": "短语对一半（大小写/形式扣分）", "note": "", "key": "英语|73|1", "card_type": "redo", "stem": "完成句子：周末我们应该把公园打扫干净。We should ___ ___ the park on weekends.", "teach": "答案 clean up（打扫、清理干净）。她只对一半，丢分在小品词 up——只写 clean 是「清洁」这个动作，clean up 才强调「彻底收拾干净」的结果。完成句子按空给分，少一个词少一分。立规矩：动词短语必须整条背、整条默写，clean up、pick up（捡起）、give up（放弃）这类「动词+小品词」不能拆着记。再记一个细节：clean up 接地点名词可直接跟（clean up the park）；宾语是代词要放中间（clean it up）。她第 70、71 题短语全对，说明就是这类短语背得不全。", "why": "clean up 只写对一半，小品词 up 漏写，短语没整条落实。", "check_q": "小检验：Please ___ ___ your bedroom before your friends come.（打扫干净）", "check_a": "clean up。表示把房间收拾干净，动词和小品词两个词都要写全。"}, {"subject": "英语", "question_no": "74", "full_score": 0.0, "got_score": 1.0, "student_answer": "took control of（部分）", "std_answer": "took control of", "error_type": "粗心", "knowledge_point": "同上", "note": "", "key": "英语|74|1", "card_type": "redo", "stem": "完成句子：去年他接管了这家小公司。He ___ ___ ___ the small company last year.", "teach": "答案 took control of（接管、掌管），三个空两个坑，她只对一空。短语 take control of 三词一个不能少，最后的 of 最易漏。时态是第二坑：句中有 last year，动作在过去，take 用过去式 took。交卷前三步检查：一，短语完整吗——of、up、on 在不在；二，时态对吗——last year、ago 用过去式，every day 用一般现在时；三，人称单复数对吗。另注意 control 前不加冠词，别写 take the control。她就是完整性和时态都没查。", "why": "take control of 没整条记住，又漏看了 last year 的过去时标志，took 没变出来。", "check_q": "小检验：When the teacher left, the monitor ___ control of the class.（take 的适当形式）", "check_a": "took。left 是过去时，接管的动作同样发生在过去，用 took。"}, {"subject": "英语", "question_no": "75", "full_score": 0.0, "got_score": 0.0, "student_answer": "（0分）", "std_answer": "other than", "error_type": "词汇量不足", "knowledge_point": "目标短语不会", "note": "", "key": "英语|75|1", "card_type": "redo", "stem": "完成句子：他整天除了学习什么都不做。He does nothing all day ___ study.", "teach": "答案 other than（除了）。它与 except 意思相近，最爱出现在否定语境：nothing、nobody、no 后跟 other than，表示「除了……没有别的」。本句有 does nothing，正是主场，后接动词原形 study。与 except for 分工：except for 用于「整体肯定、只挑一个例外」（如房间挺好 except for 有点吵），后接名词。她整条写不出，是短语没背过。对策：other than、except for、apart from 对比背，各配一例句。", "why": "other than 这个「除了」没背过，否定语境该用哪个短语完全没概念。", "check_q": "小检验：I have no friend in this city ___ Tom.（除了）", "check_a": "other than。no friend 是否定语境，「除了汤姆没有别的朋友」用 other than。"}, {"subject": "英语", "question_no": "作文", "full_score": 20.0, "got_score": 11.0, "student_answer": "建议信（Wang Peng沉迷游戏）", "std_answer": "—", "error_type": "表述不规范", "knowledge_point": "见下文作文专项评估", "note": "", "key": "英语|作文|1", "card_type": "concept", "teach": "劝诫信得 11/20，病在表达：句式单一、搭配随手造。老师改好的开头就是范本：\"You have become addicted to computer games recently.\" 先点沉迷，再表担心。结构三段：开头点问题；中间摆危害（do harm to your eyes），再给建议（had better、why not）；结尾鼓励。红线搭配：be addicted to 后接名词或 doing，spend time (in) doing，be harmful to。句式至少一句 because、一句 if。", "why": "句式单一、搭配不规范，开头没有点明问题和表态，整篇表达停留在短句堆砌。", "check_q": "小检验：把这句译成英文——「沉迷于手机对你的眼睛有害。」", "check_a": "Being addicted to the phone is harmful to your eyes.（也可用 ...does harm to your eyes.）两个搭配 be addicted to、be harmful to 都要写对。"}, {"subject": "历史", "question_no": "3", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "审题偏差", "knowledge_point": "商王巡行与内外服制度：B\"政治认同\"是干扰项，题眼在\"宣示商王统治权力\"", "note": "", "stem": "商王每隔一段时间就会带着他的“子姓”分族巡行一方，所到之处，当地部族向其纳贡，获得赏赐，并派人加入商王的队伍。这种巡行（ ）", "paper_cause": "**概念不清**——只看到巡行\"宣示王权\"的一面，没抓住\"子姓分族、派人加入队伍\"背后的血缘认同功能", "key": "历史|3|1", "card_type": "redo", "options": {"A": "扩大了商朝的疆域范围", "B": "形成了部族之间的血缘认同", "C": "加强了内服外服的商业联系", "D": "宣示了商王的统治权力"}, "teach": "先看材料的动作链：巡行一方、部族纳贡、商王赏赐、派人加入商王队伍，这是一整套臣服与效忠的政治仪式，指向的是商王权威的宣示，所以正确答案是D。B项错在偷换主语：材料里的子姓分族，说的是商王把同姓子弟分派出去，属于王族内部的安排；选项却说部族之间形成了血缘认同，可被巡行的各部族与商王并不同姓，材料里也没有任何结亲、认同血缘的信息。C项材料只字未提商业贸易，A项巡行也不等于开疆拓土。这类题的看法是：把每个选项的核心词（血缘、商业、疆域、权力）逐一回材料找对应信息，找不到出处的先排除，不要被子姓这种眼熟字眼牵着走。", "why": "被子姓二字联想到血缘，没核对选项的主语是部族之间，材料根本没有血缘认同的信息。", "check_q": "西周实行分封制，周王把土地和人民分给同姓子弟、功臣等，让他们建立诸侯国。分封制在当时最直接的作用是（ ）A.扩大并巩固了周王室的统治 B.促进了各地的商业贸易 C.实现了地方的高度自治 D.消除了各族之间的差异", "check_a": "A。分封的核心功能是政治统治与疆域巩固；和本题一样，要抓住材料行为的政治功能，不要被次要信息带偏。"}, {"subject": "历史", "question_no": "6", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "B", "error_type": "知识盲区", "knowledge_point": "春秋已能生产铁器（甘肃灵台铁剑）；A\"商朝青铜农具广泛使用\"表述有误", "note": "", "key": "历史|6|1", "card_type": "concept", "teach": "这道题输在一条时间线没记清。金属工具的演变是：商周是青铜时代，但青铜贵重，主要用来做礼器和兵器，真正的农具仍以石器、木器、骨蚌器为主，所以商朝青铜农具广泛使用是错误表述，见到广泛使用这种绝对化说法先打个问号。到了春秋时期，我国已经能够生产铁器，甘肃灵台出土的春秋早期铜柄铁剑就是证据；进入战国，铁农具才推广开来，牛耕也随之出现，生产力实现跃升。记忆锚点：青铜在庙堂（礼器兵器），不在田里；铁器春秋露头、战国下地。把这条线画在课本的时间轴上，这类题就不会再错。", "why": "不知道春秋已有铁器的实物证据，又误以为商朝青铜已经广泛用于农具。", "check_q": "下列说法正确的是（ ）A.商朝时青铜农具已广泛用于农业生产 B.春秋时期我国已出现铁器，战国时铁农具得到推广 C.西周时期铁器取代了青铜器 D.牛耕最早出现在商朝", "check_a": "B。A错在青铜主要用于礼器、兵器；C错在春秋战国是青铜与铁器并存、铁器逐步推广；D牛耕出现在春秋战国时期。"}, {"subject": "历史", "question_no": "8", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "C", "error_type": "概念混淆", "knowledge_point": "二重证据法：传世文献与出土文献互证；B\"单独评价某类文献可靠性\"偏题", "note": "", "stem": "《史记》记载，秦统一后，对官方文书的名称、格式、用途作了严格的规定。从睡虎地秦简记载中，也可知官府公文的类别有书、封诊式、录、久书等。这体现了史学研究中（ ）", "paper_cause": "**概念不清**——《史记》（传世文献）与睡虎地秦简（出土文献）互相印证，考的是\"互证性\"，她误选了泛泛的\"可靠性\"", "key": "历史|8|1", "card_type": "redo", "options": {"A": "大胆假设与小心求证的严谨性", "B": "文献史料的可靠性", "C": "传世文献与出土文献的互证性", "D": "考古发掘的重要性"}, "teach": "这道题考的是二重证据法：把地下出土的实物文献和纸上流传下来的传世文献互相印证。材料里正好凑齐两类：《史记》是传世文献（后世传抄的书），睡虎地秦简是出土文献（考古挖出来的竹简），两者都记载了秦代的公文制度而且能对得上，这就叫互证性，正确答案是C。B项可靠性错在它只评价单一一种史料可不可信，而题目给了两种来源、强调的是互相对照，考点在互不在靠。以后遇到甲书的记载加乙地出土材料、内容一致这种结构，直接锁定互证；只给一份孤零零的材料谈真伪时，才谈可靠性。", "why": "没识别出《史记》与秦简是传世加出土两种来源的组合，被泛泛的可靠性带走了。", "check_q": "殷墟出土的甲骨文记载了商王占卜、祭祀等活动，与《史记·殷本纪》中商王世系的记载大体吻合。这最能体现（ ）A.甲骨文是唯一可靠的史料 B.传世文献与出土文献的互证 C.考古发掘比文献更重要 D.《史记》的记载绝对无误", "check_a": "B。两种来源互相印证，就是二重证据法的互证性；A、C、D都犯了绝对化、单一化的毛病。"}, {"subject": "历史", "question_no": "11", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "知识盲区", "knowledge_point": "汉代中朝崛起：决策权由外朝丞相转向以皇帝为首的中朝，皇权集中", "note": "", "stem": "史料记载，汉武帝时“以（原属少府的）尚书掌文书，常侍从左右备顾问；丞相总揽百僚，然而事皆决于内朝”。至汉元帝时，中朝官弘恭、石显“贵幸倾朝，百僚皆敬事”。这一变化反映的实质是（ ）", "paper_cause": "**概念不清**——题目问\"实质\"，她停在\"丞相职能变化\"的表象，没看到内朝兴起的实质是皇帝收权、决策权向皇帝集中", "key": "历史|11|1", "card_type": "redo", "options": {"A": "丞相职能从决策转向执行", "B": "内朝官僚化威胁皇权", "C": "行政体系专业化程度提升", "D": "决策权向皇帝集中"}, "teach": "先把两个概念分清：外朝是以丞相为首的正式朝廷机构，掌握决策与行政；内朝（中朝）是皇帝在宫中用尚书、侍中、常侍等亲信组成的小圈子。材料的两句话说的是同一件事：事皆决于内朝，大事已经不由丞相拍板了；中朝官贵幸倾朝、百僚皆敬事，连百官都要看内朝的脸色。决策权正从丞相手里转到皇帝和他的亲信手里，实质就是决策权向皇帝集中，正确答案是D。A项丞相职能从决策转向执行，只是表面现象的改述，而且丞相是被架空，并不是改行去做执行。做实质、本质、根本这类题有个固定动作：先问谁的权力变大了、谁的变小了，答案往权力归属上落，基本不会错。B项说内朝威胁皇权，方向正好反了，内朝恰恰是皇帝用来夺权的工具。", "why": "停在丞相职能变化的表象上，没有继续追问决策权最终归了谁。", "check_q": "唐朝实行三省六部制，遇有军国大事，往往由皇帝召集三省长官共同商议。这一制度运行的实质是（ ）A.三省长官的权力高于皇帝 B.相权被分割，皇权得到加强 C.丞相制度正式废除 D.地方权力扩大", "check_a": "B。把相权拆分给三省、最终决策出自皇帝，与汉代内朝一样，实质都是皇权加强；判断实质题，先看权力最终归谁。"}, {"subject": "历史", "question_no": "15", "full_score": 3.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "审题偏差", "knowledge_point": "隋末统治危机：\"吏皆惧法，莫肯赈救\"恰说明法令有效，C\"法令废弛\"与材料矛盾", "note": "", "stem": "《隋书》载，大业九年（613）“百姓废业，屯集城堡，无以自给。然所在仓库，犹大充韧（满），吏皆惧法，莫肯赈救”。材料揭示了隋朝（ ）", "paper_cause": "**审题错误**——材料三层信息（百姓无以自给／官仓充盈／官吏不敢赈救）合起来指向\"统治危机\"，她大概率只抓住\"吏不敢赈", "key": "历史|15|1", "card_type": "redo", "options": {"A": "吏治腐败", "B": "经济发展失衡", "C": "法令废弛", "D": "隋朝统治危机"}, "teach": "这道材料题要把三层信息合起来读：第一层，百姓废业、屯集城堡、无以自给，民生已经崩了；第二层，所在仓库犹大充满，朝廷并不是没有粮食；第三层，吏皆惧法、莫肯赈救，官吏害怕触犯法令，不敢开仓赈灾。三层拼在一起，就是有粮不救、百姓等死，这已经不是某个环节的小毛病，而是整个统治秩序出了大问题，指向统治危机，正确答案是D。你选的C法令废弛，恰恰与材料相反：官吏惧法，说明法令正在被严格执行，甚至严苛到不敢变通。A项吏治腐败，材料里没有贪污受贿的信息，属于无中生有。做题方法：每个选项都回材料里找一句对应证据，找不到、或者与原文反着说的，立即划掉。", "why": "只抓住官吏不救灾一层就选了法令废弛，没发现惧法恰恰证明法令在执行，与所选项直接矛盾。", "check_q": "材料：安史之乱后，藩镇割据，赋税多被地方截留，中央财政困窘，宦官专权，党争不断。这段材料最能揭示唐朝后期的（ ）A.经济繁荣 B.统治危机 C.对外开放 D.文化昌盛", "check_a": "B。割据、财政、专权、党争多个层面的问题叠加，指向整体性的统治危机；材料题要综合全部信息，选概括性最强的选项。"}, {"subject": "历史", "question_no": "19", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 A，无题干无解析", "note": "", "key": "历史|19|1", "card_type": "concept", "teach": "先说清楚：这一题的题干和解析暂时缺失，只剩答题记录（你选B、正确答案A），没法像其他题那样逐项拆解，先不硬编，等补拍到这道原题，再把它换成重做卡。在此之前，用它记一条通用的选择题纪律：第一步时空定位，看清材料的时间、朝代、人物，再检查选项里有没有时代错位的机构、地名、制度，比如唐代的题里出现行省、清代的题里出现三省，时代对不上的选项不用细读就能排除；第二步主体对位，选项的主语是谁做的、谁受益，必须和材料的主语一致，不一致的先排除。很多错题不是知识不会，而是这两步没做，凭眼熟就选了。", "why": "本题题干缺失，具体错因待补拍原题后确认；先按时空定位与主体对位的纪律复盘。", "check_q": "下列选项中，属于唐代政治制度的是（ ）A.行省 B.三省六部 C.军机处 D.内阁", "check_a": "B。行省是元代的，军机处是清代的，内阁是明代的；用时代排除法，时段对不上的选项先划掉。"}, {"subject": "历史", "question_no": "20", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "A", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 A，无题干无解析", "note": "", "stem": "贞观年间，宰相岑文本辞华美，精通典章制度，皇帝文书皆出其手。据此推知，岑文本最有可能供职的部门是（ ）", "paper_cause": "**概念不清**——\"皇帝文书皆出其手\"＝草拟诏令，是中书省的活；她把中书、门下的职能记反了  ## 非选择题（作答未拍", "key": "历史|20|1", "card_type": "redo", "options": {"A": "中书省", "B": "门下省", "C": "尚书省", "D": "枢密院"}, "teach": "三省的职能必须并排着记，一个字都不能反：中书省负责决策、草拟诏令，是出令的；门下省负责审议、封驳，诏令有问题可以退回去，是把关的；尚书省负责执行，统领六部办事，是落实的。记忆口诀是中出、门审、尚行。材料给的信号非常明确：辞华美、精通典章、皇帝文书皆出其手，皇帝的文书都经他的手写出来，这就是草拟诏令，锁定中书省，正确答案是A。再并排看门下省：它管的是审核封驳，尚书省管的是执行。再看D项枢密院，那是宋朝才有的机构，掌军政，与中书省并称二府，唐代的题里出现宋代机构，光靠时代就能排除。你这次选了D，是职能没对上、时代也没把关，双重失守。", "why": "三省职能记反、记混，又没用时代线索排除宋代才有的枢密院。", "check_q": "唐朝某官员发现皇帝下达的诏令有不妥之处，将其封还、拒绝副署。这名官员最可能任职于（ ）A.中书省 B.门下省 C.尚书省 D.礼部", "check_a": "B。封驳（封还诏令）是门下省的专职：中书出令、门下审驳、尚书执行，记住中出、门审、尚行就不会记反。"}, {"subject": "历史", "question_no": "21(2)", "full_score": 8.0, "got_score": 3.0, "student_answer": "（手写，辨认见下）", "std_answer": "背景：商鞅变法推行县制；秦统一六国；法家思想确立。意义：强化中央集权；促进地区交流；贵族政治→官僚政治；后世地方治理基本制度", "error_type": "表述不规范/知识盲区", "knowledge_point": "郡县制推行的背景与意义。背景只写\"战国变法\"太笼统，未点名商鞅变法/县制/秦统一/法家思想；意义答出\"集权、收归地方权力\"，但\"为秦统一奠定基础\"因果倒置（郡县制是统一后推行）", "note": "", "key": "历史|21(2)|1", "card_type": "concept", "teach": "背景加意义是大题最常见的组合问法，各有固定框架。背景这样凑：①制度基础，商鞅变法时已在秦国推行县制，有现成经验；②政治条件，秦统一六国，需要管理空前辽阔的疆域；③集权需要，要废除分封、防止诸侯割据重演；④思想依据，法家思想提供支持。意义这样凑：①对中央，加强中央集权，郡县长官由皇帝直接任免；②对地方治理，官僚政治取代世袭贵族政治；③对后世，成为历代地方行政的基本制度；④对统一，促进各地交流、巩固统一。你丢分有两处：一是背景只写战国变法太空，没点名商鞅变法和县制；二是因果写反了，郡县制是统一之后才全面推行的，不能写成为秦统一奠定基础，统一是它的背景，不是意义。写意义前，先过一遍时间顺序。", "why": "背景没点名商鞅变法、县制等关键词，还把统一这个背景误写成了郡县制的意义，因果倒置。", "check_q": "下列哪一句是郡县制的意义而不是背景？A.商鞅变法在秦国推行县制 B.秦统一六国后疆域空前辽阔 C.郡县制使官僚政治取代贵族政治，成为后世地方治理的基本制度 D.法家思想受到秦王朝推崇", "check_a": "C。A、B、D都是推行郡县制之前已经存在的条件，属于背景；C说的是推行之后产生的影响，属于意义。判断标准就是看时间在前还是在后。"}, {"subject": "历史", "question_no": "22(1)", "full_score": 6.0, "got_score": 2.0, "student_answer": "（手写，辨认见下）", "std_answer": "任答三点：圩田/闸坝灌溉体系；开田万顷；岁增粟帛；耕作效率提高", "error_type": "表述不规范", "knowledge_point": "江南农业发展的表现。未用关键词（圩田、灌溉体系、开田万顷、岁增粟帛），表述混乱", "note": "", "key": "历史|22(1)|1", "card_type": "concept", "teach": "表现类设问有个特点：答案几乎全在材料里，不用你发明，只需要提取信息再换成关键词。这则材料里现成的得分词是：杜预在荆州修陂塘（水利设施）、太湖流域修圩田（围湖造田、配闸坝形成灌溉体系）、开田万顷（耕地面积扩大）、岁增粟帛（粮食和布帛产量增加）、耕作效率提高，任答三点就能拿满。你只得2分，问题不在不懂，而是答题动作错了：脱离材料自己组织语言，写得又乱又没有关键词，阅卷按点给分，自然找不到得分点。固定动作是：先在材料上把关键短语逐个划出来，答案就照着划线处改写成短句，一点一行、序号标清，宁可像抄材料，也不要自由发挥。", "why": "脱离材料自己编话，没有提取圩田、灌溉体系、开田万顷等关键词，阅卷按点找不到得分点。", "check_q": "材料：宋代，江南地区水稻种植面积大增，占城稻得到推广，苏州、湖州成为重要粮仓，民间有苏湖熟、天下足的谚语。请用三个关键词概括这一时期江南农业发展的表现。", "check_a": "①种植面积扩大（水稻推广、占城稻引进）；②粮食产量大增（苏湖成为重要粮仓）；③经济地位上升（苏湖熟、天下足）。表现题就是从材料里提炼关键词短句，不用自编。"}, {"subject": "历史", "question_no": "22(2)", "full_score": 6.0, "got_score": 2.0, "student_answer": "（手写，辨认见下）", "std_answer": "任答三点：北民南迁；曲辕犁/龙骨水车/圩田水利；土断/赋税改革/漕运；政府重视水利", "error_type": "知识盲区/表述不规范", "knowledge_point": "江南农业发展的主要因素。自编\"气候适宜\"非得分点；\"北民南迁/朝廷重视\"方向对但缺关键词（曲辕犁、土断、漕运）", "note": "", "key": "历史|22(2)|1", "card_type": "concept", "teach": "因素、原因类设问，用人口、技术、政策、环境四维框架往里装。这道题的标准得分点是：①人口，北方人口南迁带来劳动力，土断政策把南迁人口编入户籍；②技术，曲辕犁、龙骨水车等农具进步，加上圩田水利；③政策，政府重视农业，赋税改革、漕运开通保障流通。你写的气候适宜为什么不得分？因为设问问的是这一时期推动发展的因素，气候几千年来一直适宜，它是背景条件，不是这一时期新出现的推动变量，阅卷不会给分。你想到的北民南迁、朝廷重视方向是对的，可惜没有落到土断、曲辕犁、漕运这些术语上。记住：因素题专挑这一时期新出现的变化来写，并且尽量用课本原词。", "why": "把恒常的自然条件当成了推动因素，想到的方向又写成了大白话，没有落到土断、曲辕犁等关键词上。", "check_q": "下列哪项最适合作为魏晋南北朝时期江南得到开发的推动因素？A.江南气候温暖湿润 B.北方人口大量南迁，带来劳动力和技术 C.江南雨量充沛、河流众多 D.江南自古就是鱼米之乡", "check_a": "B。A、C、D都是长期存在的自然或历史条件，不是这一时期新出现的变量；推动因素要选这一时期发生的新变化。"}, {"subject": "历史", "question_no": "23", "full_score": 12.0, "got_score": 6.0, "student_answer": "（手写，辨认见下）", "std_answer": "主题(3)+三部分标题(3×1)+内容方向(3×2)：背景/学派人物主张/历史影响", "error_type": "审题偏差/表述不规范", "knowledge_point": "百家争鸣。三段结构完整；背景、学派部分部分踩点；第三部分写\"秦统一终结百家争鸣（焚书坑儒）\"，偏离\"对后世文化与治理的实践价值\"得分方向；主题句潦草难辨", "note": "", "key": "历史|23|1", "card_type": "concept", "teach": "这是一道策划学习手册的活动设计题，给分点就写在题目里：主题3分，三个部分的目录标题各1分，每个部分的内容方向各2分，共12分。你的结构是完整的，丢分丢在第三部分的方向上：你写了秦统一终结百家争鸣、焚书坑儒，这属于政治史的后续事件，偏离了手册思想文化的主题；这一部分应该写百家争鸣的历史影响与价值，比如儒家思想成为传统文化主流、法家思想影响后世治理、道家思想滋养文艺、各家争鸣开创了学术自由讨论的传统。还有一个小失分：主题句潦草难辨，阅卷看不清就等于没写。这类题动笔前先把给分点在草稿上拆开（主题加3个目录加3个方向），逐项配齐内容再写，方向必须紧扣题目限定的主题词。", "why": "第三部分写偏到秦统一、焚书坑儒的政治事件，脱离思想文化主题；主题句又潦草难辨。", "check_q": "为百家争鸣学习手册设计第三部分历史影响，下列内容方向最合适的是（ ）A.秦始皇焚书坑儒的经过 B.儒、法、道思想对后世文化与治理的深远影响 C.诸子百家的生平年表 D.春秋战国的战争进程", "check_a": "B。手册主题是思想文化，影响部分要落在思想对后世文化与治理的价值上；A、D偏政治军事，C是人物资料而非影响。"}, {"subject": "地理", "question_no": "5", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "B", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|5|1", "card_type": "concept", "teach": "太阳大气由里到外分三层：光球层、色球层、日冕层。活动与层对应着记：光球层上是黑子（温度比周围低，所以显得暗）；色球层上是耀斑和日珥；日冕层向外吹出太阳风。最易混的两点：第一，黑子在光球、耀斑在色球，别记串层；第二，太阳活动强弱的主要标志是黑子，周期约11年，耀斑是太阳活动最激烈的显示。影响也成串记：扰乱电离层、干扰无线电短波通信；扰动地球磁场产生\"磁暴\"；在两极高纬地区产生极光；还可能影响气候。判断顺序固定为\"先定位是哪一层，再想这一层对应什么活动、什么影响\"，不要看到\"太阳活动\"就凭眼熟乱选。", "why": "她选C、正解B；同一张卷的太阳大气填空她能答对，说明知识是碎片化的——记住了词，却没把\"层—活动—影响\"对应成链来记。", "check_q": "太阳黑子和耀斑分别位于太阳大气的哪一层？太阳活动强弱的主要标志是什么？", "check_a": "黑子在光球层，耀斑在色球层；主要标志是黑子的多少，周期约11年。"}, {"subject": "地理", "question_no": "6", "full_score": 2.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|6|1", "card_type": "concept", "teach": "地质年代表的层级从大到小是：宙—代—纪。最常考的对调坑有两个：第一，古生代和中生代——古生代是早期生命的时代，无脊椎动物和鱼类繁盛，两栖类出现；中生代是\"爬行动物的时代\"，恐龙繁盛，末期恐龙灭绝，鸟类和小型哺乳动物出现。第二，新生代和第四纪不是同一级：新生代是\"代\"，第四纪是新生代里面最新的一\"纪\"，人类就出现在第四纪。记法：问\"哪个时代有什么动物\"先定位到代（古—中—新按先后排），问\"人类出现\"直接答第四纪、属新生代。层级和先后是两个维度，出题人最爱把它们交叉起来挖坑，必须分开记。", "why": "她选B、正解D；同卷综合题里她把爬行动物繁盛答成古生代、把第四纪与新生代并列，层级和先后两个维度都没分开，这道题是同一毛病的复现。", "check_q": "恐龙繁盛和恐龙灭绝发生在哪个代？人类出现在哪个纪，它属于哪个代？", "check_a": "都在中生代（繁盛于中生代，灭绝于中生代末期）；人类出现在第四纪，第四纪属于新生代。"}, {"subject": "地理", "question_no": "10", "full_score": 2.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|10|1", "card_type": "concept", "teach": "地球内部圈层靠两个界面和一串数字记。由外到内：地壳—莫霍界面（平均深度约17千米）—地幔—古登堡界面（地下约2900千米）—地核。地幔中，上地幔顶部有一层熔融状的软流层，它是岩浆的主要发源地；软流层以上的地壳加上地幔顶部，合称岩石圈——岩石圈不等于地壳，这是最常见的对调坑。探测靠地震波：纵波速度快，固、液、气三态都能传播；横波速度慢，只能在固体中传播；横波在古登堡界面附近消失，正是推断外核为液态的证据。数字只钉三个：17（莫霍平均深度）、2900（古登堡深度）、软流层在上地幔。", "why": "她选A、正解D；同卷综合题里她把古登堡界面深度记成了4000、软流层位置也答错，这道选择题大概率栽在同一组数字和位置上——纯记忆点没钉死。", "check_q": "古登堡界面位于地下约多少千米？岩石圈由哪两部分组成？", "check_a": "约2900千米；岩石圈由地壳和上地幔顶部（软流层以上部分）组成。"}, {"subject": "地理", "question_no": "11", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|11|1", "card_type": "concept", "teach": "大气的受热过程整条链只记一句话：太阳暖大地、大地暖大气、大气还大地。展开成三段：第一段，太阳辐射（短波辐射）穿过大气时只被削弱一小部分，大部分到达地面，地面吸收后增温；第二段，地面增温后放出地面辐射（长波辐射），对流层大气中的水汽、二氧化碳强烈吸收地面辐射，大气随之增温——所以地面是近地面大气主要的、直接的热源，大气直接吸收的太阳辐射很少；第三段，大气增温后也向外辐射，其中射向地面的部分叫大气逆辐射，把热量还给地面，起保温作用。做这类题先定位题目问的是哪一段：问\"大气热源\"答地面辐射，问\"夜间保温\"答逆辐射，三段不能串。", "why": "她所在的11—14题组连续四道全错，说明整条受热链在她脑子里是散的；做题时没先定位\"问的是哪一段\"，就凭环节名称的眼熟程度乱选。", "check_q": "近地面大气主要的、直接的热源是什么？", "check_a": "地面（地面辐射）。大气对太阳短波辐射吸收很少，大部分太阳辐射到达地面；地面放出的长波辐射绝大部分被大气吸收。"}, {"subject": "地理", "question_no": "12", "full_score": 2.0, "got_score": 0.0, "student_answer": "A", "std_answer": "C", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|12|1", "card_type": "concept", "teach": "大气对太阳辐射的削弱作用有三种形式，靠例子分清：吸收——有选择性，如臭氧吸收紫外线、水汽和二氧化碳吸收红外线；反射——无选择性，云层和较大的尘埃颗粒把太阳辐射反射回宇宙空间，云越厚反射越强，阴天白天凉爽主要靠它；散射——有选择性，空气分子散射波长较短的蓝紫光，所以晴朗的天空呈蔚蓝色。最要紧的一对辨析是\"反射\"和\"大气逆辐射\"：反射发生在太阳辐射到达地面之前，把短波辐射挡回去；逆辐射发生在地面增温之后，把长波热量还回来，时间和方向都正好相反。选项里把这两个词互换着说，基本就是错误项。", "why": "她选A、正解C；她在同卷大题中明确把\"大气逆辐射\"写成了\"反射\"，削弱作用里的反射和保温作用里的逆辐射在她那里是一个模糊印象，没有按发生时机分开。", "check_q": "阴天时白天不太热、夜晚不太冷，分别主要与哪种作用有关？", "check_a": "白天不太热：云层反射作用强，削弱了到达地面的太阳辐射；夜晚不太冷：云层使大气逆辐射增强，保温作用强。"}, {"subject": "地理", "question_no": "13", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|13|1", "card_type": "concept", "teach": "保温作用的完整链条是：地面吸收太阳辐射后增温，放出地面辐射；大气几乎全部吸收地面长波辐射而增温；大气增温后产生大气辐射，其中射向地面的部分叫大气逆辐射，它把大部分热量返还地面，弥补地面损失的热量——这就是大气的保温作用（温室效应）。三个要点钉死：第一，逆辐射的方向是大气射向地面，和\"反射回宇宙空间\"正好相反，把它写成\"反射\"是她在综合题里丢整段分的原话错误；第二，逆辐射强弱看水汽、二氧化碳和云量，阴天、多云的夜晚逆辐射强、气温较高，晴朗的夜晚逆辐射弱、容易出现霜冻；第三，题干问\"保温\"时，只认逆辐射这一个关键词。", "why": "她选C、正解A；这正是她整张地理卷的病根——综合题27(2)她把大气逆辐射直接写成\"反射\"、夜间保温机制整段没答，这道选择题错在同一处。", "check_q": "为什么晴朗的秋夜比阴雨的秋夜更容易出现霜冻？", "check_a": "晴天云少，大气逆辐射弱、保温作用差，地面热量散失快，降温幅度大，容易结霜；阴雨天云层厚，逆辐射强，降温慢。"}, {"subject": "地理", "question_no": "14", "full_score": 2.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|14|1", "card_type": "concept", "teach": "对流层的气温规律只有一句：随高度升高而降低，平均每升高100米，气温下降约0.6℃。原因紧接着记：对流层大气的直接热源是地面，离地面越远，获得的地面辐射越少，所以越高越冷，这就是\"高处不胜寒\"、山顶积雪的原理。再分清一个例外：逆温——某层大气中气温随高度升高反而升高，多出现在晴朗无风的夜间，会阻碍空气对流、加重污染，但它不是对流层的常态。最易串的对子是平流层：平流层恰恰随高度升高而升高，因为那里有臭氧层吸收紫外线增温。做题先问自己\"题目说的是哪一层\"：对流层答递减，平流层答递增。", "why": "她选B、正解A；同卷综合题里她把对流层气温变化直接答成了\"升高\"，规律是记反了的原样复现——这类一字之差的规律要当口诀背，不能凭感觉。", "check_q": "某山山脚气温28℃、山顶10℃，按对流层气温递减率估算，两地相对高度约是多少米？", "check_a": "温差18℃，18÷0.6×100=3000米。"}, {"subject": "地理", "question_no": "16", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|16|1", "card_type": "concept", "teach": "热力环流是大气运动最基本的形式，成因链按顺序背：地面冷热不均→空气垂直运动（受热处膨胀上升、受冷处收缩下沉）→同一水平面上产生气压差（近地面：上升处形成低压、下沉处形成高压；高空的气压高低与近地面恰好相反）→水平气流由高压流向低压，形成风。两个判断钉子：第一，看等压面——向上凸的地方是高压、向下凹的地方是低压，记\"高凸低凹\"四个字判读所有热力环流图；第二，近地面和高空的气压永远相反，近地面是低压，高空就是高压。经典应用成串记：白天海风、夜晚陆风，城市热岛环流，山谷风。做图题顺序固定：先找冷热源，再画垂直运动，再标气压，最后画风向。", "why": "她选C、正解D；热力环流图里冷热源位置一换，箭头全反，必须按\"冷热—垂直—气压—风向\"的顺序推，她做读图题时习惯凭图形眼熟下手，顺序意识缺位。", "check_q": "白天沿海地区吹海风还是陆风？用热力环流原理解释近地面风向。", "check_a": "吹海风。白天陆地增温快，空气上升，近地面形成低压；海洋相对较冷，空气下沉形成高压；近地面风由海洋（高压）吹向陆地（低压）。"}, {"subject": "地理", "question_no": "24", "full_score": 2.0, "got_score": 0.0, "student_answer": "B", "std_answer": "A", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|24|1", "card_type": "concept", "teach": "我国年太阳辐射总量的分布记两句：西多东少、南多北少——但两个方向的原因完全不同，这是出题核心。东西差异的主因是天气状况：西部内陆降水少、晴天多，太阳辐射强；东部季风区阴雨天多、云量大，削弱作用强。南北差异的主因是纬度因素：纬度越低，正午太阳高度角越大，获得的太阳辐射越多。再钉两个极值：最丰富的是青藏高原（海拔高、空气稀薄、晴天多），最贫乏的是四川盆地（阴雨、云雾天多）。做题配对口诀：看到\"东西差异\"先想降水和晴天数，看到\"南北差异\"先想纬度；海拔只是青藏高原这一个点的原因，不能拿来解释全国的东西差异。", "why": "她选B、正解A；同卷28(1)她把太阳辐射东西差异的主因误答为海拔高度，与青藏高原的思路串了题，这道选择题极可能错在同一个原因配对上。", "check_q": "我国太阳辐射总量最丰富和最贫乏的地区分别是哪里？主要原因各是什么？", "check_a": "最丰富：青藏高原（海拔高、空气稀薄、晴天多，削弱作用弱）；最贫乏：四川盆地（阴雨、云雾天多，大气削弱作用强）。"}, {"subject": "地理", "question_no": "25", "full_score": 2.0, "got_score": 0.0, "student_answer": "C", "std_answer": "D", "error_type": "待题干", "knowledge_point": "待题干", "note": "", "key": "地理|25|1", "card_type": "concept", "teach": "青藏高原是这张卷最值得背透的辨析：同一个地方，太阳辐射最强，气温却偏低，靠的是两个方向相反的作用。先看削弱：高原海拔高、空气稀薄，水汽和尘埃少，晴天又多，太阳辐射被削弱得少，所以到达地面的辐射强。再看保温：空气稀薄意味着吸收地面辐射的能力差，大气逆辐射也弱，地面热量容易散失，所以气温低。结论句要记牢：辐射强弱看\"削弱\"，气温高低看\"保温\"，两个问题用两套机制回答。她在综合题里写过\"太阳辐射强度与气温成反比\"——这就是把两套机制混成一句话的错误表述；凡看到\"辐射强所以气温低\"\"成反比\"这类结论句，先判错，再回到削弱与保温分头找原因。", "why": "她选C、正解D；同卷28(2)这道大题她得0分，原话就是把削弱作用和保温作用混为一谈、得出\"成反比\"的错误结论，这道选择题是同一病根的复现。", "check_q": "\"太阳辐射越强的地方气温就越高\"为什么不对？用青藏高原说明。", "check_a": "不对。青藏高原太阳辐射最强，但空气稀薄、大气逆辐射弱、保温作用差，气温反而偏低。辐射强弱由削弱作用决定，气温高低还取决于保温作用，两者不是一回事。"}, {"subject": "政治", "question_no": "9", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "C", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 C，无题干无解析", "note": "", "key": "政治|9|1", "card_type": "concept", "teach": "教材原话：1919年五四运动标志着中国新民主主义革命的开端。判断\"开端\"要看三点新变化：第一，工人阶级开始以独立的姿态登上政治舞台，成为运动后期的主力；第二，五四运动促进了马克思主义在中国的传播，并开始同中国工人运动相结合；第三，先进知识分子开始走同工农相结合的道路。两个易混点要分清：一是时间，五四运动在1919年，发生在1921年建党之前，领导者是先进青年知识分子，还不是共产党；二是\"开端\"问的是新变化从哪一年出现，不是党哪一年成立。把开端记成1921年（建党），是这类题最常见的坑。", "why": "原题题干未留存，但紧挨着的第10题她把新旧民主主义革命的范畴也判错了，说明\"五四开端\"这一段的时间锚和新变化她没有成串记牢。", "check_q": "新民主主义革命的开端是哪个事件、发生在哪一年？", "check_a": "1919年五四运动。它使工人阶级登上政治舞台、马克思主义开始与工人运动相结合，革命面貌从此不同于旧民主主义革命。"}, {"subject": "政治", "question_no": "10", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 D，无题干无解析", "note": "", "key": "政治|10|1", "card_type": "concept", "teach": "新旧民主主义革命的分界线是五四运动，区别要成对记四组：领导阶级——旧：资产阶级；新：无产阶级（通过中国共产党领导）。所属范畴——旧民主主义革命属于资产阶级革命的范畴，是世界资产阶级革命的一部分；新民主主义革命属于无产阶级革命的范畴，是世界无产阶级社会主义革命的一部分。老师在她卷子上批的\"旧：资产阶级\"点的就是这一组。革命前途——旧：建立资产阶级共和国、走资本主义道路；新：前途是社会主义。革命任务相同——都反帝反封建，这是两者唯一的共同点，也是干扰项最爱做文章的地方：任务相同不等于性质相同，判断性质先看领导阶级。", "why": "她在\"新旧民主主义革命均属于世界无产阶级革命的一部分\"这类表述上栽了跟头，只记住了任务相同，没抓住领导阶级这个根本分界。", "check_q": "\"新旧民主主义革命都属于世界无产阶级革命的一部分\"——这句话错在哪？", "check_a": "旧民主主义革命由资产阶级领导，属于资产阶级革命范畴，是世界资产阶级革命的一部分；只有新民主主义革命由无产阶级领导，属于世界无产阶级革命的一部分。"}, {"subject": "政治", "question_no": "15", "full_score": 3.0, "got_score": 0.0, "student_answer": "B", "std_answer": "D", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 D，无题干无解析", "note": "", "stem": "我国的改革开放创造了发展奇迹，今后还要以更大气魄深化改革、扩大开放，续写更多\"春天的故事\"。我国的改革开放不是一蹴而就的。下列关于我国改革开放的进程，排序正确的是（ ）①我国成功加入世界贸易组织（2001年）②设立中国（上海）自由贸易试验区（2013年）③推行家庭联产承包责任制（1978年起）④明确实施社会主义市场经济体制（1992年）", "paper_cause": "**记忆缺失**——四个大事件的时间顺序没记牢，尤其\"确立社会主义市场经济体制（1992）\"与\"入世（2001）\"的先后", "key": "政治|15|1", "card_type": "redo", "options": {"A": "①②③④", "B": "③①④②", "C": "④③①②", "D": "③④①②"}, "teach": "排序题不靠感觉，给每个事件钉一个年份锚：③1978年——改革从农村起步，家庭联产承包责任制是改革开放的开端标志；④1992年——党的十四大明确提出建立社会主义市场经济体制的目标；①2001年——加入世界贸易组织，对外开放进入新阶段；②2013年——上海自贸试验区设立，是全面深化改革开放的新动作。最容易对调的是④和①：记住\"先定自家的市场经济体制（1992），再融入世界市场（2001）\"。四个锚连成一句口诀：78承包、92市场、01入世、13自贸，排任何改革开放时序题都按这条链对号。", "why": "她把1992年确立市场经济体制和2001年入世的先后记反了，四个事件只记了大概，没有逐个钉住年份。", "check_q": "按时间先后排列：设立上海自贸试验区、确立社会主义市场经济体制目标、推行家庭联产承包责任制、加入世贸组织。", "check_a": "家庭联产承包责任制（1978）→确立社会主义市场经济体制目标（1992）→加入世贸组织（2001）→设立上海自贸试验区（2013）。"}, {"subject": "政治", "question_no": "17", "full_score": 3.0, "got_score": 0.0, "student_answer": "A", "std_answer": "C", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 C，无题干无解析", "note": "", "stem": "习近平总书记指出，尽管我们所处的时代同马克思所处的时代相比发生了巨大而深刻的变化，但从世界社会主义500年的大视野来看，我们依然处在马克思主义所指明的历史时代。这表明（ ）①科学社会主义是人类社会的终极真理 ②（原卷字迹不清） ③科学社会主义依然具有真理的光芒和改造现实的力量 ④中国特色社会主义是科学社会主义在中国的实践与发展", "paper_cause": "**概念不清**——没识破\"终极真理\"这类绝对化表述的坑", "key": "政治|17|1", "card_type": "redo", "options": {"A": "①②", "B": "①④", "C": "②③", "D": "③④"}, "teach": "组合选择题的固定打法：先逐项判断、杀绝对化表述，再对组合。①\"终极真理\"是经典错误项——科学社会主义是科学真理，但它随着实践不断丰富和发展，不存在一成不变的\"终极\"形态；凡出现\"终极、永恒不变、彻底解决一切\"这类把话说死的词，先划掉，含①的A、B随之排除，只在C、D里选。再看题干指向：题干强调\"时代变了，但我们依然处在马克思主义所指明的历史时代\"，扣住\"依然\"二字——资本主义基本矛盾没有变，所以③\"依然具有真理的光芒和改造现实的力量\"正是对题干的回应。记住顺序：先排绝对化、再对题干指向、最后对组合，不要从组合倒推。", "why": "她没识破①\"终极真理\"的绝对化陷阱，第一步逐项判断就漏了，把含错误项的组合选了进去。", "check_q": "判断正误：\"科学社会主义揭示了人类社会发展的最终规律，是不可超越的终极真理。\"", "check_a": "错。科学社会主义是发展的、开放的真理，随着实践深化不断丰富，不存在\"终极真理\"；这类把话说死的绝对化表述在政治选择题里基本都是错误项。"}, {"subject": "政治", "question_no": "20", "full_score": 3.0, "got_score": 0.0, "student_answer": "D", "std_answer": "B", "error_type": "知识盲区（题干待补）", "knowledge_point": "未知：标准答案仅有选项 B，无题干无解析", "note": "", "key": "政治|20|1", "card_type": "concept", "teach": "十一届三中全会的核心动词是\"重新确立\"，不是\"首次确立\"。教材表述：这次全会重新确立了马克思主义的思想路线、政治路线和组织路线——这些路线本来就有，是被\"文化大革命\"破坏后又恢复的，只能说\"重新\"，说\"首次\"就错。再并排记三件大事：一是作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策；二是实现了新中国成立以来党的历史上具有深远意义的伟大转折；三是开启了改革开放和社会主义现代化建设新时期。三个动词各配各的对象：路线是\"重新确立\"，工作中心是\"转移\"，历史地位是\"伟大转折\"，出题人最爱把这三个动词互相换位，换一个就错。", "why": "她没分清\"首次\"和\"重新\"——\"文革\"后恢复原有正确路线只能叫重新确立，这正是出题人埋的一字之差。", "check_q": "\"十一届三中全会首次确立了马克思主义的思想路线\"错在哪里？准确表述是什么？", "check_a": "错在\"首次\"。马克思主义思想路线本来就存在，是十一届三中全会\"重新确立\"了它（连同政治路线、组织路线）。"}, {"subject": "政治", "question_no": "21", "full_score": 10.0, "got_score": 4.0, "student_answer": "（手写，辨认见下）", "std_answer": "①是历史进步(1)+②生产关系适应生产力规律/判断标准(3)+③原始社会末期阻碍生产力、奴隶制组织大协作(3)+④金属工具/城市/脑体分工(3)", "error_type": "表述不规范/知识盲区", "knowledge_point": "奴隶社会代替原始社会的进步性。答出\"历史进步\"+\"生产力被束缚/相适应\"等零散表述；缺\"金属工具、城市出现、脑体分工\"等具体史实得分点，未展开论证", "note": "", "key": "政治|21|1", "card_type": "concept", "teach": "材料题答法固定三段：先写观点句，再写规律句，最后落到具体史实论据——她丢分最狠的正是第三段。本题得分点清单（10分）：①观点（1分）：奴隶社会代替原始社会是历史的进步；②规律（3分）：判断社会形态更替是进步还是倒退，标准是生产关系是否适应生产力发展要求，原始社会末期的生产关系已经束缚了生产力；③奴隶制解放生产力（3分）：奴隶主可以组织大规模协作劳动，生产规模扩大；④具体表现（3分）：金属工具广泛使用、城市出现、脑体分工出现，为文化繁荣创造条件。组织答案时按\"观点句+教材规律表述+材料关键词/史实\"逐点排，老师扫关键词给分：只写观点和规律、不落史实，最多拿到4分左右。", "why": "她整段只写了\"是历史进步\"和\"生产力被束缚/相适应\"的零散原话，金属工具、城市、脑体分工一个都没写，论证空转，10分丢了6分。", "check_q": "论证\"奴隶社会代替原始社会是进步\"，必须写出的两个具体史实是什么？", "check_a": "示例：金属工具的广泛使用、城市的出现（或脑体分工的出现）。只写观点和规律不落史实，拿不到论据分。"}, {"subject": "政治", "question_no": "22", "full_score": 8.0, "got_score": 2.0, "student_answer": "（手写，辨认见下）", "std_answer": "①四个\"彻底结束\"+伟大飞跃(3)+②过渡前提/改变发展方向/展示前景(3)+③东方战线/世界政治力量对比/鼓舞被压迫民族(2)", "error_type": "知识盲区/表述不规范", "knowledge_point": "新中国成立的意义。未用关键词（彻底结束、半殖民地半封建、人民民主、过渡前提、东方战线），表述空泛", "note": "", "key": "政治|22|1", "card_type": "concept", "teach": "\"意义类\"材料题按\"对内—过渡—对外\"三层组织，每层一句观点句加教材原词。本题得分点清单（8分）：①\"四个彻底结束\"（3分）——彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，彻底结束了极少数剥削者统治广大劳动人民的历史；中国人民从此站起来了，这是中华民族发展史上的一次伟大飞跃。②过渡前提（3分）——为从新民主主义向社会主义过渡创造了前提条件，中国历史进入新纪元，发展方向就此改变。③国际意义（2分）——壮大了世界和平、民主和社会主义的力量，鼓舞了世界被压迫民族和被压迫人民争取解放的斗争。注意：\"彻底结束\"\"站起来了\"这些原词本身就是得分点，不要用自己的话改写。", "why": "她写了一大段\"为世界作出了贡献、中国摆脱了……\"的空泛表述，\"四个彻底结束\"一个都没写出来，8分只拿到2分。", "check_q": "\"四个彻底结束\"的第一个和最后一个分别是什么？", "check_a": "第一个：彻底结束了旧中国半殖民地半封建社会的历史；最后一个：彻底结束了极少数剥削者统治广大劳动人民的历史。"}, {"subject": "政治", "question_no": "23", "full_score": 10.0, "got_score": 5.0, "student_answer": "（手写，辨认见下）", "std_answer": "①四个面貌+三个飞跃(4)+②必由之路/关键一招(4)+③只有进行时/活力之源(2)", "error_type": "知识盲区（部分）", "knowledge_point": "改革开放的意义。答出\"四个面貌/三个飞跃\"和\"活力之源\"；缺\"必由之路/关键一招\"表述", "note": "", "key": "政治|23|1", "card_type": "concept", "teach": "问\"改革开放为什么是活力之源\"，答案从教材给改革开放的定位表述里组织。得分点清单（10分）：①改变的面貌（4分）：改革开放极大改变了中国的面貌、中华民族的面貌、中国人民的面貌、中华文明的面貌；②实现的飞跃（并入上项）：中华民族迎来了从站起来、富起来到强起来的伟大飞跃，中国人民迎来了从温饱不足到小康富裕的伟大飞跃；③定位表述（4分）：改革开放是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现中华民族伟大复兴的关键一招；④回扣设问（2分）：改革开放只有进行时、没有完成时，是当代中国发展进步的活力之源。答这类题先把教材的\"定位句\"整句默出来再展开——定位句就是分值最重的那几分。", "why": "她写出了\"四个面貌/三个飞跃\"和\"活力之源\"，却漏写了分值最重的\"必由之路、关键一招\"这组定位表述，骨架缺了一根主梁，10分只得5分。", "check_q": "教材给改革开放的两个定位表述：\"坚持和发展中国特色社会主义的＿＿\"和\"决定当代中国命运的＿＿\"。", "check_a": "\"必由之路\"；\"关键一招\"。"}, {"subject": "政治", "question_no": "24", "full_score": 12.0, "got_score": 3.0, "student_answer": "（手写，辨认见下）", "std_answer": "①资本主义道路走不通(3)+②党的诞生与新民主主义革命胜利(3)+③新中国成立改变发展方向(3)+④社会主义改造完成(3)+总结句", "error_type": "知识盲区/表述不规范", "knowledge_point": "只有社会主义能救中国。只有\"资本主义走不通\"+\"一化三改/社会主义改造\"+总结句碎片；缺\"党的诞生与新民主主义革命胜利\"\"新中国成立改变发展方向\"两大得分块", "note": "", "key": "政治|24|1", "card_type": "concept", "teach": "\"只有社会主义才能救中国\"是证明型材料题，用四段骨架答，每段一句观点句加教材关键词：①旧路走不通（3分）——农民阶级、地主阶级、资产阶级改良派和革命派的探索都失败了，资本主义道路在中国走不通；②党找到新路（3分）——中国共产党的诞生使中国革命面貌焕然一新，党领导人民取得新民主主义革命的胜利；③新中国改变方向（3分）——中华人民共和国的成立实现了民族独立、人民解放，为国家富强、人民幸福和向社会主义过渡创造了前提，中国的发展方向从此根本改变；④改造建制度（3分）——社会主义改造完成，确立了社会主义基本制度。最后加一句总结回扣题干。动笔前先在草稿上列①②③④四个小标题再填内容，就不会写成词语串烧。", "why": "她只写了\"资本主义走不通\"和\"一化三改\"两个碎片，中间\"党的诞生与革命胜利\"\"新中国成立改变方向\"两大段全空，12分只得3分。", "check_q": "用四段骨架复述\"只有社会主义才能救中国\"的论证顺序（只说每段主题词）。", "check_a": "①资本主义道路走不通→②共产党诞生、新民主主义革命胜利→③新中国成立、改变发展方向→④社会主义改造完成、确立社会主义制度。"}, {"subject": "数学", "question_no": "4", "full_score": 5.0, "got_score": 0.0, "student_answer": "在 B 与 C 之间反复涂改（先写 B 划掉，又改 C），两个都是错的；旁边虽写了\"x−2≠0\"的提醒，仍未选对。", "std_answer": "D。分式不等式要求分母不为零，x=2 必须排除：分子零点 x=1 可取，分母零点 x=2 不可取，故解集为 x≤1 或 x>2。B 错在把 x=2 包含进去，C 则整体方向都错。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "分式不等式的解法（分母不为零、零点取舍）", "note": "错因：概念不清——\"≥0 时分母也不能为零\"这条规则没有落实，在两个错误选项间摇摆。", "stem": "不等式 (x−1)/(x−2) ≥ 0 的解集为（ ）", "paper_cause": "概念不清——\"≥0 时分母也不能为零\"这条规则没有落实，在两个错误选项间摇摆。", "key": "数学|4|1", "card_type": "redo", "options": {"A": "{x | 1≤x≤2}", "B": "{x | x≤1 或 x≥2}", "C": "{x | 1≤x<2}", "D": "{x | x>2 或 x≤1}"}, "teach": "分式不等式有一条压倒一切的铁律：分母永远不能为零，所以 x=2 无论不等号朝哪、带不带等号都必须排除；而分子可以为零，x=1 可以取。标准解法：把分子零点 1 和分母零点 2 标在数轴上，分成三段逐段试号，正负一目了然，得 x≤1 或 x>2，即 D。B 错就错在写了 x≥2 把 2 包含进去。她其实在旁边写了 x−2≠0 的提醒，却没用上。检验习惯：解集出来后把分母零点代回去自查，凡是包含它的选项直接划掉。", "why": "虽然写了 x≠2 的提醒，最后还是在包含 x=2 的错误选项上摇摆，规则没落实到选项。", "check_q": "不等式 (x+1)/(x−3) ≥ 0 的解集中，x=3 能取吗？x=−1 能取吗？", "check_a": "x=3 不能取（分母为零无意义）；x=−1 能取（分子为零，不等式成立）。"}, {"subject": "数学", "question_no": "6", "full_score": 5.0, "got_score": 0.0, "student_answer": "选 A，卷面红笔订正为 B。", "std_answer": "B。p 的范围 (0,2) 是 q 的范围 (−1,3) 的子集，由 p 可以推出 q，但由 q 推不出 p。题目问的是\"q 是 p 的什么条件\"：q 是 p 的必要不充分条件。她把充分、必要的方向答反了。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "充分条件与必要条件的判断（小范围推出大范围）", "note": "错因：概念不清——充分/必要方向感反了，没有抓住\"谁推出谁\"和\"问的是谁是谁的条件\"。", "stem": "已知 p：0<x<2，q：−1<x<3，则 q 是 p 的（ ）", "paper_cause": "概念不清——充分/必要方向感反了，没有抓住\"谁推出谁\"和\"问的是谁是谁的条件\"。", "key": "数学|6|1", "card_type": "redo", "options": {"A": "充分不必要条件", "B": "必要不充分条件", "C": "充要条件", "D": "既不充分也不必要条件"}, "teach": "判断方向的方法是先写推导链，再套名称：p 的范围 (0,2) 落在 q 的范围 (−1,3) 里面，所以 p⇒q 成立；反过来 q⇒p 不成立（比如 x=2.5 满足 q 但不满足 p）。命名规则：能推出别人的叫充分条件，被别人推出的叫必要条件。q 是被 p 推出的，所以 q 是 p 的必要不充分条件，选 B。口诀“小推大”：小范围是充分、大范围是必要。最后一步务必把答案代回原问法“q 是 p 的__条件”里读一遍，她选 A 就是跳过推导链、把方向读反了。", "why": "没先写 p⇒q 的推导链就直接套名称，把充分和必要的方向答反了。", "check_q": "p：x>3，q：x>1，则 p 是 q 的什么条件？", "check_a": "充分不必要条件。小范围 (3,+∞) 能推出大范围 (1,+∞)，反之不行，p 是充分条件。"}, {"subject": "数学", "question_no": "9", "full_score": 6.0, "got_score": 0.0, "student_answer": "选 AD（卷旁有扣分痕迹）。", "std_answer": "AC。分情况：若 x+2=3，得 x=1，此时 x²−2x=−1，与集合中已有的 −1 重复，违反互异性，舍去；若 x²−2x=3，解得 x=3 或 x=−1，代入检验元素互异均成立。故 x 可为 3 或 −1。她选的 D（x=1）正是被互异性淘汰的情形，漏选的 C（x=−1）反而成立。多选含错选项，一般得 0 分。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "集合元素的互异性（分类讨论后必须回代检验）", "note": "错因：概念不清——只解方程不验互异性，分类讨论\"只求解、不检验\"。", "stem": "设集合 A={−1, x+2, x²−2x}，且 3∈A，则 x 的值可以为（ ）（多选）", "paper_cause": "概念不清——只解方程不验互异性，分类讨论\"只求解、不检验\"。", "key": "数学|9|1", "card_type": "redo", "options": {"A": "3", "B": "−3", "C": "−1", "D": "1"}, "teach": "多选题的纪律是逐项独立验证，含参数的集合题还要多最后一步：回代查互异性。3∈A 分情况讨论：若 x+2=3，得 x=1；若 x²−2x=3，解得 x=3 或 x=−1。关键在回代——x=1 时 x²−2x=−1，与集合里已有的 −1 撞车，违反元素互异性，必须舍去；x=3、−1 代回后三个元素互不相同，保留。所以选 AC。她选的 D(x=1) 恰是被互异性淘汰的。抓手：凡解出参数，落笔前强制自己代回去看一眼元素重不重复，只解方程不检验是这类题的头号死法。", "why": "只解方程选了 AD，没把 x=1 代回检验互异性，正好选进了被淘汰的情形，还漏了 −1。", "check_q": "集合 {2, m, m−3} 中，若 m−3=2，则 m 是多少？这个情形符合元素互异性吗？", "check_a": "m=5，但此时元素为 2、5、2，出现重复，违反互异性，该情形不成立、必须舍去。"}, {"subject": "数学", "question_no": "10", "full_score": 6.0, "got_score": 2.0, "student_answer": "只选 A，选项 C 被她划掉；卷面红笔在多选区标有\"−9\"（与第 9 题全扣 6 分、第 11 题漏选扣 3 分合算，第 10 题应为漏选扣约 3 分，据此推断，存疑度中）。", "std_answer": "AC。A 作差得 (a−b)(a+b+c)>0，成立；C 是真分数\"糖水不等式\"，a>b>1、c>0 时 a/b>(a+c)/(b+c)，成立；B 在 c<1 时不成立；D 等价于 b²>a²，不成立。她把成立的 C 划掉了。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "不等式性质、作差比较法、糖水不等式", "note": "错因：概念不清——对 C 这类分式不等式的判断没有把握，会做 A 的作差法，却在 C 上犹豫误划。（答题卡核定：漏选得2分）", "stem": "若 a>b>1，c>0，则下列不等式一定成立的是（ ）（多选）", "paper_cause": "概念不清——对 C 这类分式不等式的判断没有把握，会做 A 的作差法，却在 C 上犹豫误划。", "key": "数学|10|1", "card_type": "redo", "options": {"A": "a²−bc > b²−ac", "B": "c ≥ (b+ac)/(a+bc)", "C": "a/b > (a+c)/(b+c)", "D": "bc/a > ac/b"}, "teach": "逐项验证：A 用作差法，a²−bc−(b²−ac)=(a−b)(a+b+c)，三个因子都为正，成立；C 是糖水不等式——a/b 是大于 1 的分数，分子分母同加正数 c，分数被“稀释”向 1 靠拢而变小，所以 a/b>(a+c)/(b+c)，成立。她恰恰把对的 C 划掉了，说明对分式大小没直觉。抓手：分式比大小别靠感觉，统一用作差：a/b−(a+c)/(b+c)=c(a−b)/(b(b+c))>0，一算便知。B 取 c=0.5 代入即可举出反例；D 两边约去 c 得 b/a>a/b，等价于 b²>a²，与 a>b 矛盾。", "why": "A 的作差法会用，但 C 没把握、靠感觉划掉，漏选丢了部分分。", "check_q": "若 x>y>0，z>0，比较 x/y 与 (x+z)/(y+z) 的大小。", "check_a": "x/y 更大。作差得 z(x−y)/(y(y+z))>0，所以 x/y>(x+z)/(y+z)（糖水不等式）。"}, {"subject": "数学", "question_no": "11", "full_score": 6.0, "got_score": 2.0, "student_answer": "只选 A。", "std_answer": "AD。A：ab = ½·(2a·b) ≤ ½·((2a+b)/2)² = 1/8，成立；B：1/a+1/b = (2a+b)(1/a+1/b) = 3 + 2a/b + b/a ≥ 3+2√2，不是 4，不成立；C 不成立；D：b=1−2a 代入，a²+b² = 5a²−4a+1，a=2/5 时取最小值 1/5，成立。她漏选了 D。卷面草稿写了 (a+b)²/2 ≤ a²+b²，但没结合 2a+b=1 的条件走通。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "基本不等式、消元法求最值（二次函数配方）", "note": "错因：方法不会——A 用基本不等式能判，但 D 需要消元加配方，她没有这条解题路径，直接漏选。（答题卡核定：漏选得2分）", "stem": "已知正数 a，b 满足 2a+b=1，则（ ）（多选）", "paper_cause": "方法不会——A 用基本不等式能判，但 D 需要消元加配方，她没有这条解题路径，直接漏选。", "key": "数学|11|1", "card_type": "redo", "options": {"A": "ab 的最大值为 1/8", "B": "1/a + 1/b 的最小值为 4", "C": "√(2a) + √b 的最小值为 √2", "D": "a² + b² 的最小值为 1/5"}, "teach": "逐项验证：A 用基本不等式，ab=½·(2a·b)≤½×((2a+b)/2)²=1/8，成立；B 把条件乘进去展开：(2a+b)(1/a+1/b)=3+2a/b+b/a≥3+2√2≈5.83，不是 4，不成立。她漏的 D 没有现成公式可用后备路径——消元：由 b=1−2a 代入，a²+b²=5a²−4a+1，配方得 5(a−2/5)²+1/5，最小值 1/5，成立。抓手：遇到“一次等式条件求二次式最值”，没有公式就消元成一元二次函数配方，这是通用后备打法；她草稿写了 (a+b)²/2≤a²+b² 却没代入条件，等于没走通。", "why": "A 能用基本不等式判断，D 需要消元加配方，她没有这条解题路径，直接漏选。", "check_q": "正数 x、y 满足 x+y=1，x²+y² 的最小值是多少？", "check_a": "消元配方：x²+(1−x)²=2(x−½)²+½，当 x=y=½ 时取最小值 ½。"}, {"subject": "数学", "question_no": "14", "full_score": 5.0, "got_score": 0.0, "student_answer": "写\"B⊆A\"被划改，又写\"A⊇B\"，卷面有订正痕迹，判错。", "std_answer": "A=B。A 是函数 y=x²−2x−8=(x−1)²−9 的值域，为 [−9, +∞)；B 是函数 y=√(x+9) 的定义域，由 x+9≥0 得 [−9, +∞)。两集合完全相同。她草稿里把 A 的最小值 −9、B 的起点 −9 都算出来了，却没意识到两者是同一个区间。", "error_type": "试卷分析（无答题卡）", "knowledge_point": "函数值域与定义域、集合相等与包含的区分", "note": "错因：概念不清——最后一步关系判断失误：两集合相等时写成包含关系，说明\"相等也是包含的特例、问关系时应答最精确者\"没吃透（与第 6 题同属关系类概念薄弱）。  ## 存疑题（不计入确定错题）", "stem": "已知 A={y | y=x²−2x−8, x∈R}，B={x | y=√(x+9)}，那么集合 A 与 B 的关系为 ___。", "paper_cause": "概念不清——最后一步关系判断失误：两集合相等时写成包含关系，说明\"相等也是包含的特例、问关系时应答最精确者\"没吃透（与第", "key": "数学|14|1", "card_type": "redo", "teach": "这类题分两步：先把两个集合分别算到底，再比关系。A 是二次函数 y=x²−2x−8=(x−1)²−9 的值域，为 [−9,+∞)；B 是函数 y=√(x+9) 的定义域，由根号下非负 x+9≥0 得 [−9,+∞)。两边化成区间并排一写，完全相同，关系就是 A=B。她草稿里两个 −9 都算出来了，却写成包含——记住判断原则：相等是包含的特殊情况，题目问“关系”时要答最精确的那个；两个集合互相包含当且仅当它们相等。抓手：比关系前先把两边都化成最简区间，相同就果断写 =。", "why": "A、B 的范围都算对了，最后一步把“相等”写成了“包含”，关系判断不精确。", "check_q": "A={y | y=x²+1}，B={y | y≥1}，A 与 B 是什么关系？", "check_a": "A=B，因为 x²+1 的值域正是 [1,+∞)，与 B 完全相同。"}, {"subject": "数学", "question_no": "5", "full_score": 5.0, "got_score": 0.0, "student_answer": "D", "std_answer": "（见试卷分析补遗）", "error_type": "待定（答题卡坐实错）", "knowledge_point": "见试卷第5题", "note": "答题卡涂卡：选D，判错。题干见数学试卷照片。", "key": "数学|5|1", "card_type": "redo", "stem": "已知集合 A={x | 0≤x<4, x∈N*}，则集合 A 的子集的个数为（ ）", "options": {"A": "32", "B": "16", "C": "8", "D": "4"}, "teach": "子集个数题三步走：先列举、再数数、后套公式。第一步把 A 的元素逐个写出：x∈N* 表示 x 是正整数（N* 从 1 开始，0 不是正整数，哪怕 0 满足 0≤x<4 也不能算），结合 0≤x<4 得 A={1,2,3}；第二步数清元素个数 n=3；第三步套公式：n 个元素的集合有 2ⁿ 个子集，这里 2³=8，选 C。易混点：真子集才是 2ⁿ−1（要再挖掉集合本身）。凡是描述法给出的集合，先翻译成列举法再动手，别凭感觉估 n。", "why": "没先把 A 的元素列出来，元素个数估错，2ⁿ 里的 n 取错，选了 D(4)。", "check_q": "集合 M={x | −1<x<3, x∈Z} 的子集个数是多少？", "check_a": "先列举：M={0,1,2}（注意 x∈Z 包含 0），共 3 个元素，子集个数 2³=8。"}, {"subject": "数学", "question_no": "7", "full_score": 5.0, "got_score": 0.0, "student_answer": "A", "std_answer": "D", "error_type": "方法不会", "knowledge_point": "A∩B=A 即 A⊆B 求参数：必须分 A 为空集与非空集讨论", "note": "正确答案 (−∞,1]。她的草稿只写出 a≤−2 等片断，空集情况讨论不完整。", "key": "数学|7|1", "card_type": "redo", "stem": "已知集合 A={x | a−1≤x≤2a+1}，B={x | −3≤x≤3}，且 A∩B=A，则实数 a 的取值范围是（ ）", "options": {"A": "[−2,1]", "B": "(−2,1)", "C": "(−∞,−2)", "D": "(−∞,1]"}, "teach": "看到 A∩B=A 先翻译成 A⊆B，而由包含关系求参必须先分空集。第一步判空：A 为空集 ⟺ 左端大于右端，即 a−1>2a+1 ⟺ a<−2，此时 A⊆B 自动成立，不能漏。第二步 A 非空（a≥−2）时端点对齐：左端不小于 −3、右端不大于 3，即 a−1≥−3 且 2a+1≤3，得 −2≤a≤1。第三步把两段合并：a≤1，即 (−∞,1]，选 D。她选的 [−2,1] 正是只写了非空的一段。记住口诀：集合求参，空集先行。", "why": "只讨论了 A 非空的情况，漏掉 A 为空集（a<−2）时 A⊆B 也成立，范围少了左边一截。", "check_q": "已知 A={x | 2a≤x≤a+1}，B={x | 0≤x≤3}，若 A⊆B，求 a 的取值范围。", "check_a": "先分空集：A=∅ ⟺ 2a>a+1 ⟺ a>1，此时成立；A≠∅ 时 a≤1，还需左端 2a≥0、右端 a+1≤3，得 0≤a≤1。两段合并：a≥0，即 [0,+∞)。"}, {"subject": "数学", "question_no": "8", "full_score": 5.0, "got_score": 0.0, "student_answer": "C", "std_answer": "A", "error_type": "方法不会", "knowledge_point": "恒成立问题：4/(x+1)+1/(y+2) 用权方和/柯西求最小值", "note": "正确答案 m≤1/16。她用通分硬算，方法笨且算错。", "key": "数学|8|1", "card_type": "redo", "stem": "已知 x>0，y>0，且 x+y=5，若 4/(x+1) + 1/(y+2) ≥ 2m+1 恒成立，则实数 m 的取值范围是（ ）", "options": {"A": "m≤1/16", "B": "m≤2/5", "C": "m≤1/2", "D": "m≤1/4"}, "teach": "恒成立先转最值：'左边 ≥2m+1 恒成立'等价于 2m+1≤左边的最小值，所以核心是求最小值。求法用权方和（柯西）一步到位：把分子 4 看成 2²、1 看成 1²，再换元 a=x+1、b=y+2，则 a+b=(x+y)+3=8，于是 2²/a+1²/b ≥ (2+1)²/(a+b)=9/8。回代：2m+1≤9/8，解得 m≤1/16，选 A。关键动作是换元凑出'分母之和为定值'，而不是通分硬算——通分后式子臃肿、计算量爆炸。等号在 a:b=2:1 时成立，最小值取得到。", "why": "用通分硬算求最小值，方法笨重且算错；没看出换元后分母之和为定值、可用权方和一步求最值。", "check_q": "x>0，y>0，x+y=3，求 1/(x+1) + 4/(y+1) 的最小值。", "check_a": "设 a=x+1、b=y+1，则 a+b=5；权方和：1²/a+2²/b ≥ (1+2)²/5=9/5，最小值为 9/5。"}, {"subject": "数学", "question_no": "13", "full_score": 5.0, "got_score": 0.0, "student_answer": "5<9x−y≤12（两式直接加减）", "std_answer": "[−1, 20]", "error_type": "方法不会", "knowledge_point": "已知 x−y 与 4x−y 范围求 9x−y：待定系数法，不能直接加减", "note": "9x−y = −(5/3)(x−y) + (8/3)(4x−y)，代入两范围得 [−1,20]。", "key": "数学|13|1", "card_type": "redo", "stem": "已知实数 x, y 满足 −4≤x−y≤−1，−1≤4x−y≤5，则 t=9x−y 的取值范围是 ______。", "teach": "这类'已知两个式子的范围、求第三个式子的范围'只能用待定系数法，绝不能把两个不等式直接加减——因为 x、y 在两式中是同一个人、联动的，直接加减等于默认 x、y 能同时取到各自极值，求出的范围会失真。标准三步：设 9x−y=m(x−y)+n(4x−y)，比对系数得 m+4n=9、−m−n=−1，解得 m=−5/3、n=8/3；把已知范围分别乘 m、n（乘负数不等号要变向）后相加：−(5/3)(x−y)∈[5/3,20/3]，(8/3)(4x−y)∈[−8/3,40/3]，相加得 9x−y∈[−1,20]。她写的 5<9x−y≤12 就是直接加减的产物。", "why": "把两个已知不等式直接相加减去凑 9x−y，没意识到 x、y 在两式中联动，不能独立取极值。", "check_q": "已知 −1≤x+y≤3，2≤2x+y≤6，求 3x+2y 的取值范围。", "check_a": "待定系数：3x+2y=(x+y)+(2x+y)，把两范围相加得 [−1+2, 3+6]=[1,9]。"}, {"subject": "数学", "question_no": "15", "full_score": 13.0, "got_score": 8.0, "student_answer": "(1)解集端点写错；(2)A∩B={x|2<x<3}；(3)补集端点含糊", "std_answer": "见讲解", "error_type": "概念不清", "knowledge_point": "集合的并、交、补运算与解集端点开闭", "note": "答题卡得8/13。(1)问解不等式端点出错，连带后面集合范围偏差。", "key": "数学|15|1", "card_type": "concept", "stem": "已知 A={x | −1≤x<3}，B={x | 1<3x−5<16}，求 (1) A∪B；(2) A∩B；(3) ∁_R(A∩B)。满分 13 分，她得 8 分，丢分集中在端点开闭。", "teach": "集合运算先化简、再画数轴，端点开闭全程盯住。第一步解 B：1<3x−5<16 → 6<3x<21 → 2<x<7，两端都是开的。第二步读并集：A∪B 取覆盖范围的最外侧端点——左端 −1 在 A 中是闭（≤）所以并集左端闭，右端 7 在 B 中是开所以并集右端开，得 {x | −1≤x<7}；交集取重叠段 {x | 2<x<3}。第三步补集口诀：端点开闭与原集合正好反过来——A∩B 在 2、3 处都不含，补集里就要含，得 ∁_R(A∩B)={x | x≤2 或 x≥3}。每写一个端点，都回头看一眼原不等式是 ≤ 还是 <。", "why": "B 的化简和交集都会，但写并集、补集时端点开闭出错，没逐个端点回看原不等号。", "check_q": "A={x | 0≤x<2}，B={x | 1<x≤3}，求 A∩B 和 ∁_R(A∩B)。", "check_a": "A∩B={x | 1<x<2}；补集端点反过来取：∁_R(A∩B)={x | x≤1 或 x≥2}。"}, {"subject": "数学", "question_no": "17", "full_score": 15.0, "got_score": 8.0, "student_answer": "讨论了 m=0 成立、m<0 且 Δ<0 得 −4<m<0", "std_answer": "−4<m≤0（第(1)问口径）", "error_type": "表达不规范", "knowledge_point": "含参二次不等式恒成立：分类讨论后结论必须合并完整", "note": "答题卡得8/15。过程讨论基本都在，丢分疑在结论漏并 m=0 或第(2)问不完整。", "key": "数学|17|1", "card_type": "concept", "stem": "已知 f(x)=mx²−mx−1。(1) m=1/2 时求 f(x)<0 的解集；(2) 若 f(x)<0 对一切 x∈R 恒成立，求 m 的取值范围。满分 15 分，她得 8 分。", "teach": "含参二次不等式恒成立，分类框架固定：先单独验 m=0，再看 m≠0 时的'开口方向+Δ'。第 (2) 问要 f(x)<0 恒成立：m=0 时 f(x)=−1<0 成立，先记下不能丢；m≠0 时图像须开口向下（m<0）且与 x 轴无交点（Δ=m²+4m<0），解得 −4<m<0。最后一步最关键——合并结论：把各段取并集，将 m=0 并回去，得 −4<m≤0。她讨论过程基本都在，却疑似收尾时漏并 m=0。记住：分类讨论写完，每种情况都要在最终结论里'对号入座'，写完回头数一遍，一段都不能丢。", "why": "分类讨论的过程基本正确，但最后合并结论时疑似漏并 m=0，结论不完整被扣分。", "check_q": "若关于 x 的不等式 mx²−mx+1>0 对一切 x∈R 恒成立，求 m 的取值范围（注意最后合并结论）。", "check_a": "m=0 时 1>0 成立；m>0 且 Δ=m²−4m<0 得 0<m<4；两段合并：0≤m<4，即 [0,4)。"}, {"subject": "数学", "question_no": "18", "full_score": 17.0, "got_score": 4.0, "student_answer": "设 xy 后列式混乱，出现 x²−30x+500<0 等错误，涂改多", "std_answer": "见讲解", "error_type": "计算失误", "knowledge_point": "基本不等式实际应用（围栏面积最大/材料最省）", "note": "答题卡仅得4/17。试卷草稿上推导基本正确，正式作答却涂改混乱、计算出错——会做但没写对。", "key": "数学|18|1", "card_type": "concept", "stem": "一边靠墙围矩形菜园，长 x 米、宽 y 米。(1) 面积为 36 平方米时，x、y 为何值所用篱笆总长最小？(2) 篱笆总长为 30 米时，把面积 S 表示为长 x 的函数，并求 S≥100 时 x 的范围与 S(x) 的值域。满分 17 分，她只得 4 分。", "teach": "建模三步：设元——先把'一边靠墙'翻译清楚：篱笆总长=x+2y（靠墙的长边不占篱笆）；列约束与目标——(1) 约束 xy=36，目标 x+2y 最小，用基本不等式 x+2y≥2√(2xy)=12√2；(2) 约束 x+2y=30，先解出 y=(30−x)/2 并写定义域 0<x<30，再得目标函数 S=xy=−½x²+15x。她的思路其实在草稿上基本正确，正式作答却另起炉灶、涂改混乱，还把 S≥100 的式子写成 x²−30x+500<0（常数应为 200）。铁规矩：草稿定稿什么样，答题卡就照抄什么结构，誊写时只抄不改。", "why": "草稿上推导基本正确，正式作答却涂改混乱、常数项算错——会做但没写对，草稿与正式作答不一致。", "check_q": "一边靠墙，用 20 米篱笆围矩形菜园（长 x 与墙平行，宽 y），求面积的最大值及此时 x、y 的值。", "check_a": "约束 x+2y=20，S=xy=½·(x·2y)≤½·((x+2y)/2)²=50，当 x=2y 即 x=10、y=5 时取最大，最大值 50 平方米。"}, {"subject": "数学", "question_no": "19", "full_score": 17.0, "got_score": 0.0, "student_answer": "答题卡上写成 mx(2x+1) 一套，得出 m<1", "std_answer": "M=(−∞,0)∪(1,+∞)（草稿结论）", "error_type": "方法不会", "knowledge_point": "含参二次方程/不等式：按 m=0、m<0、m>0 分类讨论", "note": "答题卡得0/17。但她在试卷草稿上讨论完整、结论正确——正式作答写了另一套跑偏解法，没把想通的誊上去。", "key": "数学|19|1", "card_type": "concept", "stem": "已知 ∃x∈R 使 2mx²+mx+1/8<0，实数 m 的取值范围记为集合 M。(1) 求 M；(2) 若集合 N={x | x²+(1−a)x−a>0}，且 'x∈N' 是 'x∈M' 的充分不必要条件，求 a 的取值范围。满分 17 分，她得 0 分。", "teach": "含参二次'存在性'问题框架：∃x 使式子 <0，只需函数能取到负值。逐类验：m=0 时式子恒为 1/8>0，不成立；m<0 开口向下、两端趋于 −∞，必然取到负值，成立；m>0 开口向上，需最小值 <0 即 Δ=m²−m>0，得 m>1。合并 M=(−∞,0)∪(1,+∞)——这些她在草稿上全做对了，却没誊进答题卡，正式作答写了另一套跑偏解法。考场流程铁律：先在草稿完整定稿并圈出结论，再整体誊写、只抄不改；最后留 3 分钟'回誊检查'，逐题核对答题卡与草稿结论是否一致。", "why": "草稿上分类讨论完整、结论正确，却没誊到答题卡，正式作答另写了一套错误解法——做对了但没交上去。", "check_q": "若 ∃x∈R 使 mx²+2x+1<0，求实数 m 的取值范围。", "check_a": "m=0 时 2x+1<0 有解，成立；m<0 开口向下必能取负，成立；m>0 需 Δ=4−4m>0 得 0<m<1。合并：m<1，即 (−∞,1)。"}], "practice": [{"id": "phy-01", "subject": "物理", "type": "single", "points": 4, "knowledge": "时间间隔 vs 时刻", "source": "高一上第一次月考", "stem": "下列计时数据指时间间隔的是（ ）", "options": {"A": "北京时间2026年5月24日23时08分，搭载神舟二十三号载人飞船的长征二号F遥二十三运载火箭在酒泉卫星发射中心点火发射", "B": "某同学在校运动会上110m跨栏成绩是14.10s", "C": "一辆汽车在第10s末开始加速行驶", "D": "我们12时15分开始吃午饭"}, "answer": "B", "explain": "A：2026年5月24日23时08分是时刻，错；B：14.10s是时间间隔，对；C：第10s末是时刻，错；D：12时15分是时刻，错。故选B。"}, {"id": "phy-02", "subject": "物理", "type": "single", "points": 4, "knowledge": "质点模型", "source": "高一上第一次月考", "stem": "下列情形中，可以把人或物体看成质点的是（ ）", "options": {"A": "研究地球的自转", "B": "研究跳水运动员的空中姿态", "C": "观察苏炳添百米赛跑的起跑动作", "D": "测量动车从宁德站到上海站的时间"}, "answer": "D", "explain": "A：研究地球自转需考虑地球大小形状，不能看成质点；B：研究跳水姿态需考虑身体大小形状，不能；C：观察起跑动作需考虑身体，不能；D：测量动车运行时间可忽略动车大小形状，可以看成质点。故选D。"}, {"id": "phy-03", "subject": "物理", "type": "single", "points": 4, "knowledge": "参考系", "source": "高一上第一次月考", "stem": "这是宋代诗人陈与义的一首诗：\"飞花两岸照船红，百里榆堤半日风，卧看满天云不动，不知云与我俱东\"，在诗人看来云是不动的，他选择的参照物是（ ）", "options": {"A": "岸边的江堤", "B": "江边的树", "C": "树上的飞花", "D": "诗人的小船"}, "answer": "D", "explain": "\"不知云与我俱东\"说明相对于地面，诗人与云都向东运动、运动状态相同、相对静止。诗人以自己乘坐的小船为参照物看云，就会出现\"卧看满天云不动\"的效果。故选D。"}, {"id": "phy-04", "subject": "物理", "type": "single", "points": 4, "knowledge": "匀变速直线运动速度与位移关系", "source": "高一上第一次月考", "stem": "【注：原卷中加速度数值转换丢失，据答案反推为5m/s²】航空母舰上有帮助飞机起飞的弹射系统，已知某战斗机离开弹射系统后，在跑道上做加速度大小为5m/s²的匀加速直线运动，战斗机在跑道上自主滑行100m时起飞，飞机离开跑道的速度大小为55m/s，则弹射系统赋予战斗机的初速度大小为（ ）", "options": {"A": "35m/s", "B": "40m/s", "C": "45m/s", "D": "50m/s"}, "answer": "C", "explain": "由 v²−v₀²=2ax 得 v₀=√(v²−2ax)=√(55²−2×5×100)=√(3025−1000)=√2025=45m/s。故选C。"}, {"id": "phy-05", "subject": "物理", "type": "multi", "points": 6, "knowledge": "速度与加速度的关系", "source": "高一上第一次月考", "stem": "关于速度和加速度的关系，下列说法中正确的是（ ）", "options": {"A": "物体的加速度等于零，速度一定等于零", "B": "物体的加速度越大，速度一定越大", "C": "物体的加速度越大，速度一定改变越快", "D": "物体的加速度增大，速度可能减小"}, "answer": "CD", "explain": "A：光滑平面上匀速直线运动的滑块，加速度为零但速度不为零，错；B：a=Δv/Δt，加速度大小与速度大小无关，错；C：加速度是描述速度变化快慢的物理量，对；D：当加速度方向与速度方向相反时，加速度增大、速度减小，对。故选CD。"}, {"id": "phy-06", "subject": "物理", "type": "multi", "points": 6, "knowledge": "位移/路程、平均速度/平均速率、参考系", "source": "高一上第一次月考", "stem": "【注：原卷中部分数字转换丢失，据答案反推复原：路程5.4km、用时1h、M、N直线距离1.8km】一游客在武夷山九曲溪乘竹筏漂流，途经双乳峰附近的M点和玉女峰附近的N点。已知该游客从M点漂流到N点的路程为5.4km，用时1h，M、N间的直线距离为1.8km，则从M点漂流到N点的过程中（ ）", "options": {"A": "该游客的位移大小为5.4km", "B": "该游客的平均速率为5.4km/h", "C": "该游客的平均速度大小为1.8m/s", "D": "若以所乘竹筏为参考系，玉女峰在这段时间内的平均速度大小为0.5m/s"}, "answer": "BD", "explain": "A：位移是M→N的有向线段，大小为1.8km≠5.4km，错；B：平均速率=路程/时间=5.4km/1h=5.4km/h，对；C：平均速度=位移/时间=1.8km/1h=1.8km/h=0.5m/s≠1.8m/s，错；D：以竹筏为参考系，玉女峰相对竹筏运动，位移大小1.8km、时间1h，平均速度大小0.5m/s，对。故选BD。"}, {"id": "phy-07", "subject": "物理", "type": "multi", "points": 6, "knowledge": "初速为零的匀加速直线运动规律", "source": "高一上第一次月考", "stem": "从静止开始做匀加速直线运动的物体，第1s内通过的位移为0.5m，则（ ）", "options": {"A": "第1s末物体的速度为1m/s", "B": "第1s末物体的速度为2m/s", "C": "第1s内物体的平均速度为1m/s", "D": "物体的加速度为1m/s²"}, "answer": "AD", "explain": "由 x=½at² 得 0.5=½×a×1²，a=1m/s²（D对）；第1s末速度 v=at=1×1=1m/s（A对、B错）；第1s内平均速度=x/t=0.5/1=0.5m/s（C错）。故选AD。"}, {"id": "phy-08", "subject": "物理", "type": "multi", "points": 6, "knowledge": "初速为零匀加速直线运动的比例推论", "source": "高一上第一次月考", "stem": "如图所示，光滑斜面AE被分成长度相等的四段（AB=BC=CD=DE），一个物体由A点静止释放后做匀加速直线运动，下面结论中正确的是（ ）", "options": {"A": "经过每一部分时，其速度增量均相同", "B": "物体到达B、C、D、E各点的速度大小之比为1:√2:√3:2", "C": "物体通过AB、BC、CD、DE段所需的时间之比为1:(√2−1):(√3−√2):(2−√3)", "D": "若该物体从A点运动到E点共用时4s，则物体在第2s末的速度等于B点速度"}, "answer": "BD", "explain": "B：由 v²=2ax（初速为0），v∝√x，vB:vC:vD:vE=1:√2:√3:2，对；C：通过连续相等位移时间之比确为1:(√2−1):(√3−√2):(2−√3)，但原卷该选项表述有误，按详解判错；A：每段速度增量Δv=aΔt，各段时间不同，增量不同，错；D：AB:BE=1:3，B为中间时刻（总时间4s），2s末速度=中间时刻速度=vB，对。故选BD。"}, {"id": "phy-09", "subject": "物理", "type": "fill", "points": 4, "knowledge": "平均速度（路程/时间两种情形）", "source": "高一上第一次月考", "stem": "一物体做直线运动，它经过前一半路程的平均速度为6m/s，经过后一半路程的平均速度为9m/s，则物体全过程的平均速度为____m/s。如果它经过前一半时间的平均速度为4m/s，经过后一半时间的平均速度为8m/s，则物体全过程的平均速度为____m/s。", "answer": ["7.2", "6"], "explain": "[1]设总路程为s，前一半路程用时 t1=(s/2)/6=s/12，后一半用时 t2=(s/2)/9=s/18，全程时间 t=s/12+s/18=5s/36，全程平均速度=s/t=7.2m/s。[2]设总时间为t，前一半时间路程=4×(t/2)=2t，后一半=8×(t/2)=4t，总路程=6t，平均速度=6t/t=6m/s。"}, {"id": "phy-10", "subject": "物理", "type": "fill", "points": 10, "knowledge": "x-t图像", "source": "高一上第一次月考", "stem": "某物体沿x轴做直线运动，其位置坐标随时间的变化如图乙所示（x-t图像：t=0时x=2m；0~1s直线上升到x=3m；1~3s保持x=3m不动；3~4s直线下降到x=0；图像据详解数据反推）。在第3s末的坐标为 x3=____m，第4s内物体坐标变化量 Δx=____m；在第1s内物体平均速度为____m/s，在第4s内物体平均速度为____m/s；在前4s内通过的路程是____m。", "answer": ["3", "−3", "1", "−3", "4"], "explain": "[1]第3s末坐标 x3=3m。[2]第4s内坐标变化量 Δx=x末−x初=0−3=−3m（注意符号）。[3]第1s内平均速度 v1=Δx1/t=(3−2)/1=1m/s。[4]第4s内平均速度 v2=(0−3)/1=−3m/s。[5]前4s路程 s=(3−2)+(3−0)=4m（先上后下，路程相加）。"}, {"id": "phy-11", "subject": "物理", "type": "exp", "points": 6, "knowledge": "光电门测瞬时速度、加速度", "source": "高一上第一次月考", "stem": "【注：原卷中数字转换丢失，据答案反推复原】用气垫导轨和光电门测物体的加速度。数字毫秒计记录了遮光板通过第一个光电门的时间为0.125s，通过第二个光电门的时间为0.020s，遮光板从开始遮住第一个光电门到开始遮住第二个光电门的时间为3.00s，已知遮光板的宽度为1.00cm。分别求出滑块通过第一个光电门的速度大小、第二个光电门的速度大小，以及滑块的加速度（结果均保留两位小数）。", "answer": ["0.08", "0.50", "0.14"], "explain": "遮光板通过光电门时间极短，平均速度可视为瞬时速度，v=d/Δt。[1]v1=0.0100/0.125=0.08m/s。[2]v2=0.0100/0.020=0.50m/s。[3]a=(v2−v1)/Δt=(0.50−0.08)/3.00=0.14m/s²。"}, {"id": "phy-12", "subject": "物理", "type": "exp", "points": 6, "knowledge": "打点计时器纸带、逐差法", "source": "高一上第一次月考", "stem": "某同学用如图所示装置研究小车运动的速度随时间变化的规律（纸带图略）。(1)电火花打点计时器使用的电源为____（选填\"直流220V\"或\"交流220V\"）电源。(2)实验打出的纸带上各点为计数点，相邻两计数点间还有四个计时点未标出，打点计时器所接电源的频率为50Hz，根据打出的纸带计算出打B点时小车的速度____m/s，小车运动的加速度____m/s²（结果均保留2位有效数字；关键数据：计数点间隔T=0.1s，详解取纸带数据用逐差法）。", "answer": ["交流220V", "0.81", "2.0"], "explain": "(1)电火花打点计时器使用交流220V电源。(2)打点周期0.02s，相邻计数点间还有四个计时点未标出，故计数点时间间隔 T=5×0.02s=0.1s。打B点速度用B点前后两段位移的平均：vB=(xAB+xBC)/(2T)=0.81m/s。加速度用逐差法：a=[(9.10−7.10)×10⁻²]/(0.1²)m/s²=2.0m/s²（数据引自详解）。"}, {"id": "phy-13", "subject": "物理", "type": "calc", "points": 8, "knowledge": "速度变化量的矢量性、加速度定义式", "source": "高一上第一次月考", "stem": "一质量为0.4kg的足球，以10m/s的速度迎面飞来，足球守门员将球以8m/s的速度反向踢出，守门员与球接触的时间为0.1s，求：(1)足球在与守门员接触的这段时间内的速度的变化量大小；(2)足球在与守门员接触的这段时间内的平均加速度大小。", "answer": ["18m/s", "180m/s²"], "explain": "取足球返回的方向为正方向（先写正方向！）。(1)速度的变化量 Δv=v2−v1=8−(−10)=18m/s（2分），=18m/s（1分）。答：足球速度的变化量大小为18m/s（1分）。注意迎面飞来取负，反向踢回两者相加不是相减。(2)加速度 a=Δv/t=18/0.1=180m/s²（2分），=180m/s²（1分）。答：足球加速度大小180m/s²（1分）。"}, {"id": "phy-14", "subject": "物理", "type": "calc", "points": 10, "knowledge": "v-t图像（斜率、面积）", "source": "高一上第一次月考", "stem": "一摩托车由静止开始在平直的公路上行驶，其运动过程的v-t图像如图所示（v-t图像：0~20s从0匀加速到30m/s；20~45s保持30m/s匀速；45~75s匀减速到0；后段据详解梯形面积反推）。求：(1)摩托车在0~20s这段时间的加速度大小；(2)摩托车在0~75s这段时间的平均速度大小。", "answer": ["1.5m/s²", "20m/s"], "explain": "(1)v-t图像斜率=加速度：a=Δv/Δt=30/20=1.5m/s²（2分），=1.5m/s²（1分）。答：0~20s加速度大小为1.5m/s²（1分）。(2)v-t图像面积=位移：x=½×(25+75)×30=1500m（2分，梯形：上底25s匀速段、下底75s总时间）。平均速度 v=x/t=1500/75=20m/s（2分）。"}, {"id": "phy-15", "subject": "物理", "type": "calc", "points": 16, "knowledge": "刹车陷阱（先算停止时间）", "source": "高一上第一次月考", "stem": "【注：原卷中初速度与加速度数值转换丢失，据详解反推复原为18m/s、6m/s²】以18m/s的速度行驶的汽车，紧急刹车后做匀减速直线运动，其加速度大小为6m/s²。求：(1)汽车在刹车1s末的速度；(2)汽车在刹车2s内的位移；(3)汽车在刹车4s内的位移。", "answer": ["12m/s", "24m", "27m"], "explain": "取汽车初速度方向为正方向。刹车问题第一步：先算停止时间 t₀=v₀/a=18/6=3s！(1)v=v₀+at=18−6×1=12m/s（2分），=12m/s（1分）。答：刹车1s末速度大小为12m/s，方向与初速度相同（1分）。(2)t=2s<t₀，用 x=v₀t−½at²=18×2−½×6×4=36−12=24m（3分），=24m（1分）。答：刹车2s内位移24m（1分）。(3)t=4s>t₀，汽车3s已停住，刹车4s内的位移=3s内的位移：x=18×3−½×6×9=54−27=27m（2分），=27m（1分）。答：位移大小27m（1分）。陷阱：直接代t=4s会得到24m的错误答案。"}, {"id": "math-01", "subject": "数学", "type": "single", "points": 5, "knowledge": "集合符号（∈/⊆）", "source": "高一上第一次月考", "stem": "下列关系中，正确的有（ ）", "options": {"A": "∅∈{0}", "B": "√2∈Q", "C": "Q⊆Z", "D": "−2∈Z"}, "answer": "D", "explain": "A错：∅是集合不是元素，应为∅⊆{0}；B错：√2是无理数，√2∉Q；C错：Q⊄Z，如1/2∈Q但1/2∉Z；D对：−2是整数。"}, {"id": "math-02", "subject": "数学", "type": "single", "points": 5, "knowledge": "Venn图与集合运算", "source": "高一上第一次月考", "stem": "已知全集U={0,1,2,3,4}，集合A={0,2,4}，集合B={2,3,4}，则如图所示的阴影部分表示的集合为（ ）。（图中阴影部分为矩形内除A、B两圆相交部分之外的所有区域，即A∩B在全集U中的补集）", "options": {"A": "{0,2,3,4}", "B": "{0,1,3}", "C": "{2,4}", "D": "{1}"}, "answer": "B", "explain": "A∩B={2,4}，阴影部分为∁U(A∩B)={0,1,3}。"}, {"id": "math-03", "subject": "数学", "type": "single", "points": 5, "knowledge": "全称量词命题的否定", "source": "高一上第一次月考", "stem": "已知命题p：∀x>0，x²−1≥0，则命题p的否定为（ ）", "options": {"A": "∀x≤0，x²−1<0", "B": "∀x>0，x²−1<0", "C": "∃x₀≤0，x₀²−1<0", "D": "∃x₀>0，x₀²−1<0"}, "answer": "D", "explain": "全称量词命题的否定：∀改∃，结论否定，量词的范围（x>0）保持不变。"}, {"id": "math-04", "subject": "数学", "type": "single", "points": 5, "knowledge": "分式不等式", "source": "高一上第一次月考", "stem": "不等式(x−1)/(x−2)≥0的解集为（ ）", "options": {"A": "{x|1≤x≤2}", "B": "{x|x≤1或x≥2}", "C": "{x|1≤x<2}", "D": "{x|x>2或x≤1}"}, "answer": "D", "explain": "等价于{(x−1)(x−2)≥0, x−2≠0}，解得x>2或x≤1。注意分母不为零，x=2要舍去。"}, {"id": "math-05", "subject": "数学", "type": "single", "points": 5, "knowledge": "子集个数", "source": "高一上第一次月考", "stem": "已知集合A={x|0≤x<4, x∈N*}，则集合A的子集的个数为（ ）", "options": {"A": "32", "B": "16", "C": "8", "D": "4"}, "answer": "C", "explain": "N*是正整数集，A={1,2,3}，共3个元素，子集个数为2³=8。"}, {"id": "math-06", "subject": "数学", "type": "single", "points": 5, "knowledge": "充分必要条件", "source": "高一上第一次月考", "stem": "已知p：0<x<2，q：−1<x<3，则q是p的（ ）", "options": {"A": "充分不必要条件", "B": "必要不充分条件", "C": "充要条件", "D": "既不充分也不必要条件"}, "answer": "B", "explain": "p⇒q（(0,2)⊂(−1,3)），但q⇏p，所以p是q的充分不必要条件，即q是p的必要不充分条件。"}, {"id": "math-07", "subject": "数学", "type": "single", "points": 5, "knowledge": "集合包含关系求参数", "source": "高一上第一次月考", "stem": "已知集合A={x|a−1≤x≤2a+1}，B={x|−3≤x≤3}，且A∩B=A，则实数a的取值范围是（ ）", "options": {"A": "[−2,1]", "B": "(−2,1)", "C": "(−∞,−2)", "D": "(−∞,1]"}, "answer": "D", "explain": "A∩B=A即A⊆B。若A=∅（a<−2）显然成立；若A≠∅，需a−1≥−3且2a+1≤3，得−2≤a≤1。合并得a≤1。易漏点：A为空集的情形。"}, {"id": "math-08", "subject": "数学", "type": "single", "points": 5, "knowledge": "基本不等式与恒成立", "source": "高一上第一次月考", "stem": "已知x>0，y>0，且x+y=5，若4/(x+1)+1/(y+2)≥2m+1恒成立，则实数m的取值范围是（ ）", "options": {"A": "m≤1/16", "B": "m≤2/5", "C": "m≤1/2", "D": "m≤1/4"}, "answer": "A", "explain": "x+1+y+2=8。4/(x+1)+1/(y+2)=(1/8)[4/(x+1)+1/(y+2)][(x+1)+(y+2)]≥(1/8)(5+2√4)=9/8，当且仅当x=13/3、y=2/3时取等。由2m+1≤9/8得m≤1/16。"}, {"id": "math-09", "subject": "数学", "type": "multi", "points": 6, "knowledge": "集合元素的互异性", "source": "高一上第一次月考", "stem": "设集合A={−1, x+2, x²−2x}，且3∈A，则x的值可以为（ ）", "options": {"A": "3", "B": "−3", "C": "−1", "D": "1"}, "answer": "AC", "explain": "若x+2=3得x=1，此时A={−1,3,−1}违背互异性，舍去；若x²−2x=3得x=3或x=−1，x=3时A={−1,5,3}成立，x=−1时A={−1,1,3}成立。故x=3或x=−1。（注：答案整理表备注误作x=−3，已据原卷核对更正。）"}, {"id": "math-10", "subject": "数学", "type": "multi", "points": 6, "knowledge": "不等式的性质", "source": "高一上第一次月考", "stem": "十六世纪中叶，英国数学家雷科德在《砺智石》一书中首先把“=”作为等号使用，后来英国数学家哈利奥特引入“<”和“>”符号，对不等式的发展影响深远。若a>b>1，c>0，则下列不等式一定成立的是（ ）。", "options": {"A": "a²−bc>b²−ac", "B": "c≥(b+ac)/(a+bc)", "C": "a/b>(a+c)/(b+c)", "D": "bc/a>ac/b"}, "answer": "AC", "explain": "A：a²−b²>bc−ac即(a−b)(a+b+c)>0，成立；B：等价于c²≥1，c>0不能保证，取c=0.5即为反例；C：等价于ac>bc即a>b，成立；D：等价于b²>a²，与a>b矛盾。"}, {"id": "math-11", "subject": "数学", "type": "multi", "points": 6, "knowledge": "基本不等式求最值", "source": "高一上第一次月考", "stem": "已知正数a，b满足2a+b=1，则（ ）", "options": {"A": "ab的最大值为1/8", "B": "1/a+1/b的最小值为4", "C": "√(2a)+√b的最小值为√2", "D": "a²+b²的最小值为1/5"}, "answer": "AD", "explain": "A：ab=(2a·b)/2≤((2a+b)/2)²/2=1/8；B：1/a+1/b的最小值为3+2√2≠4；C：令u=√(2a)、v=√b，则u²+v²=1，u+v>1无最小值（下确界为1）；D：由柯西不等式(4+1)(a²+b²)≥(2a+b)²=1，得a²+b²≥1/5。"}, {"id": "math-12", "subject": "数学", "type": "fill", "points": 5, "knowledge": "分段函数求值", "source": "高一上第一次月考", "stem": "已知f(x)={x²+1, x≥0; −x+1, x<0}，则f[f(−2)]=______。", "answer": "10", "explain": "先算内层：f(−2)=−(−2)+1=3；再算外层：f(3)=3²+1=10。关键：根据自变量的范围选对解析式。"}, {"id": "math-13", "subject": "数学", "type": "fill", "points": 5, "knowledge": "不等式范围（待定系数法）", "source": "高一上第一次月考", "stem": "已知实数x，y满足−4≤x−y≤−1，−1≤4x−y≤5，则t=9x−y的取值范围是______。", "answer": "[−1,20]", "explain": "待定系数：设9x−y=a(x−y)+b(4x−y)，解得a=−5/3，b=8/3。则t=−5/3(x−y)+8/3(4x−y)。由−4≤x−y≤−1得5/3≤−5/3(x−y)≤20/3，由−1≤4x−y≤5得−8/3≤8/3(4x−y)≤40/3，相加得−1≤t≤20。"}, {"id": "math-14", "subject": "数学", "type": "fill", "points": 5, "knowledge": "集合的表示（值域/定义域）", "source": "高一上第一次月考", "stem": "已知A={y|y=x²−2x−8, x∈R}，B={x|y=√(x+9)}，那么集合A与B的关系为______。", "answer": "B=A", "explain": "A是二次函数的值域：y=(x−1)²−9≥−9，即A={y|y≥−9}；B是函数y=√(x+9)的定义域：x+9≥0即B={x|x≥−9}。作为实数集两者都是[−9,+∞)，故B=A。易错点：代表元素y/x只是记号，不影响集合本身。"}, {"id": "math-15", "subject": "数学", "type": "solve", "points": 13, "knowledge": "集合的交并补运算", "source": "高一上第一次月考", "stem": "已知集合A={x|−1≤x<3}，B={x|1<3x−5<16}，（1）求A∪B；（2）求A∩B；（3）求∁R A∩B。", "answer": "（1）A∪B={x|−1≤x<7}；（2）A∩B={x|2<x<3}；（3）∁R A∩B={x|3≤x<7}", "explain": "关键步骤：先化简B：1<3x−5<16得2<x<7。（1）并集取两集合的合并：{x|−1≤x<7}；（2）交集取公共部分：{x|2<x<3}；（3）先求补集∁R A={x|x<−1或x≥3}，再与B取交得{x|3≤x<7}。注意端点开闭。"}, {"id": "math-16", "subject": "数学", "type": "solve", "points": 15, "knowledge": "函数定义域与集合包含", "source": "高一上第一次月考", "stem": "已知函数f(x)=√(3−x)+1/√(x+2)的定义域为集合A，B={x|x<a}。（1）求集合A；（2）若A⊆B，求a的取值范围。", "answer": "（1）A={x|−2<x≤3}；（2）a>3，即(3,+∞)", "explain": "（1）√(3−x)有意义需3−x≥0即x≤3；1/√(x+2)有意义需x+2>0即x>−2（分母不为零且根号内为正）。取交集得A={x|−2<x≤3}。（2）A⊆B={x|x<a}，A中最大元素x=3必须满足3<a，故a>3。"}, {"id": "math-17", "subject": "数学", "type": "solve", "points": 15, "knowledge": "一元二次不等式恒成立", "source": "高一上第一次月考", "stem": "已知函数f(x)=mx²−mx−1。（1）若m=1/2，求不等式f(x)<0的解集；（2）若关于x的不等式f(x)<0对一切x∈R恒成立，求实数m的取值范围。", "answer": "（1）{x|−1<x<2}；（2）{m|−4<m≤0}", "explain": "（1）m=1/2时化为x²−x−2<0，因式分解(x+1)(x−2)<0，解得−1<x<2。（2）m=0时−1<0恒成立；m≠0时需开口向下（m<0）且判别式Δ=m²+4m<0，解得−4<m<0。合并得−4<m≤0。易漏点：m=0的单独讨论。"}, {"id": "math-18", "subject": "数学", "type": "solve", "points": 17, "knowledge": "基本不等式应用与二次函数", "source": "高一上第一次月考", "stem": "如图，某人计划用篱笆围成一个一边靠墙（墙足够长）的矩形菜园。设菜园的长为x米，宽为y米。（1）若菜园面积为36平方米，则x，y为何值时，所用篱笆总长最小？（2）若使用的篱笆总长为30米，把菜园面积S表示为长x的函数：①当菜园面积不小于100平方米时，求x的取值范围；②求函数S(x)的值域，并指出面积最大时x，y的值。", "answer": "（1）x=6√2米，y=3√2米时篱笆总长最小；（2）S(x)=−x²/2+15x（0<x<30）；①10≤x≤20；②值域(0,225/2]，x=15、y=7.5时面积最大225/2", "explain": "（1）xy=36，篱笆总长为x+2y≥2√(2xy)=12√2，当且仅当x=2y即x=6√2、y=3√2时取等。（2）由x+2y=30得y=(30−x)/2，S(x)=x(30−x)/2=−x²/2+15x（0<x<30）。①S≥100化为x²−30x+200≤0，分解(x−10)(x−20)≤0，得10≤x≤20。②配方S(x)=−(x−15)²/2+225/2，开口向下，对称轴x=15在定义域内，故Smax=225/2，此时y=7.5；x→0或30时S→0，值域为(0,225/2]。"}, {"id": "math-19", "subject": "数学", "type": "solve", "points": 17, "knowledge": "存在量词命题与充分必要条件", "source": "高一上第一次月考", "stem": "已知∃x∈R，2mx²+mx+1/8<0，记实数m的取值范围为集合M。（1）求集合M；（2）已知集合N={x|x²+(1−a)x−a>0}，若“x∈N”是“x∈M”的充分不必要条件，求实数a的取值范围。", "answer": "（1）M={m|m<0或m>1}；（2）a≥1", "explain": "（1）m=0时1/8<0不成立；m<0时开口向下，必存在x使不等式成立；m>0时需Δ=m²−m>0，解得m>1。综上M={m|m<0或m>1}。（2）“x∈N是x∈M的充分不必要条件”即N⫋M。由x²+(1−a)x−a>0得(x−a)(x+1)>0。分类：a=−1时N={x|x≠−1}⊄M；a<−1时N={x|x<a或x>−1}⊄M；a>−1时N={x|x<−1或x>a}，要N⊂M需a≥1。综上a≥1。"}, {"id": "che-01", "subject": "化学", "type": "single", "points": 4, "knowledge": "化学实验安全", "source": "化学专题练习卷（2026-10-19）", "stem": "下列做法符合实验安全要求的是（ ）", "options": {"A": "剩余的钠块放回原试剂瓶", "B": "金属钠着火时使用泡沫灭火器灭火", "C": "浓硫酸与氢氧化钠固体放在同一实验橱内", "D": "新制氯水保存在棕色广口瓶中，置于避光阴凉处"}, "answer": "A", "explain": "A 对：钠是活泼金属，剩余钠块应放回原试剂瓶，不能随意丢弃；B 错：钠着火不能用泡沫灭火器（泡沫中的水和二氧化碳都会与钠反应），应用沙土扑灭；C 错：酸和碱应分开存放；D 错：氯水是液体，应保存在棕色细口瓶中，不是广口瓶。故选 A。"}, {"id": "che-02", "subject": "化学", "type": "single", "points": 4, "knowledge": "化学基本观念", "source": "化学专题练习卷（2026-10-19）", "stem": "构建化学基本观念是学好化学的基础。下列认识错误的是（ ）", "options": {"A": "元素观：物质是由元素组成的", "B": "分类观：H2O 和 Al2O3 均是氧化物", "C": "守恒观：1g 碳与 1g 氧气充分反应，生成 2g 二氧化碳", "D": "转化观：化学变化有新物质生成，其本质是原子的重新组合"}, "answer": "C", "explain": "A 对：物质都是由元素组成的；B 对：H2O 和 Al2O3 都是由两种元素组成、其中一种是氧元素的化合物，属于氧化物；C 错：1g 碳完全燃烧需要约 2.67g 氧气，1g 氧气只够生成约 1.375g 二氧化碳（氧气不足、碳有剩余），不可能生成 2g；D 对：化学变化的本质就是原子的重新组合。故选 C。"}, {"id": "che-03", "subject": "化学", "type": "single", "points": 4, "knowledge": "阿伏加德罗常数", "source": "化学专题练习卷（2026-10-19）", "stem": "NA 表示阿伏加德罗常数的值，下列叙述正确的是（ ）", "options": {"A": "22g CO2 所含有的分子数为 0.5NA", "B": "含 0.1mol BaCl2 的溶液中 Cl⁻ 数为 0.1NA", "C": "11.2L CO2 所含有的分子数为 0.5NA", "D": "7.8g Na2O2 中含有的离子总数为 0.4NA"}, "answer": "A", "explain": "A 对：22g CO2 为 0.5mol，分子数为 0.5NA；B 错：0.1mol BaCl2 电离出 0.2mol Cl⁻，应为 0.2NA；C 错：没说标准状况，11.2L 气体的物质的量不一定是 0.5mol；D 错：7.8g Na2O2 为 0.1mol，含 0.2mol Na⁺ 和 0.1mol O₂²⁻，离子总数为 0.3NA。故选 A。"}, {"id": "che-04", "subject": "化学", "type": "single", "points": 4, "knowledge": "钠及其化合物", "source": "化学专题练习卷（2026-10-19）", "stem": "下列关于钠及其化合物的说法正确的是（ ）", "options": {"A": "Na2O 久置于空气中，最终转化为 NaHCO3", "B": "Na2O 与 Na2O2 都能和水反应生成碱，它们都是碱性氧化物", "C": "Na2CO3 溶液能与酸溶液反应，但不能与碱溶液反应", "D": "Na 投入 MgCl2 溶液中生成白色沉淀和无色气体"}, "answer": "D", "explain": "A 错：Na2O 久置空气中先变成 NaOH，最终变成 Na2CO3，不是 NaHCO3；B 错：Na2O2 与水反应除生成碱外还有 O2 生成，不属于碱性氧化物；C 错：Na2CO3 能与澄清石灰水等碱反应生成 CaCO3 沉淀；D 对：Na 先与水反应生成 NaOH 和 H2，NaOH 再与 MgCl2 反应生成白色 Mg(OH)2 沉淀。故选 D。"}, {"id": "che-05", "subject": "化学", "type": "single", "points": 4, "knowledge": "实验现象与结论", "source": "化学专题练习卷（2026-10-19）", "stem": "下列有关实验现象与分析或结论都正确的是（ ）", "options": {"A": "光照新制氯水有气泡冒出——氯水中含有 Cl2，光照 Cl2 逸出", "B": "氯水中加入 NaOH 溶液，氯水黄绿色消失——氯水中有 HClO 分子存在", "C": "向镁粉中加入久置的氯水，有无色无味的气体产生——产生的气体是 H2", "D": "向氯水中加入盐酸酸化，再加入硝酸银溶液产生白色沉淀——氯水中有 Cl⁻ 存在"}, "answer": "C", "explain": "A：现象对但结论错——光照氯水冒气泡是因为 HClO 见光分解放出 O2，不是 Cl2 逸出；B：黄绿色消失只能证明有 Cl2（被 NaOH 吸收了），不能证明有 HClO；C 对：久置的氯水相当于稀盐酸，Mg 与盐酸反应放出无色无味的 H2；D：加盐酸酸化引入了 Cl⁻，再加 AgNO3 有沉淀不能证明原氯水中有 Cl⁻。故选 C。"}, {"id": "che-06", "subject": "化学", "type": "single", "points": 4, "knowledge": "阿伏加德罗定律", "source": "化学专题练习卷（2026-10-19）", "stem": "温度、压强相同时，等体积的两容器内，一个盛 CO2，另一个盛 H2，则两容器内所盛气体相比，下列结论一定不正确的是（ ）", "options": {"A": "分子个数比为 1∶1", "B": "密度比为 22∶1", "C": "原子个数比为 1∶1", "D": "质量比为 22∶1"}, "answer": "C", "explain": "同温同压同体积 → 两容器气体分子数相等。A 对：分子数比 1∶1；B 对：密度比 = 摩尔质量比 = 44∶2 = 22∶1；C 错：CO2 每个分子 3 个原子、H2 每个分子 2 个原子，原子数比应为 3∶2，所以\"1∶1\"一定不正确；D 对：质量比 = 44∶2 = 22∶1。故选 C。"}, {"id": "che-07", "subject": "化学", "type": "single", "points": 4, "knowledge": "氯气和氯水", "source": "化学专题练习卷（2026-10-19）", "stem": "下列关于氯气和氯水的说法中正确的是（ ）", "options": {"A": "红热的铁丝在 Cl2 中剧烈燃烧生成 FeCl2", "B": "氯气是一种无色、密度比空气大的有毒气体", "C": "新制氯水能杀菌消毒是因为 Cl2 有毒，能毒杀细菌", "D": "氯水放置数天后酸性增强"}, "answer": "D", "explain": "A 错：红热铁丝在 Cl2 中燃烧生成 FeCl3（氯气强氧化性，铁被氧化到 +3 价）；B 错：氯气是黄绿色气体，不是无色；C 错：新制氯水杀菌是因为 HClO 有强氧化性，不是 Cl2 的毒性；D 对：HClO 见光分解生成 HCl，久置的氯水酸性增强。故选 D。"}, {"id": "che-08", "subject": "化学", "type": "single", "points": 4, "knowledge": "物质的量计算", "source": "化学专题练习卷（2026-10-19）", "stem": "下列物质所含原子数由大到小排列的是（ ）①0.5mol NH3  ②4g H2  ③标准状况下，0.3mol CO2  ④0.2mol H3PO4", "options": {"A": "①④③②", "B": "④③②①", "C": "②③④①", "D": "②①④③"}, "answer": "D", "explain": "① 0.5mol NH3 含 0.5×4 = 2mol 原子；② 4g H2 为 2mol，含 2×2 = 4mol 原子；③ 0.3mol CO2 含 0.3×3 = 0.9mol 原子；④ 0.2mol H3PO4 含 0.2×8 = 1.6mol 原子。由大到小：②①④③。故选 D。"}, {"id": "che-09", "subject": "化学", "type": "single", "points": 4, "knowledge": "气体摩尔体积", "source": "化学专题练习卷（2026-10-19）", "stem": "下列说法正确的是（ ）", "options": {"A": "同温、同压下，相同质量的气体都占有相同的体积", "B": "在标准状况下，1mol 任何物质的体积均为 22.4L", "C": "1mol 某气体的体积约为 22.4L，该气体所处的状况一定是标准状况", "D": "同温、同压下，相同体积的气体都含有相同数目的分子"}, "answer": "D", "explain": "A 错：应为\"相同物质的量\"的气体，不是相同质量；B 错：应为\"1mol 任何气体\"，不是任何物质；C 错：1mol 气体体积约为 22.4L 时，温度和压强可以有多种组合，不一定是标准状况；D 对：阿伏加德罗定律——同温同压下，相同体积的气体含有相同数目的分子。故选 D。"}, {"id": "che-10", "subject": "化学", "type": "multi", "points": 6, "knowledge": "化学实验装置", "source": "化学专题练习卷（2026-10-19）", "stem": "用下列实验装置进行相应实验，装置正确且能达到相应实验目的的是（ ）甲：气体依次通过饱和 NaCl 溶液、浓硫酸（长进短出）；乙：坩埚中放钠块加热；丙：稀释浓硫酸；丁：加热 Na2CO3 固体", "options": {"A": "用图甲除去 Cl2 中的 HCl 并干燥", "B": "用图乙装置进行钠的燃烧实验", "C": "用图丙装置稀释浓硫酸", "D": "用图丁制备二氧化碳"}, "answer": "AB", "explain": "甲：除 Cl2 中 HCl 先经饱和食盐水（Cl2 溶解度小、HCl 极易溶），再经浓硫酸干燥，长进短出正确，能达到目的；乙：坩埚加热钠块进行钠的燃烧实验，装置正确；丙：稀释浓硫酸若在烧杯中将浓硫酸沿玻璃棒缓慢倒入水中并搅拌则正确，请对照原卷图确认容器；丁错：Na2CO3 受热不分解，不能用加热法制备 CO2。故选 AB（C 以原卷图为准）。"}, {"id": "che-11", "subject": "化学", "type": "fill", "points": 12, "knowledge": "化学方程式书写", "source": "化学专题练习卷（2026-10-19）", "stem": "写出下列过程发生的化学方程式：（1）钠块在氧气中加热，生成淡黄色固体：＿＿；（2）氢气在氯气中燃烧：＿＿；（3）细铁丝在氯气中燃烧：＿＿；（4）次氯酸见光分解：＿＿；（5）工业生产漂白粉：＿＿；（6）往 CuSO4 溶液中滴加 NaOH 溶液：＿＿。", "options": null, "answer": ["2Na + O2 = 【条件：△】 Na2O2", "H2 + Cl2 = 【条件：点燃】 2HCl", "2Fe + 3Cl2 = 【条件：点燃】 2FeCl3", "2HClO = 【条件：光照】 2HCl + O2↑", "2Cl2 + 2Ca(OH)2 = CaCl2 + Ca(ClO)2 + 2H2O", "CuSO4 + 2NaOH = Cu(OH)2↓ + Na2SO4"], "explain": "（1）钠在氧气中加热生成淡黄色固体 Na2O2，注意是加热不是点燃；（2）H2 在 Cl2 中燃烧生成 HCl；（3）Fe 在 Cl2 中燃烧生成 FeCl3——氯气氧化性强，铁直接被氧化到 +3 价，不生成 FeCl2；（4）HClO 见光分解是氯水久置变质、酸性增强的原因；（5）Cl2 通入石灰乳制漂白粉，有效成分是 Ca(ClO)2；（6）生成蓝色 Cu(OH)2 沉淀。条件（点燃/加热/光照）和 ↑↓ 别漏。"}, {"id": "che-12a", "subject": "化学", "type": "fill", "points": 8, "knowledge": "物质的量计算", "source": "化学专题练习卷（2026-10-19）", "stem": "（1）1.204×10²³ 个 NO 的物质的量为＿＿mol，其 N 原子的质量为＿＿g；（2）质量相同的 SO2 和 SO3，物质的量之比是＿＿，所含氧原子个数比是＿＿。", "options": null, "answer": ["0.2", "2.8", "5:4", "5:6"], "explain": "（1）1.204×10²³ ÷ 6.02×10²³ = 0.2mol；N 原子 0.2mol，质量 0.2×14 = 2.8g。（2）设质量同为 m：n(SO2) = m/64，n(SO3) = m/80，物质的量之比 = 80∶64 = 5∶4；氧原子个数比 = (5×2)∶(4×3) = 10∶12 = 5∶6。"}, {"id": "che-12b", "subject": "化学", "type": "fill", "points": 6, "knowledge": "物质的量计算", "source": "化学专题练习卷（2026-10-19）", "stem": "（3）标准状况下，3.4g NH3 与＿＿L H2S 气体含有相同数目的氢原子；（4）标准状况下，1.28g 气态氧化物 RO2 的体积为 448mL，则 R 的相对原子质量为＿＿；（5）标准状况下，V L CH4 气体中含有 a 个氢原子，则阿伏加德罗常数的值可表示为＿＿。", "options": null, "answer": ["6.72", "32", "5.6a/V||22.4a/4V"], "explain": "（3）3.4g NH3 为 0.2mol，含 H 原子 0.6mol；需要 H2S 0.3mol，标况体积 0.3×22.4 = 6.72L。（4）448mL = 0.02mol，M = 1.28÷0.02 = 64g/mol，R = 64−32 = 32。（5）n(CH4) = V/22.4，H 原子数 = (4V/22.4)×NA = a，得 NA = 22.4a/4V = 5.6a/V。"}, {"id": "che-13a", "subject": "化学", "type": "fill", "points": 10, "knowledge": "钠及其化合物", "source": "化学专题练习卷（2026-10-19）", "stem": "（1）Na 与水反应的化学方程式为＿＿；（2）Na2O2 与二氧化碳反应的化学方程式为＿＿；（3）Na2CO3 粉末与过量盐酸反应的化学方程式为＿＿；（4）NaH 中氢元素的化合价为＿＿价，NaH 与水反应的化学方程式为＿＿。", "options": null, "answer": ["2Na + 2H2O = 2NaOH + H2↑", "2Na2O2 + 2CO2 = 2Na2CO3 + O2", "Na2CO3 + 2HCl = 2NaCl + H2O + CO2↑", "-1", "NaH + H2O = NaOH + H2↑"], "explain": "（1）钠与水剧烈反应放出 H2；（2）Na2O2 与 CO2 反应放出 O2，可作供氧剂；（3）盐酸过量，碳酸钠中的碳全部以 CO2 放出；（4）NaH 中 H 为 −1 价（活泼金属的氢化物中 H 显 −1 价），与水反应：NaH + H2O = NaOH + H2↑，生成的 H2 可燃。"}, {"id": "che-13b", "subject": "化学", "type": "single", "points": 2, "knowledge": "钠及其化合物", "source": "化学专题练习卷（2026-10-19）", "stem": "将一小块钠投入 CuSO4 溶液中，观察到的现象是（ ）①钠浮于液面上 ②熔化成小球 ③发出嘶嘶的响声，放出气体 ④有蓝色沉淀产生 ⑤析出红色的铜", "options": {"A": "①②③", "B": "①②③④", "C": "②③④⑤", "D": "①③④⑤"}, "answer": "B", "explain": "Na 先与水反应：浮于液面（密度比水小）、熔成小球（熔点低、反应放热）、嘶嘶响并放出 H2；生成的 NaOH 再与 CuSO4 反应生成蓝色 Cu(OH)2 沉淀。钠不能从 CuSO4 溶液中置换出铜（它先跟水反应了），⑤错。故选 B。"}, {"id": "che-14a", "subject": "化学", "type": "fill", "points": 10, "knowledge": "氯气的实验室制备", "source": "化学专题练习卷（2026-10-19）", "stem": "实验室用 MnO2 与浓盐酸制备干燥纯净的氯气（B 瓶除杂、C 瓶干燥、E 烧杯 NaOH 尾气吸收）。（1）装置 A 中反应的化学方程式为＿＿；（2）B 中所盛试剂为＿＿（填序号：A.氢氧化钠溶液 B.饱和食盐水 C.浓硫酸 D.澄清石灰水），C 中所盛试剂为＿＿；（3）尾气处理反应的化学方程式为＿＿；（4）新制氯水呈黄绿色说明其中含有＿＿（填化学式）；将紫色石蕊溶液滴入氯水，观察到的现象是＿＿，说明其中含有＿＿。", "options": null, "answer": ["MnO2 + 4HCl(浓) = 【条件：△】 MnCl2 + Cl2↑ + 2H2O", "B", "C", "Cl2 + 2NaOH = NaCl + NaClO + H2O", "Cl2", "先变红后褪色||变红后褪色", "H+、HClO||H+和HClO||氢离子、次氯酸||氢离子和次氯酸"], "explain": "（1）MnO2 与浓盐酸加热制 Cl2，注意盐酸要标\"浓\"、要加热；（2）B 用饱和食盐水除 HCl（Cl2 在其中溶解度小），C 用浓硫酸干燥——先除杂后干燥；（3）Cl2 尾气用 NaOH 溶液吸收；（4）黄绿色是 Cl2 的颜色；紫色石蕊先变红（氯水显酸性，有 H⁺）后褪色（HClO 的漂白性），说明同时含有 H⁺ 和 HClO。"}, {"id": "che-14b", "subject": "化学", "type": "fill", "points": 12, "knowledge": "漂白粉变质探究", "source": "化学专题练习卷（2026-10-19）", "stem": "有一瓶密封不严的漂白粉样品，肯定含有 CaCl2。假设①：该漂白粉未变质，含有＿＿；假设②：该漂白粉全部变质，含有＿＿。实验 1：取样加稀盐酸，有气泡产生 → 则假设＿＿不成立；实验 2：向实验 1 反应后的试管中滴加品红溶液，振荡。若品红褪色，结合实验 1 则假设＿＿成立；若品红不褪色，则假设＿＿成立。（假设③：部分变质，既含 Ca(ClO)2 又含 CaCO3）", "options": null, "answer": ["Ca(ClO)2", "CaCO3", "①||1", "③||3", "②||2"], "explain": "漂白粉变质原理：Ca(ClO)2 + CO2 + H2O = CaCO3↓ + 2HClO。实验 1 加稀盐酸有气泡 → 有 CaCO3 → \"未变质\"的假设①不成立；实验 2 品红褪色 → 还有 Ca(ClO)2（能使品红褪色）→ 部分变质，假设③成立；品红不褪色 → Ca(ClO)2 已耗尽 → 全部变质，假设②成立。"}], "dictation": [{"answer": "2Na + 2H2O = 2NaOH + H2↑", "explain": "思路：钠是活泼金属，与水剧烈反应生成氢氧化钠和氢气。四步checklist：化学式写对→配平（Na 2个、H2O 2个）→无特殊条件→H2是气体加↑。易错：漏写H2、漏↑。她13-(1)漏写H2且未配平被扣光。", "id": "chem-01", "prompt": "钠与水反应", "set": "方程式默写", "subject": "化学", "tags": ["钠", "配平", "气体符号"]}, {"answer": "4Na + O2 = 2Na2O", "explain": "思路：常温下钠被氧化生成氧化钠。关键：条件决定产物——常温→Na2O，点燃→Na2O2。她11-(1)自创了不明条件“R△”，产物也写错，0分。", "id": "chem-02", "prompt": "钠在常温下与氧气反应", "set": "方程式默写", "subject": "化学", "tags": ["钠", "条件决定产物"]}, {"answer": "2Na + O2 = 【条件：点燃】 Na2O2", "explain": "思路：点燃时生成淡黄色的过氧化钠Na2O2。对比记忆：常温→Na2O，点燃→Na2O2。易错：把Na2O2写成NaO2。", "id": "chem-03", "prompt": "钠在氧气中燃烧", "set": "方程式默写", "subject": "化学", "tags": ["钠", "条件", "过氧化钠"]}, {"answer": "2Na2O2 + 2H2O = 4NaOH + O2↑", "explain": "思路：Na2O2中O为-1价，歧化为O2（0价）和OH-中的O（-2价）。配平：先定Na2O2为2，再配H2O为2。易错：漏O2↑。", "id": "chem-04", "prompt": "过氧化钠与水反应", "set": "方程式默写", "subject": "化学", "tags": ["过氧化钠", "配平"]}, {"answer": "2Na2O2 + 2CO2 = 2Na2CO3 + O2", "explain": "思路：呼吸面具/潜水艇供氧剂原理，CO2→O2。她13-(2)写成Na2O2+CO2=2Na2CO3+O2未配平被扣1分——配平是按规则必扣分的，亲手配10遍。", "id": "chem-05", "prompt": "过氧化钠与二氧化碳反应（呼吸面具供氧原理）", "set": "方程式默写", "subject": "化学", "tags": ["过氧化钠", "配平", "13题错题"]}, {"answer": "2NaHCO3 = 【条件：加热】 Na2CO3 + CO2↑ + H2O", "explain": "思路：NaHCO3不稳定，受热分解。配平：2个NaHCO3。易错：漏条件加热、漏↑。", "id": "chem-06", "prompt": "碳酸氢钠受热分解", "set": "方程式默写", "subject": "化学", "tags": ["碳酸氢钠", "条件"]}, {"answer": "Na2CO3 + 2HCl = 2NaCl + CO2↑ + H2O", "explain": "思路：强酸制弱酸，碳酸盐+酸→CO2↑。她13-(2)这个写对拿了满分，会写的要保持。注意：盐酸少量时先生成NaHCO3，足量才放出CO2。", "id": "chem-07", "prompt": "碳酸钠与足量盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["碳酸钠", "气体符号"]}, {"answer": "2Al + 6HCl = 2AlCl3 + 3H2↑", "explain": "思路：Al是活泼金属，与非氧化性酸生成AlCl3和H2。配平：Al 2个、HCl 6个、H2 3个。", "id": "chem-08", "prompt": "铝与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "配平"]}, {"answer": "2Al + 2NaOH + 2H2O = 2NaAlO2 + 3H2↑", "explain": "思路：Al既能与酸反应又能与强碱反应（两性金属的特性）。产物是偏铝酸钠NaAlO2和H2。配平：Al 2、NaOH 2、H2O 2。易错：漏写H2O、漏↑。", "id": "chem-09", "prompt": "铝与氢氧化钠溶液反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "两性", "配平"]}, {"answer": "Al2O3 + 6HCl = 2AlCl3 + 3H2O", "explain": "思路：Al2O3是两性氧化物，与酸生成盐和水。配平：HCl 6个。", "id": "chem-10", "prompt": "氧化铝与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "两性氧化物"]}, {"answer": "Al(OH)3 + NaOH = NaAlO2 + 2H2O", "explain": "思路：Al(OH)3是两性氢氧化物，溶于强碱生成偏铝酸钠。注意H2O是2个，配平不要漏。", "id": "chem-11", "prompt": "氢氧化铝与氢氧化钠溶液反应", "set": "方程式默写", "subject": "化学", "tags": ["铝", "两性"]}, {"answer": "2Fe + 3Cl2 = 【条件：点燃】 2FeCl3", "explain": "思路：Cl2是强氧化剂，把Fe氧化到+3价，生成FeCl3（棕褐色烟）。对比：Fe与盐酸只生成FeCl2+H2↑——她11-(3)把两者混了，还写出Fe3Cl2这种不存在的化学式。记住：氧化剂强弱决定价态，Cl2强→+3价，HCl弱→+2价。", "id": "chem-12", "prompt": "铁在氯气中燃烧", "set": "方程式默写", "subject": "化学", "tags": ["铁", "氯气", "11题错题"]}, {"answer": "Fe + 2HCl = FeCl2 + H2↑", "explain": "思路：Fe与非氧化性酸反应，Fe只到+2价，生成FeCl2和H2↑。对比记忆：Fe+Cl2→FeCl3，Fe+HCl→FeCl2。", "id": "chem-13", "prompt": "铁与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铁", "对比"]}, {"answer": "2FeCl2 + Cl2 = 2FeCl3", "explain": "思路：Cl2把Fe2+氧化为Fe3+，溶液由浅绿色变为棕黄色。这是Fe2+的检验思路之一。", "id": "chem-14", "prompt": "氯化亚铁溶液中通入氯气", "set": "方程式默写", "subject": "化学", "tags": ["铁", "氧化还原"]}, {"answer": "4Fe(OH)2 + O2 + 2H2O = 4Fe(OH)3", "explain": "思路：白色Fe(OH)2→灰绿色→红褐色Fe(OH)3。配平：Fe(OH)2 4个、O2 1个、H2O 2个。现象记忆：颜色渐变是考点。", "id": "chem-15", "prompt": "氢氧化亚铁在空气中被氧化", "set": "方程式默写", "subject": "化学", "tags": ["铁", "配平", "现象"]}, {"answer": "Fe2O3 + 6HCl = 2FeCl3 + 3H2O", "explain": "思路：Fe2O3（铁红）是碱性氧化物，与酸生成盐和水。配平：HCl 6个。", "id": "chem-16", "prompt": "氧化铁与盐酸反应", "set": "方程式默写", "subject": "化学", "tags": ["铁"]}, {"answer": "H2 + Cl2 = 【条件：点燃】 2HCl", "explain": "思路：苍白色火焰，生成HCl。她11-(2)涂改混乱得0分——这个式子必须一笔写对：H2+Cl2点燃→2HCl。", "id": "chem-17", "prompt": "氢气在氯气中燃烧", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "11题错题"]}, {"answer": "Cl2 + H2O ⇌ HCl + HClO", "explain": "思路：可逆反应（⇌）。氯水中含Cl2、HClO、H+、Cl-等。HClO是弱酸，有漂白性。易错：写成等号、漏写HClO。", "id": "chem-18", "prompt": "氯气与水反应（氯水的成分）", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "可逆", "漂白"]}, {"answer": "2HClO = 【条件：光照】 2HCl + O2↑", "explain": "思路：HClO不稳定，见光分解为HCl和O2——这就是氯水要避光保存、新制氯水久置变成稀盐酸的原因。她11-(4)写成HClO=H2O+Cl2↑，产物全错。", "id": "chem-19", "prompt": "次氯酸见光分解", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "11题错题", "光照"]}, {"answer": "Cl2 + 2NaOH = NaCl + NaClO + H2O", "explain": "思路：产物是NaClO（次氯酸钠）不是HClO——她14-(3)写成HClO被扣光。记忆：碱吸收氯气，Cl2歧化为Cl-和ClO-。配平：NaOH 2个。", "id": "chem-20", "prompt": "氯气与氢氧化钠溶液反应（尾气吸收）", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "14题错题", "尾气吸收"]}, {"answer": "MnO2 + 4HCl(浓） = 【条件：加热】 MnCl2 + Cl2↑ + 2H2O", "explain": "思路：二氧化锰+浓盐酸加热。四要素缺一不可：MnO2、浓HCl、加热、配平（HCl 4个、H2O 2个）。她14-(1)未配平、缺“浓”和“加热”被扣2分——按规则配平/条件/气体符号有问题各扣1分。", "id": "chem-21", "prompt": "实验室制取氯气", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "实验室制法", "14题错题"]}, {"answer": "2Ca(OH)2 + 2Cl2 = CaCl2 + Ca(ClO)2 + 2H2O", "explain": "思路：氯气通入石灰乳。漂白粉是混合物（CaCl2·Ca(ClO)2），有效成分是Ca(ClO)2——她14-(5)把两者混淆。配平：Ca(OH)2 2个、Cl2 2个、H2O 2个。她11-(5)配平也错了，重默10遍。", "id": "chem-22", "prompt": "工业制漂白粉", "set": "方程式默写", "subject": "化学", "tags": ["氯气", "漂白粉", "14题错题"]}, {"answer": "Cu + 2H2SO4(浓） = 【条件：加热】 CuSO4 + SO2↑ + 2H2O", "explain": "思路：浓硫酸的强氧化性（+6价S→+4价SO2），Cu被氧化为CuSO4。必须加热、必须浓硫酸。配平：H2SO4 2个。", "id": "chem-23", "prompt": "铜与浓硫酸反应（加热）", "set": "方程式默写", "subject": "化学", "tags": ["浓硫酸", "氧化性"]}, {"answer": "C + 2H2SO4(浓） = 【条件：加热】 CO2↑ + 2SO2↑ + 2H2O", "explain": "思路：C被浓硫酸氧化为CO2，浓硫酸被还原为SO2。两个气体产物都要加↑。配平：H2SO4 2个、SO2 2个。", "id": "chem-24", "prompt": "碳与浓硫酸反应（加热）", "set": "方程式默写", "subject": "化学", "tags": ["浓硫酸", "配平"]}, {"answer": "SO2 + H2O ⇌ H2SO3", "explain": "思路：可逆反应，生成亚硫酸H2SO3（二元弱酸）。SO2是酸性氧化物。", "id": "chem-25", "prompt": "二氧化硫与水反应", "set": "方程式默写", "subject": "化学", "tags": ["硫", "可逆"]}, {"answer": "4NH3 + 5O2 = 【条件：催化剂、加热】 4NO + 6H2O", "explain": "思路：工业制硝酸第一步。NH3中N（-3价）→NO中N（+2价）。配平：NH3 4个、O2 5个、NO 4个、H2O 6个。条件催化剂（铂铑合金）+加热缺一不可。", "id": "chem-26", "prompt": "氨的催化氧化", "set": "方程式默写", "subject": "化学", "tags": ["氨", "催化氧化", "配平"]}, {"answer": "2NO + O2 = 2NO2", "explain": "思路：无色NO遇空气变红棕色NO2，是NO的特征检验。配平：NO 2个、NO2 2个。", "id": "chem-27", "prompt": "一氧化氮与氧气反应", "set": "方程式默写", "subject": "化学", "tags": ["氮", "现象"]}, {"answer": "3NO2 + H2O = 2HNO3 + NO", "explain": "思路：NO2与水歧化，生成硝酸和NO。配平：NO2 3个、HNO3 2个。", "id": "chem-28", "prompt": "二氧化氮与水反应", "set": "方程式默写", "subject": "化学", "tags": ["氮", "配平"]}, {"answer": "SiO2 + 2NaOH = Na2SiO3 + H2O", "explain": "思路：SiO2是酸性氧化物，与碱生成硅酸钠和水。这就是“盛碱液的玻璃瓶不能用玻璃塞”的原因（会生成Na2SiO3把瓶塞粘住）。", "id": "chem-29", "prompt": "二氧化硅与氢氧化钠溶液反应", "set": "方程式默写", "subject": "化学", "tags": ["硅", "酸性氧化物"]}, {"answer": "SiO2 + 4HF = SiF4↑ + 2H2O", "explain": "思路：SiO2的特性——只与HF反应（其他酸都不反应），用于雕刻玻璃。配平：HF 4个，SiF4是气体加↑。", "id": "chem-30", "prompt": "二氧化硅与氢氟酸反应", "set": "方程式默写", "subject": "化学", "tags": ["硅", "特性"]}, {"answer": "奴隶社会代替原始社会是历史的进步。", "explain": "21题1分得分点。观点句先写，这是送分的第一句，写完再跟论据。她这句写出来了，要保持。", "id": "pol-01", "prompt": "21题得分点①：奴隶社会代替原始社会是什么性质？", "set": "标志性表述", "subject": "政治", "tags": ["社会形态更替", "21题"]}, {"answer": "生产关系一定要适应生产力状况的规律是人类社会发展的一般规律。一种社会形态代替另一种社会形态，究竟是历史的进步还是倒退，判断的主要标准，是看生产关系是否适应生产力的发展要求，是否符合人类社会发展的总趋势。", "explain": "21题3分得分点。她只写了零散表述丢了分。关键词：生产关系适应生产力、是否符合人类社会发展的总趋势。", "id": "pol-02", "prompt": "21题得分点②：判断社会形态更替是进步还是倒退的主要标准", "set": "标志性表述", "subject": "政治", "tags": ["历史规律", "21题"]}, {"answer": "奴隶社会代替原始社会后，金属工具的广泛使用、城市的出现、脑力劳动和体力劳动的分工等，这是历史的进步。", "explain": "21题3分得分点。她一个论据没写，观点空转。三个关键词必须一字不差：金属工具、城市、脑力劳动和体力劳动的分工。", "id": "pol-03", "prompt": "21题得分点④：奴隶社会进步性的具体表现（三个）", "set": "标志性表述", "subject": "政治", "tags": ["史实论据", "21题"]}, {"answer": "中华人民共和国的成立，彻底结束了旧中国半殖民地半封建社会的历史，彻底结束了极少数剥削者统治广大劳动人民的历史，彻底结束了旧中国一盘散沙的局面，彻底废除了列强强加给中国的不平等条约和帝国主义在中国的一切特权，实现了中国从几千年封建专制政治向人民民主的伟大飞跃。", "explain": "22题3分得分点。她这题只拿2/8分，关键词全缺。四个“彻底结束”＋“从封建专制政治向人民民主的伟大飞跃”，一字不差背下来。", "id": "pol-04", "prompt": "22题得分点①：中华人民共和国成立的意义（“四个彻底结束”＋伟大飞跃）", "set": "标志性表述", "subject": "政治", "tags": ["新中国成立", "22题"]}, {"answer": "中华人民共和国的成立，为实现由新民主主义向社会主义的过渡创造了前提条件，从根本上改变了中国社会的发展方向，为实现国家富强、民族复兴展示了美好前景和现实道路。", "explain": "22题3分得分点。关键词：过渡创造了前提条件、根本上改变发展方向、美好前景和现实道路。", "id": "pol-05", "prompt": "22题得分点②：新中国成立为过渡创造的前提条件", "set": "标志性表述", "subject": "政治", "tags": ["新中国成立", "22题"]}, {"answer": "新中国的诞生，冲破了帝国主义的东方战线，极大地改变了世界政治力量的对比，鼓舞和推动了世界被压迫民族和被压迫人民争取解放的斗争。", "explain": "22题2分得分点。关键词：东方战线、世界政治力量对比、被压迫民族。", "id": "pol-06", "prompt": "22题得分点③：新中国成立的世界意义", "set": "标志性表述", "subject": "政治", "tags": ["新中国成立", "22题"]}, {"answer": "改革开放是党和人民大踏步赶上时代的重要法宝，是坚持和发展中国特色社会主义的必由之路，是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。", "explain": "23题4分得分点。她缺了“必由之路/关键一招”丢5分。关键词：重要法宝、必由之路、关键一招（出现两次）。", "id": "pol-07", "prompt": "23题得分点②：改革开放的地位（“必由之路”“关键一招”）", "set": "标志性表述", "subject": "政治", "tags": ["改革开放", "23题"]}, {"answer": "①在半殖民地半封建社会的近代中国，资本主义道路走不通。②中国共产党的诞生使中国人民有了前进的主心骨，党领导各族人民夺取了新民主主义革命的伟大胜利。③中华人民共和国的成立，从根本上改变了中国社会的发展方向。④社会主义改造的完成，在中国建立起社会主义制度。总之：只有社会主义才能救中国。", "explain": "24题12分她只拿3分，缺②③两大得分块。先背四段骨架再填肉：旧路不通→党领导革命胜利→新中国转方向→社会主义改造建制度→总结句。", "id": "pol-08", "prompt": "24题骨架：“只有社会主义能救中国”四段论证＋总结句", "set": "标志性表述", "subject": "政治", "tags": ["社会主义", "24题"]}, {"answer": "不是。反射是太阳辐射被云层、地面直接弹回太空，属于削弱作用；大气逆辐射是大气吸收地面长波辐射后、再以长波辐射形式返还给地面的部分，属于保温作用。", "explain": "27(2)就栽在这：把“大气逆辐射”写成“反射”，6分只拿1分。记忆钩：逆辐射是“大气回赠给地面的热量”，方向是朝下的。", "id": "con-01", "prompt": "大气逆辐射和反射是一回事吗？", "set": "概念辨析", "subject": "地理", "tags": ["大气", "27题错题"]}, {"answer": "削弱作用：大气对太阳辐射的吸收、反射、散射，使到达地面的太阳辐射减少（白天降温）。保温作用：大气吸收地面辐射，并以大气逆辐射形式返还热量给地面（夜间保温）。", "explain": "28(2)把两者混为一谈，得出“太阳辐射强度与气温成反比”的错误结论，6分挂零。记住：削弱管白天，保温管夜晚。", "id": "con-02", "prompt": "大气的削弱作用和保温作用各指什么？", "set": "概念辨析", "subject": "地理", "tags": ["大气", "28题错题"]}, {"answer": "太阳辐射→（被大气削弱：吸收/反射/散射）→地面吸收→地面增温→地面辐射（长波）→大气吸收→大气增温→大气逆辐射→返还地面（保温）。根本热源是太阳辐射，直接热源是地面。", "explain": "27、28题的共同病根，约13分。每天默画一遍这张图，标出削弱三种形式和保温链条，直到闭眼能复述。", "id": "con-03", "prompt": "复述“大气的受热过程”完整链条", "set": "概念辨析", "subject": "地理", "tags": ["大气", "链条"]}, {"answer": "古登堡面约2900km，是地幔与地核的分界面；莫霍面平均约17km深，是地壳与地幔的分界面；软流层位于上地幔顶部，是岩浆的发源地。", "explain": "26(1)她把古登堡面写成4000，纯记忆分丢了。2900这个数字贴书桌——这是卷面直接考的。", "id": "con-04", "prompt": "古登堡面、莫霍面的深度和软流层的位置", "set": "概念辨析", "subject": "地理", "tags": ["地球圈层", "数字"]}, {"answer": "由里到外：光球层→色球层→日冕层。对应太阳活动：黑子在光球层，耀斑（日珥）在色球层。口诀：黑子在光球，耀斑在色球。", "explain": "26(3)她这题拿了满分，说明记得住——保持住，别还回去。", "id": "con-05", "prompt": "太阳大气层由里到外是哪三层？对应的太阳活动是什么？", "set": "概念辨析", "subject": "地理", "tags": ["太阳", "记忆"]}, {"answer": "对流层气温随高度升高而降低。近地面大气的主要直接热源是地面（地面辐射），不是太阳直接加热。", "explain": "26(4)她把“降低”写成“升高”，规律记反丢分。记忆：越高越冷，因为热源在脚下（地面）。", "id": "con-06", "prompt": "对流层气温随高度如何变化？近地面大气的直接热源是什么？", "set": "概念辨析", "subject": "地理", "tags": ["对流层", "26题错题"]}, {"answer": "古生代、中生代、新生代是“代”；第四纪是新生代里的一个“纪”，层级比代低。", "explain": "26(2)她把“新生代”等同于“第四纪”，是层级混淆丢2分。记住：代和纪是上下级，第四纪属于新生代。", "id": "con-07", "prompt": "地质年代：古生代、中生代、新生代和第四纪是什么关系？", "set": "概念辨析", "subject": "地理", "tags": ["地质年代", "26题错题"]}, {"answer": "辐射强：①纬度低太阳高度大；②晴天多，削弱作用弱；③海拔高空气稀薄，削弱作用弱。气温低：④空气稀薄，大气吸收地面辐射少，保温作用弱。", "explain": "28(2)她只答出②③，还推出“成反比”的错误结论，6分挂零。记住：辐射强弱看“削弱”，气温高低看“保温”，两套逻辑别串。", "id": "con-08", "prompt": "为什么青藏高原“太阳辐射强、气温却低”？", "set": "概念辨析", "subject": "地理", "tags": ["青藏高原", "28题错题"]}, {"answer": "病毒无细胞结构（只有蛋白质外壳+核酸）；蓝藻是原核细胞生物，有细胞结构（无核膜、无叶绿体）。", "explain": "21-(1)她疑似写成“无细胞结构”得0分——题干问的是有细胞结构的生物，别把病毒和蓝藻搞反。", "id": "con-09", "prompt": "病毒有细胞结构吗？蓝藻呢？", "set": "概念辨析", "subject": "生物", "tags": ["细胞", "21题错题"]}, {"answer": "有无以核膜为界限的细胞核。有→真核细胞，无→原核细胞（如细菌、蓝藻）。", "explain": "21-(2)她这个答对了。根本标准只有一个：核膜。", "id": "con-10", "prompt": "区分原核细胞和真核细胞的根本标准是什么？", "set": "概念辨析", "subject": "生物", "tags": ["细胞"]}, {"answer": "蓝藻含有藻蓝素和叶绿素，能进行光合作用，但没有叶绿体（原核生物没有叶绿体、线粒体等复杂细胞器）。", "explain": "21-(3)她写成“叶绿体”得0分——典型易错点：有叶绿素≠有叶绿体。", "id": "con-11", "prompt": "蓝藻含有什么色素？有叶绿体吗？", "set": "概念辨析", "subject": "生物", "tags": ["蓝藻", "21题错题"]}, {"answer": "自由水：游离态，可自由流动，是良好溶剂、参与化学反应、运输物质；结合水：与细胞内其他物质结合，是细胞结构的重要组成成分。代谢越旺盛，自由水与结合水的比值越高。", "explain": "22题连丢6分：自由水功能（良好溶剂）没写出来。记住：自由水管“活”（代谢），结合水管“结构”。", "id": "con-12", "prompt": "自由水和结合水有什么区别？", "set": "概念辨析", "subject": "生物", "tags": ["水", "22题错题"]}, {"answer": "①脱水数＝氨基酸数－肽链数；②蛋白质相对分子质量＝氨基酸总分子质量－18×脱水数；③一条肽链至少含1个游离氨基和1个游离羧基。", "explain": "23题她脱水数直接写51（氨基酸总数），正确是51-2=49；分子量882 vs 888漏项。这三公式默到条件反射。", "id": "con-13", "prompt": "蛋白质计算三公式", "set": "概念辨析", "subject": "生物", "tags": ["蛋白质", "23题错题", "公式"]}, {"answer": "中心碳原子上连接：一个氨基（-NH2）、一个羧基（-COOH）、一个氢原子（-H）、一个R基。结构式：H2N—C(R)(H)—COOH。", "explain": "23-(1)她用文字描述代替画图得0分——题目要求画图就必须画，文字描述不给分。亲手画50遍。", "id": "con-14", "prompt": "画出氨基酸的结构通式", "set": "概念辨析", "subject": "生物", "tags": ["氨基酸", "23题错题"]}, {"answer": "条件：水浴加热（50-65℃）。现象：出现砖红色沉淀。", "explain": "24-(1)她写“没有加热”得0分——“水浴”是关键限定词，直接加热不行。实验题先圈限定词。", "id": "con-15", "prompt": "斐林试剂检测还原糖的关键条件和现象是什么？", "set": "概念辨析", "subject": "生物", "tags": ["实验", "24题错题"]}, {"answer": "不能。Although本身已表转折，再加but重复。改法：Although he is tired, he keeps working. 或 He is tired, but he keeps working.", "explain": "作文硬伤第1条：Although play computer games can…, but it…——although和but连用是典型中式错误，见到就改。", "id": "con-16", "prompt": "Although和but能连用吗？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "连词"]}, {"answer": "不可数。a piece of advice（一则建议），不能说advices。", "explain": "作文：follow my advices→follow my advice。不可数名词没有复数形式。", "id": "con-17", "prompt": "advice可数吗？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "名词"]}, {"answer": "不对。a是单数冠词，后面必须跟单数：it is not a good thing。单复数必须一致：a thing / good things。", "explain": "作文硬伤：a good things——冠词a和复数things打架。写完检查：a/an后面一定是单数。", "id": "con-18", "prompt": "it is not a good things对吗？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "单复数"]}, {"answer": "stop doing：停止正在做的事（Stop playing games.）；stop to do：停下来去做另一件事。forget doing：忘记做过的事；forget to do：忘记去做（还没做）。", "explain": "作文：stop play→stop playing；don't forget do→don't forget to do。先判断“这件事做没做”，再选doing/to do。", "id": "con-19", "prompt": "stop doing和stop to do有什么区别？forget呢？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "作文", "非谓语"]}, {"answer": "跟名词：have confidence in sb/sth（对……有信心）。confident是形容词（be confident of/about），confidence是名词。", "explain": "完成句子66题：have confidence in后面写了confident（形容词）得0分。in是介词，后面只能跟名词/动名词。", "id": "con-20", "prompt": "have confidence in后面跟什么词形？", "set": "概念辨析", "subject": "英语", "tags": ["英语", "词形"]}, {"answer": "have confidence in", "explain": "66题错：写了confident（形容词）。in是介词，后面跟名词confidence。整句：We should have confidence in ourselves.", "id": "eng-01", "prompt": "have ______ in（对……有信心）", "set": "词句急救", "subject": "英语", "tags": ["词形", "完成句子"]}, {"answer": "confusing", "explain": "67题0分。-ing形容词修饰物（令人……的），-ed形容词修饰人（感到……的）：confusing movie / confused person。", "id": "eng-02", "prompt": "The movie is ______（令人困惑的）", "set": "词句急救", "subject": "英语", "tags": ["形容词", "完成句子"]}, {"answer": "extremely", "explain": "68题0分。副词修饰形容词/副词：extremely fast。extreme是形容词，不能直接修饰fast。", "id": "eng-03", "prompt": "He runs ______（极其）fast", "set": "词句急救", "subject": "英语", "tags": ["副词", "完成句子"]}, {"answer": "be addicted to", "explain": "72题0分，目标短语直接不会。addicted是形容词：be addicted to sth/doing sth（沉迷于……）。", "id": "eng-04", "prompt": "be ______ to games（沉迷于游戏）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "other than", "explain": "75题0分。other than＝除了……之外。注意than的拼写。", "id": "eng-05", "prompt": "______ than watching TV（除了看电视之外）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "clean up", "explain": "73题部分给分。clean up＝打扫干净，up是副词不是介词。", "id": "eng-06", "prompt": "______ up the room（打扫房间）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "take control of / took control of", "explain": "74题部分给分。take control of＝控制、接管，注意时态用took。", "id": "eng-07", "prompt": "______ control of the company（接管公司）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "concentrate on / focus on", "explain": "76题部分给分。concentrate on＝focus on＝专注于，后面跟名词/动名词。", "id": "eng-08", "prompt": "______ on your study（专注于学习）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "leave alone", "explain": "70题全对。leave sb alone＝别打扰某人，让某人独自待着。", "id": "eng-09", "prompt": "leave the baby ______（别管婴儿，让他自己待着）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "look forward to", "explain": "71题全对。look forward to中to是介词，后面跟名词/动名词：look forward to hearing from you。", "id": "eng-10", "prompt": "look ______ to hearing from you（期待收到你的来信）", "set": "词句急救", "subject": "英语", "tags": ["短语", "完成句子"]}, {"answer": "to reduce", "explain": "57题错写成to surprised。不定式to do表目的，后面必须跟动词原形：to reduce（为了减少）。", "id": "eng-11", "prompt": "______ reduce stress, he runs daily.（为了减压）", "set": "词句急救", "subject": "英语", "tags": ["不定式", "语法填空"]}, {"answer": "easier", "explain": "59题未写出完整形式。easy→easier，比较级变化：y变i加er。", "id": "eng-12", "prompt": "This book is ______（更容易）than that one", "set": "词句急救", "subject": "英语", "tags": ["比较级", "语法填空"]}, {"answer": "the", "explain": "63题0分。特指双方都知道的人/物用the：the children＝那些孩子们。", "id": "eng-13", "prompt": "______ children are playing there.（那些孩子，特指）", "set": "词句急救", "subject": "英语", "tags": ["冠词", "语法填空"]}, {"answer": "aged", "explain": "64题0分。aged是age的过去分词作定语：children aged 5-10＝5到10岁的孩子们。", "id": "eng-14", "prompt": "______ children aged 5-10（5-10岁的孩子们）", "set": "词句急救", "subject": "英语", "tags": ["分词", "语法填空"]}, {"answer": "For", "explain": "56题错写成at。句首表对象/范围用For：For children, …＝对于孩子们来说。", "id": "eng-15", "prompt": "______ children, playing outside is fun.（对于孩子们来说）", "set": "词句急救", "subject": "英语", "tags": ["介词", "语法填空"]}]};
